/* 西电811 信号题库：课后题 + 考研真题 + 期末真题 */
window.PRO_BANK_SS={"chapters":[{"id":"ss-intro","area":"信号","name":"信号与系统的基本概念","short":"基本概念","weight":8,"rule":"mixed"},{"id":"ss-cont-time","area":"信号","name":"连续系统的时域分析","short":"连续时域","weight":10,"rule":"mixed"},{"id":"ss-disc-time","area":"信号","name":"离散系统的时域分析","short":"离散时域","weight":10,"rule":"mixed"},{"id":"ss-freq","area":"信号","name":"连续系统的频域分析","short":"频域","weight":12,"rule":"mixed"},{"id":"ss-sdomain","area":"信号","name":"连续系统的复频域分析（s 域）","short":"s 域","weight":12,"rule":"mixed"},{"id":"ss-zdomain","area":"信号","name":"离散系统的 z 域分析","short":"z 域","weight":10,"rule":"mixed"},{"id":"ss-sysfunc","area":"信号","name":"系统函数","short":"系统函数","weight":8,"rule":"mixed"},{"id":"ss-state","area":"信号","name":"系统的状态变量分析","short":"状态变量","weight":5,"rule":"mixed"}],"questions":[{"id":"p24","ch":"ss-intro","qt":"选择","pts":5,"t":"课后题","src":"吴大正4版","q":"单位冲激函数 δ(t) 与单位阶跃函数 u(t) 的关系是：","o":["A. δ(t) = du(t)/dt","B. u(t) = dδ(t)/dt","C. δ(t) = ∫u(t)dt","D. 两者没有关系"],"a":"A","s":"δ(t) 是 u(t) 的导数，即 δ(t) = du(t)/dt。"},{"id":"p25","ch":"ss-intro","qt":"填空","pts":5,"t":"课后题","src":"吴大正4版","q":"冲激函数的取样性质：∫ f(t)·δ(t−t₀) dt = ?","a":"f(t₀)","s":"δ(t−t₀) 把 f(t) 在 t₀ 处的值筛出来。"},{"id":"p26","ch":"ss-intro","qt":"填空","pts":5,"t":"课后题","src":"吴大正4版","q":"化简：f(t)·δ(t) = ?","a":"f(0)·δ(t)","s":"冲激函数只在 t=0 处非零，相乘时 f(t) 取 f(0)。"},{"id":"p27","ch":"ss-intro","qt":"选择","pts":5,"t":"课后题","src":"吴大正4版","q":"系统 y(t) = t·f(t) 的线性与时变特性是：","o":["A. 线性时不变","B. 线性时变","C. 非线性时不变","D. 非线性时变"],"a":"B","s":"满足叠加性和齐次性（线性）；系统函数含 t，激励时移响应不同（时变）。"},{"id":"p28","ch":"ss-cont-time","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"计算卷积：u(t) * u(t)。","a":"t·u(t)","s":"u(t)*u(t) = ∫₀ᵗ dτ = t（t≥0），写作 t·u(t)。"},{"id":"p29","ch":"ss-cont-time","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"计算卷积：e^(−2t)u(t) * e^(−2t)u(t)。","a":"t·e^(−2t)·u(t)","s":"∫₀ᵗ e^(−2τ)·e^(−2(t−τ)) dτ = e^(−2t)·∫₀ᵗ dτ = t·e^(−2t)。"},{"id":"p30","ch":"ss-cont-time","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"LTI 系统 y″ + 3y′ + 2y = f(t)，求其冲激响应 h(t)。","a":"h(t) = (e^(−t) − e^(−2t))·u(t)","s":"特征方程 r²+3r+2=0，根 −1、−2。h(0₊)=0，h′(0₊)=1，解得 h(t)=(e^(−t)−e^(−2t))u(t)。"},{"id":"p31","ch":"ss-cont-time","qt":"填空","pts":5,"t":"课后题","src":"吴大正4版","q":"零输入响应由什么决定？","a":"仅由系统初始状态决定（与激励无关）","s":"零输入响应是初始状态引起的响应，激励为零。"},{"id":"p32","ch":"ss-disc-time","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"计算卷积和：u(n) * u(n)。","a":"(n+1)·u(n)","s":"u(n)*u(n) = Σₖ₌₀ⁿ 1 = n+1（n≥0）。"},{"id":"p33","ch":"ss-disc-time","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"LTI 离散系统 y(n) − 0.5y(n−1) = x(n)，求单位序列响应 h(n)。","a":"h(n) = (0.5)ⁿ·u(n)","s":"零状态且 x(n)=δ(n) 时迭代：h(0)=1，h(n)=0.5h(n−1)，得 h(n)=(0.5)ⁿu(n)。"},{"id":"p34","ch":"ss-disc-time","qt":"填空","pts":5,"t":"课后题","src":"吴大正4版","q":"单位序列 δ(n) 与阶跃序列 u(n) 的关系：δ(n) = ?","a":"u(n) − u(n−1)","s":"δ(n) 是 u(n) 的一阶差分。"},{"id":"p35","ch":"ss-freq","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"求 e^(−at)·u(t)（a>0）的傅里叶变换。","a":"1/(a + jω)","s":"F(jω) = ∫₀^∞ e^(−at)e^(−jωt)dt = 1/(a+jω)。"},{"id":"p36","ch":"ss-freq","qt":"填空","pts":5,"t":"课后题","src":"吴大正4版","q":"傅里叶变换的时移性质：f(t−t₀) ↔ ?","a":"F(jω)·e^(−jωt₀)","s":"时移对应频域乘以 e^(−jωt₀)。"},{"id":"p37","ch":"ss-freq","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"信号最高频率 f_m = 4kHz，按取样定理求奈奎斯特取样频率。","a":"8kHz","s":"奈奎斯特频率 f_s = 2f_m = 8kHz，取样间隔 T ≤ 1/(2f_m) = 0.125ms。"},{"id":"p38","ch":"ss-freq","qt":"选择","pts":5,"t":"课后题","src":"吴大正4版","q":"线性系统无失真传输的条件是：","o":["A. H(jω) = K·e^(−jωt₀)（幅度为常数，相位线性）","B. H(jω) = K（常数）","C. 幅度任意，相位为常数","D. 系统带宽无穷大"],"a":"A","s":"无失真要求幅频特性为常数、相频特性为过原点的直线，即 H(jω)=Ke^(−jωt₀)。"},{"id":"p39","ch":"ss-sdomain","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"求 e^(−3t)·u(t) 的单边拉普拉斯变换。","a":"1/(s+3)，Re(s) > −3","s":"L[e^(−at)u(t)] = 1/(s+a)，收敛域 Re(s) > −3。"},{"id":"p40","ch":"ss-sdomain","qt":"填空","pts":5,"t":"课后题","src":"吴大正4版","q":"拉普拉斯变换的初值定理：f(0₊) = ?","a":"lim(s→∞) s·F(s)","s":"f(0₊) = lim(s→∞) sF(s)，要求 F(s) 为真分式。"},{"id":"p41","ch":"ss-sdomain","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"零初始条件下解 y″ + 5y′ + 6y = e^(−t)·u(t)，求 y(t)。","a":"y(t) = (0.5e^(−t) − e^(−2t) + 0.5e^(−3t))·u(t)","s":"Y(s)=1/[(s+1)(s+2)(s+3)]，部分分式展开：A=0.5（s=−1），B=−1（s=−2），C=0.5（s=−3），反变换得 y(t)。"},{"id":"p42","ch":"ss-sdomain","qt":"填空","pts":5,"t":"课后题","src":"吴大正4版","q":"零初始状态下，电感 L 在 s 域中的运算阻抗为？","a":"sL","s":"电感电压 U(s) = sL·I(s) − Li(0₋)，零初始时为 sL。"},{"id":"p43","ch":"ss-zdomain","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"求 aⁿ·u(n) 的 z 变换及其收敛域。","a":"z/(z−a)，|z| > |a|","s":"Z[aⁿu(n)] = Σaⁿz⁻ⁿ = 1/(1−az⁻¹) = z/(z−a)，收敛域 |z|>|a|。"},{"id":"p44","ch":"ss-zdomain","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"求 F(z) = z/(z−0.5)（|z|>0.5）的逆 z 变换。","a":"f(n) = (0.5)ⁿ·u(n)","s":"由常用变换对 z/(z−a) ↔ aⁿu(n) 直接得 f(n)=(0.5)ⁿu(n)。"},{"id":"p45","ch":"ss-zdomain","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"用 z 域法解差分方程 y(n) − 0.5y(n−1) = x(n)，其中 x(n)=u(n)，y(−1)=0。","a":"y(n) = (2 − 0.5ⁿ)·u(n)","s":"Y(z)=1/[(1−z⁻¹)(1−0.5z⁻¹)]，部分分式：A=2（z⁻¹=1 处），B=−1（z⁻¹=2 处），反变换 y(n)=(2−0.5ⁿ)u(n)。"},{"id":"p46","ch":"ss-sysfunc","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"因果系统 H(s) = 1/(s+2)，判断其稳定性。","a":"稳定（极点 s=−2 在左半平面）","s":"因果连续系统稳定 ⟺ 所有极点在 s 左半开平面。"},{"id":"p47","ch":"ss-sysfunc","qt":"选择","pts":5,"t":"课后题","src":"吴大正4版","q":"因果连续 LTI 系统稳定的充要条件是：","o":["A. 所有极点在 s 左半开平面","B. 所有极点在 s 右半平面","C. 极点全在虚轴上","D. 系统函数分子阶次高于分母"],"a":"A","s":"因果连续系统稳定 ⟺ 系统函数所有极点位于左半开平面。"},{"id":"p48","ch":"ss-sysfunc","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"离散系统 H(z) = z/(z−2)，判断因果系统的稳定性。","a":"不稳定（极点 z=2 在单位圆外）","s":"因果离散系统稳定 ⟺ 所有极点在单位圆内；|2|>1，不稳定。"},{"id":"p49","ch":"ss-state","qt":"解答","pts":10,"t":"课后题","src":"吴大正4版","q":"对系统 y″ + 3y′ + 2y = f(t) 建立状态方程与输出方程。","a":"取 x₁=y，x₂=y′：x₁′=x₂；x₂′=−2x₁−3x₂+f；输出 y=x₁","s":"令状态变量 x₁=y、x₂=y′，代入微分方程整理即得状态方程与输出方程。"},{"id":"pb01","ch":"ss-intro","qt":"选择","pts":5,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"判断系统 y(t) = t·f(t) 的线性性与时不变性（f 为输入，y 为输出）。","a":"线性、时变。","s":"对任意常数 a、b：a·f1(t)+b·f2(t) 对应的输出为 t[a·f1(t)+b·f2(t)] = a·y1(t)+b·y2(t)，故线性。若输入延时 t0，输出为 t·f(t-t0)，而 y(t-t0)=(t-t0)·f(t-t0)，两者不等，故时变（系统中含显式 t 因子）。"},{"id":"pb02","ch":"ss-intro","qt":"选择","pts":5,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"判断系统 y(n) = f(n)·f(n-1) 的线性性与时不变性。","a":"非线性、时不变。","s":"输入 2f(n) 时输出为 4f(n)f(n-1) ≠ 2y(n)，不满足齐次性，非线性。系统不显含 n，输入移位输出随之同样移位，时不变。"},{"id":"pb03","ch":"ss-intro","qt":"解答","pts":10,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"已知 f(t) = u(t+1) - u(t-1)（门函数，宽 2、高 1），画出 f(1-2t) 的波形，并说明其幅度、宽度与所在区间。","a":"幅度 1、宽度 1 的门函数，位于 0 < t ≤ 1（端点处取跳变）。","s":"三步：f(t) → f(-t)（反折，仍为 [-1,1] 上宽 2 的门）→ f(1-t)=f(-(t-1))（右移 1，得 [0,2] 上宽 2 的门）→ f(1-2t)（横轴压缩 2 倍，得 (0,1] 上宽 1 的门）。直接验证：f(1-2t)=u(2-2t)-u(-2t)，在 0<t≤1 时为 1，其余为 0。"},{"id":"pb04","ch":"ss-cont-time","qt":"解答","pts":10,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"f1(t) = u(t) - u(t-2)，f2(t) = u(t) - u(t-1)，求卷积 y(t) = f1(t)*f2(t)。","a":"y(t) = t·[u(t)-u(t-1)] + (2-t)·[u(t-1)-u(t-2)]（即高度 1、底宽 2、顶点在 t=1 的三角波），其余为 0。","s":"两个门函数卷积为三角波：0≤t<1 时 y=t；1≤t<2 时 y=2-t；其余为 0。可用定义 y(t)=∫f1(τ)f2(t-τ)dτ 分段积分验证。"},{"id":"pb05","ch":"ss-cont-time","qt":"解答","pts":10,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"LTI 系统微分方程 y″(t)+3y′(t)+2y(t)=f(t)，f(t)=u(t)，y(0⁻)=y′(0⁻)=0。求零状态响应 y(t)。","a":"y(t) = (1/2 - e^(-t) + (1/2)e^(-2t))·u(t)。","s":"特征方程 λ²+3λ+2=0，λ=-1,-2。零状态响应 = 齐次解 + 特解：y(t)=C1·e^(-t)+C2·e^(-2t)+1/2。由 y(0)=0、y′(0)=0 得 C1=-1，C2=1/2。"},{"id":"pb06","ch":"ss-freq","qt":"解答","pts":10,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"求信号 f(t) = e^(-2|t|) 的傅里叶变换 F(jω)。","a":"F(jω) = 4/(4 + ω²)。","s":"e^(-a|t|) 的傅里叶变换为 2a/(a²+ω²)，a=2 代入即得。也可按 ∫e^(-2|t|)e^(-jωt)dt 从 -∞ 到 +∞ 直接积分。"},{"id":"pb07","ch":"ss-freq","qt":"解答","pts":10,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"信号 f(t) 的最高频率为 2 kHz，若要不失真取样，求奈奎斯特取样频率 f_s 与最大取样间隔 T_s。","a":"f_s ≥ 4 kHz，T_s ≤ 0.25 ms。","s":"奈奎斯特取样频率 = 2×最高频率 = 4 kHz；取样间隔 T_s = 1/f_s = 0.25 ms。"},{"id":"pb08","ch":"ss-freq","qt":"解答","pts":10,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"写出线性系统无失真传输时系统函数 H(jω) 应满足的条件。","a":"H(jω) = K·e^(-jωt0)（K 为常数幅度增益，t0 为常数延时），即幅频特性为常数、相频特性为过原点直线。","s":"无失真要求输出 y(t)=K·f(t-t0)，取傅里叶变换比较得 H(jω)=K·e^(-jωt0)。"},{"id":"pb09","ch":"ss-sdomain","qt":"解答","pts":10,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"求 f(t) = t·e^(-2t)·u(t) 的单边拉普拉斯变换 F(s) 及收敛域。","a":"F(s) = 1/(s+2)²，收敛域 Re{s} > -2。","s":"由 L{t·u(t)}=1/s² 及 s 域平移性质（e^(-at) 对应 s→s+a），得 F(s)=1/(s+2)²。"},{"id":"pb10","ch":"ss-sdomain","qt":"解答","pts":10,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"系统函数 H(s) = 1/(s²+3s+2)，求冲激响应 h(t)（因果系统）。","a":"h(t) = (e^(-t) - e^(-2t))·u(t)。","s":"H(s)=1/[(s+1)(s+2)] = 1/(s+1) - 1/(s+2)，逐项求逆变换得 e^(-t)u(t) - e^(-2t)u(t)。"},{"id":"pb11","ch":"ss-zdomain","qt":"解答","pts":10,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"求序列 f(n) = aⁿ·u(n)（a 为常数）的 z 变换 F(z) 及收敛域。","a":"F(z) = z/(z-a)，收敛域 |z| > |a|。","s":"等比级数求和：F(z)=Σaⁿz⁻ⁿ=1/(1-a·z⁻¹)=z/(z-a)，要求 |a·z⁻¹|<1 即 |z|>|a|。"},{"id":"pb12","ch":"ss-zdomain","qt":"解答","pts":10,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"差分方程 y(n) - 0.5·y(n-1) = f(n)，f(n)=u(n)，y(-1)=0。用 z 变换求全响应 y(n)。","a":"y(n) = (2 - 0.5ⁿ)·u(n)。","s":"Y(z)[1-0.5z⁻¹]=z/(z-1)，Y(z)=z²/[(z-1)(z-0.5)]。Y(z)/z=z/[(z-1)(z-0.5)]=2/(z-1)-1/(z-0.5)，故 y(n)=2u(n)-0.5ⁿu(n)。"},{"id":"pb13","ch":"ss-sysfunc","qt":"选择","pts":5,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"因果系统 H(s) = (s+2)/(s²+3s+2)，判断其稳定性，并说明理由。","a":"稳定。","s":"H(s)=(s+2)/[(s+1)(s+2)]，零极点对消后 H(s)=1/(s+1)，极点 s=-1 位于 s 左半平面，故系统稳定（零极点对消不改变稳定性判断）。"},{"id":"pb14","ch":"ss-sysfunc","qt":"解答","pts":10,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"信号流图：输入 X 经增益 a 到节点 x1，经增益 b 到节点 x2，经增益 c 到输出 Y；另有回路 x1→x2 增益 d、x2→x1 增益 e（负反馈）。用梅森公式求 H = Y/X。","a":"H = abc/(1+de)。","s":"前向通路 1 条，增益 P1=abc，无不相交回路；回路 L1=-de（负号来自负反馈），Δ=1-L1=1+de，Δ1=1。梅森公式：H=abc/(1+de)。"},{"id":"pb15","ch":"ss-state","qt":"解答","pts":10,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"由微分方程 y″(t)+3y′(t)+2y(t)=f(t) 建立状态方程与输出方程（取 x1=y，x2=y′）。","a":"x1′=x2；x2′ = -2x1 -3x2 + f；输出 y = x1。","s":"令 x1=y、x2=y′，则 x1′=x2；由原方程 y″=-3y′-2y+f 得 x2′=-3x2-2x1+f。写成矩阵形式即可。"},{"id":"pb22","ch":"ss-intro","qt":"解答","pts":10,"t":"课后题","src":"吴大正《信号与线性系统分析》第4版 课后题","q":"利用冲激函数性质计算：∫(-∞,+∞) (t²+1)·δ(t-1) dt 与 ∫(-∞,+∞) t²·δ′(t) dt。","a":"前者 = 2；后者 = 0。","s":"取样性质：∫f(t)δ(t-t0)dt=f(t0)，t0=1 时 t²+1=2。冲激偶性质：∫f(t)δ′(t)dt = -f′(0)；f(t)=t²，f′(t)=2t，f′(0)=0，故结果为 0。"},{"id":"r19-01","seq":1,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"1. 求积分 $\\int_{-\\infty}^{+\\infty}(3-t)\\bigl[\\delta(t-1)+\\delta(t+1)\\bigr]\\,\\mathrm{d}t$ 的值。","img":"pro-img/2019_p01.jpg","a":"0","s":""},{"id":"r19-02","seq":2,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"2. 描述某系统的方程为 $y(t)=f(t)-3f(2t+1)$，其中 $f(t)$ 为激励，则该系统为（1）____（线性/非线性）系统、（2）____（时变/时不变）系统。","img":"pro-img/2019_p01.jpg","a":"（1）线性；（2）时变","s":""},{"id":"r19-03","seq":3,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"3. 已知 $f(t)$ 波形如图 1-3 所示，$g(t)=f'(t)$，画出 $g(t)$ 和 $g(2t-1)$ 的波形。[图1-3：$f(t)$ 分段波形（见图）]","img":"pro-img/2019_p01.jpg","a":"（作图题：$g(t)=f'(t)$ 与 $g(2t-1)$ 的波形，见图）","s":"平移→尺度变换；求导注意有无 $\\delta(t)$；尺度变换要注意强度的改变。"},{"id":"r19-04","seq":4,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"4. 已知有限频带信号 $f(t)$ 的最高频率为 $f_m$ Hz，若对 $f_1(t)=f(4t)*f(2t)$（$*$ 表示卷积）进行时域采样，使频谱不发生混叠的奈奎斯特频率是（1）____。","img":"pro-img/2019_p02.jpg","a":"$4f_m$ Hz","s":"$f(t)\\to f_m$，$f(4t)\\to 4f_m$，$f(2t)\\to 2f_m$；卷积后最高频率为 $\\min\\{4f_m,2f_m\\}=2f_m$，故奈奎斯特采样频率为 $2\\times2f_m=4f_m$ Hz。"},{"id":"r19-05","seq":5,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"5. 已知 $f(t)$ 的傅里叶变换 $\\mathcal{F}[f(t)]=F(j\\omega)$，$f_1(t)=f(1-5t)e^{j2t}$，求 $\\mathcal{F}[f_1(t)]=$____。","img":"pro-img/2019_p02.jpg","a":"$\\dfrac{1}{5}F\\left(-j\\dfrac{\\omega-2}{5}\\right)e^{-j\\frac{\\omega-2}{5}}$","s":"$f(t)\\leftrightarrow F(j\\omega)$，$f(t+1)\\leftrightarrow F(j\\omega)e^{j\\omega}$；由尺度变换与反折，$f(-5t+1)\\leftrightarrow\\dfrac{1}{5}F\\left(-j\\dfrac{\\omega}{5}\\right)e^{-j\\frac{\\omega}{5}}$；再频移 $e^{j2t}$ 得 $F_1(j\\omega)=\\dfrac{1}{5}F\\left(-j\\dfrac{\\omega-2}{5}\\right)e^{-j\\frac{\\omega-2}{5}}$。"},{"id":"r19-06","seq":6,"part":"信号","qt":"填空","pts":4,"ch":"ss-cont-time","q":"6. 描述某 LTI 系统的微分方程为 $y''(t)+5y'(t)+6y(t)=f'(t)+2f(t)$，已知输入信号 $f(t)=e^{-t}\\varepsilon(t)$，$y(0_+)=4$，$y'(0_+)=2$，求 $y'(0_-)=$____。","img":"pro-img/2019_p02.jpg","a":"1","s":"$f'(t)=\\delta(t)-e^{-t}\\varepsilon(t)$，故 $f'(t)+2f(t)=\\delta(t)+e^{-t}\\varepsilon(t)$；右端 $\\delta(t)$ 系数为 $1$，故 $y'(0_+)-y'(0_-)=1$，得 $y'(0_-)=2-1=1$。"},{"id":"r19-07","seq":7,"part":"信号","qt":"填空","pts":4,"ch":"ss-sdomain","q":"7. 已知某系统的系统函数 $H(s)=\\dfrac{3s+9}{s^2+6s+8}$，描述该系统的微分方程是（1）____。","img":"pro-img/2019_p02.jpg","a":"$y''(t)+6y'(t)+8y(t)=3f'(t)+9f(t)$","s":"$H(s)=\\dfrac{Y(s)}{F(s)}=\\dfrac{3s+9}{s^2+6s+8}$，即 $(s^2+6s+8)Y(s)=(3s+9)F(s)$，故 $y''(t)+6y'(t)+8y(t)=3f'(t)+9f(t)$。"},{"id":"r19-08","seq":8,"part":"信号","qt":"填空","pts":4,"ch":"ss-zdomain","q":"8. 已知 $f(k)$ 的 z 变换 $F(z)=\\dfrac{z^2}{(z+1)(z-2)}$，其收敛域为（1）____时，$f(k)$ 是因果序列，其原序列 $f(k)$ 为（2）____。","img":"pro-img/2019_p02.jpg","a":"（1）$|z|>2$；（2）$f(k)=\\dfrac{1}{3}(-1)^k+\\dfrac{2}{3}2^k$，$k\\geq0$","s":"$\\dfrac{F(z)}{z}=\\dfrac{z}{(z+1)(z-2)}=\\dfrac{1/3}{z+1}+\\dfrac{2/3}{z-2}$，故 $F(z)=\\dfrac{1}{3}\\dfrac{z}{z+1}+\\dfrac{2}{3}\\dfrac{z}{z-2}$；收敛域 $|z|>2$ 时（因果），$f(k)=\\left[\\dfrac{1}{3}(-1)^k+\\dfrac{2}{3}2^k\\right]\\varepsilon(k)$。"},{"id":"r19-09","seq":9,"part":"信号","qt":"解答","pts":11,"ch":"ss-freq","q":"1.（11分）一个由乘法器和理想低通滤波器组成的系统如图 2-1 所示。[图2-1：$f(t)$ 与 $s(t)$ 经乘法器得 $f_s(t)=f(t)s(t)$，再经理想低通滤波器 $H(j\\omega)$ 输出 $y(t)$] 已知低通滤波器的频率特性 $H(j\\omega)=\\begin{cases}1,&|\\omega|<2\\ \\mathrm{rad/s}\\\\0,&|\\omega|>2\\ \\mathrm{rad/s}\\end{cases}$，信号 $f(t)=\\dfrac{\\sin(2t)}{t}$，$s(t)=\\cos(3t)$；$f(t)$、$s(t)$ 和 $f_s(t)$ 的傅里叶变换分别记为 $F(j\\omega)$、$S(j\\omega)$ 和 $F_s(j\\omega)$。(1) 试求 $F(j\\omega)$、$S(j\\omega)$ 和 $F_s(j\\omega)$；(2) 试求系统的输出 $y(t)$。","img":"pro-img/2019_p02.jpg","a":"(1) $F(j\\omega)=\\pi g_4(\\omega)$（$|\\omega|<2$ 为 $\\pi$，$|\\omega|>2$ 为 $0$），$S(j\\omega)=\\pi[\\delta(\\omega+3)+\\delta(\\omega-3)]$，$F_s(j\\omega)=\\dfrac{\\pi}{2}[g_4(\\omega+3)+g_4(\\omega-3)]$；(2) $y(t)=\\dfrac{1}{2}\\mathrm{Sa}\\!\\left(\\dfrac{t}{2}\\right)\\cos\\!\\left(\\dfrac{3}{2}t\\right)=\\dfrac{\\sin(t/2)\\cos(3t/2)}{t}$。","s":"$f(t)=\\dfrac{\\sin2t}{t}=2\\,\\mathrm{Sa}(2t)$，由对称性 $F(j\\omega)=\\pi g_4(\\omega)$；$s(t)=\\cos3t$，$S(j\\omega)=\\pi[\\delta(\\omega+3)+\\delta(\\omega-3)]$；$F_s(j\\omega)=\\dfrac{1}{2\\pi}F(j\\omega)*S(j\\omega)=\\dfrac{\\pi}{2}[g_4(\\omega+3)+g_4(\\omega-3)]$。经低通滤波得 $Y(j\\omega)=\\dfrac{\\pi}{2}[g_1(\\omega+\\tfrac32)+g_1(\\omega-\\tfrac32)]$，故 $y(t)=\\dfrac12\\mathrm{Sa}\\!\\left(\\dfrac t2\\right)\\cos\\!\\left(\\dfrac32 t\\right)$。"},{"id":"r19-10","seq":10,"part":"信号","qt":"解答","pts":11,"ch":"ss-zdomain","q":"2.（11分）描述某线性时不变系统的 k 域框图如图 2-2 所示。[图2-2：z 域框图，输入 $F(z)$、输出 $Y(z)$，含中间变量 $X(z)$，反馈支路 $0.25z^{-2}$，前向与反馈系数见图] (1) 求系统函数 $H(z)$；(2) 确定其收敛域，分析其系统因果稳定性；(3) 对因果稳定系统写出其频率响应函数表达式；(4) 若激励为 $f(k)=[1+\\cos(\\pi k)]\\varepsilon(k)$，求系统的稳态响应。","img":"pro-img/2019_p03.jpg","a":"(1) $H(z)=\\dfrac{3z^2-2}{z^2+z+0.25}$；(2) 极点 $z=-0.5$（二重），收敛域 $|z|>0.5$ 时系统因果稳定（含单位圆），$|z|<0.5$ 时非因果不稳定；(3) $H(e^{j\\omega})=\\dfrac{3e^{j2\\omega}-2}{e^{j2\\omega}+e^{j\\omega}+0.25}$；(4) $y_s(k)=\\dfrac{4}{9}+4\\cos(\\pi k)$。","s":"$X(z)=-z^{-1}X(z)-0.25z^{-2}X(z)+F(z)$，即 $(1+z^{-1}+0.25z^{-2})X(z)=F(z)$，$Y(z)=(3-2z^{-2})X(z)$，故 $H(z)=\\dfrac{3-2z^{-2}}{1+z^{-1}+0.25z^{-2}}=\\dfrac{3z^2-2}{z^2+z+0.25}$。极点 $z=-0.5$（二重），收敛域 $|z|>0.5$ 含单位圆，因果稳定。$H(e^{j0})=\\dfrac{1}{2.25}=\\dfrac49$，$H(e^{j\\pi})=\\dfrac{1}{0.25}=4$，故 $y_s(k)=\\dfrac49+4\\cos(\\pi k)$。"},{"id":"r19-11","seq":11,"part":"信号","qt":"解答","pts":11,"ch":"ss-sdomain","q":"3.（11分）某线性时不变因果连续系统框图如图 2-3 所示。[图2-3：连续系统框图，含积分器与增益 $K$ 及反馈支路（具体拓扑见图）] (1) 画出系统的 s 域流图；(2) 写出系统函数 $H(s)$ 及其零点和极点；(3) 当 $K$ 满足什么条件时，系统稳定。","img":"pro-img/2019_p03.jpg","a":"(1) s 域流图（略，见图）；(2) $H(s)=\\dfrac{Ks}{s^2+(4-K)s+3}$，零点 $s=0$，极点 $s=\\dfrac{(K-4)\\pm\\sqrt{(K-4)^2-12}}{2}$；(3) 当 $4-K>0$ 即 $K<4$ 时，系统稳定。","s":"由梅森公式得 $H(s)=\\dfrac{Ks}{s^2+(4-K)s+3}$；令分子、分母分别为 $0$，得零点 $s=0$，极点 $s=\\dfrac{(K-4)\\pm\\sqrt{(K-4)^2-12}}{2}$；由罗斯准则，$4-K>0$ 即 $K<4$ 时极点位于左半平面，系统稳定。"},{"id":"r19-12","seq":12,"part":"信号","qt":"解答","pts":10,"ch":"ss-state","q":"4.（10分）某离散系统的信号流图如图 2-4 所示，写出以 $x_1(k)$、$x_2(k)$、$x_3(k)$ 为状态变量的状态方程和输出方程。[图2-4：离散信号流图，含三个延时支路与增益 $+2$、$-3$ 等（见图）]","img":"pro-img/2019_p04.jpg","a":"状态方程 $\\begin{bmatrix}x_1(k+1)\\\\x_2(k+1)\\\\x_3(k+1)\\end{bmatrix}=\\begin{bmatrix}2&-3&0\\\\4&-6&0\\\\4&-6&1\\end{bmatrix}\\begin{bmatrix}x_1(k)\\\\x_2(k)\\\\x_3(k)\\end{bmatrix}+\\begin{bmatrix}1\\\\1\\\\1\\end{bmatrix}f(k)$；输出方程 $y(k)=\\begin{bmatrix}1&-2&0\\end{bmatrix}\\begin{bmatrix}x_1(k)\\\\x_2(k)\\\\x_3(k)\\end{bmatrix}$。","s":"由流图列节点方程：$p(k)=f(k)-3x_2(k)$，$x_1(k+1)=2x_1(k)+p(k)$；$x_2(k+1)+3x_2(k)=x_1(k+1)+2x_1(k)$；$x_3(k+1)-x_3(k)=x_2(k+1)$；$y(k)=x_1(k)-2x_2(k)$。整理即得状态方程与输出方程。"},{"id":"r20-01","seq":1,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"描述某系统的差分方程为 $y(k)+(k-1)y(k-1)=f(k)$，其中 $f(k)$ 为激励，$y$ 为全响应，那么该系统是____（线性/非线性）____（时变/时不变）系统。","img":"pro-img/2020_p01.jpg","a":"线性，时变","s":"$y(k-1)$ 前的系数为 $k-1$（是 $k$ 的函数），违背时不变性；方程中无非线性运算项，故为线性系统。"},{"id":"r20-02","seq":2,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"设 $f(t)=\\int_{-\\infty}^{t}2(2-3x)\\,\\delta(x-2)\\,\\mathrm{d}x+2\\delta(t)+3\\varepsilon(t)$，则 $f(t)=$____。","img":"pro-img/2020_p01.jpg","a":"$2\\delta(t)+3\\varepsilon(t)-8\\varepsilon(t-2)$","s":"$\\int_{-\\infty}^{t}2(2-3x)\\delta(x-2)\\,\\mathrm{d}x=2(2-3x)\\big|_{x=2}\\varepsilon(t-2)=-8\\varepsilon(t-2)$，故 $f(t)=2\\delta(t)+3\\varepsilon(t)-8\\varepsilon(t-2)$。"},{"id":"r20-03","seq":3,"part":"信号","qt":"填空","pts":4,"ch":"ss-cont-time","q":"信号 $f_1(t)$ 和 $f_2(t)$ 如图1-3所示，$f(t)=f_1(1-t)*f_2(t)$，则 $f(0)=$____。[图1-3：$f_1(t)$、$f_2(t)$ 波形，标注含 0.5、-2 等值，见图]","img":"pro-img/2020_p01.jpg","a":"$f(0)=1$","s":""},{"id":"r20-04","seq":4,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"已知有限频带信号 $f(t)$ 的最高频率为 $f_m$ Hz，若对 $f(t)\\cdot f(1-t)$ 进行时域采样，为使频谱不发生混叠，奈奎斯特频率是____。","img":"pro-img/2020_p02.jpg","a":"$4f_m$ Hz","s":"$f(t)$ 与 $f(1-t)$ 的最高频率均为 $f_m$，二者相乘后最高频率为 $2f_m$，故奈奎斯特频率为 $2\\times 2f_m=4f_m$ Hz。"},{"id":"r20-05","seq":5,"part":"信号","qt":"填空","pts":4,"ch":"ss-cont-time","q":"描述某 LTI 系统的微分方程为 $y''(t)+3y'(t)+2y(t)=f(t)$。已知输入信号 $f(t)=e^{-t}\\varepsilon(t)$，$y(0_+)=2$，$y'(0_+)=3$，求 $y'(0_-)=$____。","img":"pro-img/2020_p02.jpg","a":"$2$","s":"$f(t)=e^{-t}\\varepsilon(t)$，$f'(t)=\\delta(t)-e^{-t}\\varepsilon(t)$；由初值突变关系 $y'(0_+)-y'(0_-)=1$，得 $y'(0_-)=y'(0_+)-1=3-1=2$。"},{"id":"r20-06","seq":6,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"已知频谱密度函数 $F(j\\omega)=[\\varepsilon(\\omega)-\\varepsilon(\\omega-2)]e^{-j2\\omega}$，式中 $\\varepsilon(\\omega)$ 为频域单位阶跃函数，则原函数 $f(t)=$____。","img":"pro-img/2020_p02.jpg","a":"$\\dfrac{\\sin(t-2)}{\\pi(t-2)}$","s":"$\\varepsilon(\\omega)-\\varepsilon(\\omega-2)=g_2(\\omega-1)$，$g_2(\\omega)\\leftrightarrow \\dfrac{\\sin t}{\\pi t}$，故 $f(t)=\\dfrac{\\sin(t-2)}{\\pi(t-2)}$（含相移 $e^{j(t-2)}$，以答案页写法为准）。"},{"id":"r20-07","seq":7,"part":"信号","qt":"填空","pts":4,"ch":"ss-sdomain","q":"象函数 $F(s)=\\dfrac{e^{-s}}{s(s^2+1)}$ 的单边拉普拉斯逆变换为____。","img":"pro-img/2020_p02.jpg","a":"$[1-\\cos(t-1)]\\varepsilon(t-1)$","s":"$\\dfrac{1}{s(s^2+1)}$ 的逆变换为 $\\varepsilon(t)-\\cos t\\,\\varepsilon(t)=(1-\\cos t)\\varepsilon(t)$，乘以 $e^{-s}$（时移 1）得 $f(t)=[1-\\cos(t-1)]\\varepsilon(t-1)$。"},{"id":"r20-08","seq":8,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"序列和 $\\sum_{i=-\\infty}^{k}\\cos(k-i)\\,\\delta(i-3)=$____。","img":"pro-img/2020_p02.jpg","a":"$\\cos(k-3)\\,\\varepsilon(k-3)$","s":"由 $\\delta(i-3)$ 的筛选性质，仅在 $i=3$ 处取值，故 $\\sum_{i=-\\infty}^{k}\\cos(k-i)\\delta(i-3)=\\cos(k-3)\\varepsilon(k-3)$。"},{"id":"r20-09","seq":9,"part":"信号","qt":"解答","pts":11,"ch":"ss-freq","q":"（11分）如图2-1(a)所示为二次抑制载波振幅调制接收系统。已知输入信号 $f(t)=\\dfrac{\\sin t}{t}$（$-\\infty<t<\\infty$），调制信号 $s(t)=\\cos(1000t)$（$-\\infty<t<\\infty$），低通滤波器的传输函数如图2-1(b)所示，其相位特性为 $\\varphi(\\omega)=0$，试：（1）画出 $f_s(t)$ 和 $F_s(j\\omega)$ 的频谱图；（2）求系统的输出 $y(t)$。[图2-1：两次调制（乘 $s(t)$）与低通滤波器级联框图，低通 $H(j\\omega)=g_2(\\omega)$（门宽 2）]","img":"pro-img/2020_p02.jpg","a":"$F_s(j\\omega)=\\dfrac{1}{2}[g_2(\\omega+1000)+g_2(\\omega-1000)]$，$F_y(j\\omega)=\\dfrac{1}{4}[g_2(\\omega+2000)+2g_2(\\omega)+g_2(\\omega-2000)]$；输出 $y(t)=\\dfrac{\\sin t}{2t}$。","s":"$f(t)=\\dfrac{\\sin t}{t}\\leftrightarrow F(j\\omega)=\\pi g_2(\\omega)$，$s(t)=\\cos(1000t)\\leftrightarrow S(j\\omega)=\\pi[\\delta(\\omega+1000)+\\delta(\\omega-1000)]$。$f_s(t)=f(t)s(t)$，$F_s(j\\omega)=\\dfrac{1}{2\\pi}F*S=\\dfrac{\\pi}{2}[g_2(\\omega+1000)+g_2(\\omega-1000)]$；再乘 $s(t)$ 得 $F_y(j\\omega)=\\dfrac{\\pi}{4}[g_2(\\omega+2000)+2g_2(\\omega)+g_2(\\omega-2000)]$；低通 $H(j\\omega)=g_2(\\omega)$ 只保留中心项，$Y(j\\omega)=\\dfrac{\\pi}{2}g_2(\\omega)$，故 $y(t)=\\dfrac{\\sin t}{2t}$。"},{"id":"r20-10","seq":10,"part":"信号","qt":"解答","pts":10,"ch":"ss-sdomain","q":"（10分）已知系统函数和初态如下：$H(s)=\\dfrac{s+1}{s^2+5s+6}$，$y(0_+)=y'(0_+)=1$。（1）求系统的零输入响应 $y_x(t)$；（2）输入信号 $f(t)=5\\cos t\\,\\varepsilon(t)$，求系统的零状态响应 $y_f(t)$ 和稳态响应。","img":"pro-img/2020_p03.jpg","a":"（1）$y_x(t)=(4e^{-2t}-3e^{-3t})\\varepsilon(t)$；（2）零状态响应 $y_f(t)=(2e^{-2t}-3e^{-3t}+\\cos t)\\varepsilon(t)$，稳态响应 $y_s(t)=\\cos t$。","s":"（1）$y_x(t)$ 满足 $y''+5y'+6y=0$，特征根 $\\lambda=-2,-3$，由 $y_x(0_+)=y(0_+)=1$、$y_x'(0_+)=y'(0_+)=1$ 得 $C_1+C_2=1$、$-2C_1-3C_2=1$，解得 $C_1=4$，$C_2=-3$，故 $y_x(t)=(4e^{-2t}-3e^{-3t})\\varepsilon(t)$。（2）$F(s)=\\dfrac{5s}{s^2+1}$，$Y_f(s)=H(s)F(s)=\\dfrac{s+1}{(s+2)(s+3)}\\cdot\\dfrac{5s}{s^2+1}=\\dfrac{2}{s+2}-\\dfrac{3}{s+3}+\\dfrac{s}{s^2+1}$，故 $y_f(t)=(2e^{-2t}-3e^{-3t}+\\cos t)\\varepsilon(t)$，稳态响应为 $\\cos t$。"},{"id":"r20-11","seq":11,"part":"信号","qt":"解答","pts":11,"ch":"ss-zdomain","q":"（11分）如图2-3所示为离散 LTI 因果系统的信号流图，求：（1）系统函数 $H(z)$；（2）列写输入输出差分方程；（3）判断该系统是否稳定，并给出理由；（4）当输入为 $(0.5)^k\\varepsilon(k)$ 时系统的零状态响应。[图2-3：离散系统信号流图，含反馈支路系数 0.8、0.6]","img":"pro-img/2020_p03.jpg","a":"（1）$H(z)=\\dfrac{1+z^{-1}}{1-1.4z^{-1}+0.48z^{-2}}=\\dfrac{z(z+1)}{(z-0.6)(z-0.8)}$；（2）$y(k)-1.4y(k-1)+0.48y(k-2)=f(k)+f(k-1)$；（3）稳定；（4）$y_f(k)=[25(0.5)^k-48(0.6)^k+24(0.8)^k]\\varepsilon(k)$。","s":"（1）由信号流图得 $H(z)=\\dfrac{Y(z)}{F(z)}=\\dfrac{1+z^{-1}}{1-1.4z^{-1}+0.48z^{-2}}$。（2）对应差分方程 $y(k)-1.4y(k-1)+0.48y(k-2)=f(k)+f(k-1)$。（3）$z^2-1.4z+0.48=(z-0.6)(z-0.8)$，极点均位于单位圆内，且为因果系统，收敛域 $|z|>0.8$ 包含单位圆，故系统稳定。（4）$F(z)=\\dfrac{z}{z-0.5}$，$Y(z)=H(z)F(z)=\\dfrac{z^2(z+1)}{(z-0.5)(z-0.6)(z-0.8)}=\\dfrac{25z}{z-0.5}-\\dfrac{48z}{z-0.6}+\\dfrac{24z}{z-0.8}$，故 $y_f(k)=[25(0.5)^k-48(0.6)^k+24(0.8)^k]\\varepsilon(k)$。"},{"id":"r20-12","seq":12,"part":"信号","qt":"解答","pts":11,"ch":"ss-state","q":"（11分）如图2-4所示为某连续系统的信号流图，写出以 $x_1$ 和 $x_2$ 为状态变量的状态方程和输出方程。[图2-4：连续系统信号流图，含状态变量 $x_1$、$x_2$ 及反馈系数 -3、-3 等，见图]","img":"pro-img/2020_p03.jpg","a":"状态方程：$x_1'=2x_1-x_2$，$x_2'=3x_1-7x_2+f$；输出方程：$y=2x_2$。","s":"由信号流图列写积分器输入端方程得 $\\begin{cases}x_1'=2x_1-x_2\\\\ x_2'=3x_1-7x_2+f\\end{cases}$，输出 $y=2x_2$，即 $y=[0\\ \\ 2]\\begin{bmatrix}x_1\\\\x_2\\end{bmatrix}$。"},{"id":"r21-01","seq":1,"part":"信号","qt":"填空","pts":3,"ch":"ss-intro","q":"1. 计算积分 $\\int_{-\\infty}^{\\infty}\\cos(\\pi t)\\,\\delta'(t+2)\\,\\mathrm{d}t=$ ____。（原文积分式 OCR 不清）","img":"pro-img/2021_p01.jpg","a":"$1+\\dfrac{\\sqrt{3}}{2}$","s":"据答案页：原式含 $\\cos(\\pi t)$ 与 $\\delta'(t+2)$、$\\delta(t)$ 的积分，利用冲激函数及其导数的采样性质，得 $=1+\\dfrac{\\sqrt{3}}{2}$（解析 OCR 残缺，完整步骤见图）。"},{"id":"r21-02","seq":2,"part":"信号","qt":"填空","pts":3,"ch":"ss-intro","q":"2. 描述某连续系统的方程为 $y'(t)+5y(t)=f(t)-4f'(t)$（末项 OCR 原文不清），那么，该系统是____（线性/非线性）、____（时变/时不变）系统。","img":"pro-img/2021_p01.jpg","a":"非线性；时不变","s":"答案页：非线性、时不变。解析残缺（OCR 显示线性/时不变判别式与「未违背两条准则」）。"},{"id":"r21-03","seq":3,"part":"信号","qt":"填空","pts":3,"ch":"ss-cont-time","q":"3. 信号 $f_1(t)$ 和 $f_2(t)$ 如图1-3所示 [图1-3：两波形信号]，若 $f(t)=f_1(1-t)*f_2(2t)$，则 $f(1)=$ ____。","img":"pro-img/2021_p01.jpg","a":"原文不清（OCR 显示 $f(1)=-1\\times1\\times1+\\cdots$，完整值见图1-3）","s":"解析：先作 $f_1(1-t)$ 的反折平移与 $f_2(2t)$ 的尺度变换，再求卷积在 $t=1$ 处取值（波形见图1-3，数值依赖原图）。"},{"id":"r21-04","seq":4,"part":"信号","qt":"填空","pts":3,"ch":"ss-freq","q":"4. 已知 $f(t)=\\dfrac{\\sin(30t)}{\\pi t}$，用正弦载波 $f_c(t)=\\sin(2000t)$ 对其进行抑制载波的双边带（DSB）调制，即已调信号 $f_m(t)=f(t)f_c(t)$，则（1）已调信号 $f_m(t)$ 的带宽为____ Hz；（2）以角频率为横坐标，画出已调信号 $f_m(t)$ 的相位频谱。","img":"pro-img/2021_p01.jpg","a":"（1）$30$ Hz；（2）相位谱在 $\\omega=\\pm1970,\\pm2030$ rad/s 处取值 $\\pm\\dfrac{\\pi}{2}$","s":"解析：$f(t)=\\dfrac{30}{\\pi}\\mathrm{Sa}(30t)$，$F(j\\omega)=g_{60}(\\omega)$；$F_c(j\\omega)=j\\pi[\\delta(\\omega+2000)-\\delta(\\omega-2000)]$；$F_m(j\\omega)=\\dfrac{j}{2}[g_{60}(\\omega+2000)-g_{60}(\\omega-2000)]$，带宽 $60$ rad/s 即 $30$ Hz。"},{"id":"r21-05","seq":5,"part":"信号","qt":"填空","pts":3,"ch":"ss-freq","q":"5. $f(t)=\\varepsilon(t)-\\varepsilon(t-2)$，则其能量谱 $E(\\omega)=$ ____ ($J\\cdot s$)。","img":"pro-img/2021_p02.jpg","a":"$E(\\omega)=4\\,\\mathrm{Sa}^{2}(\\omega)$","s":"解析：$f(t)=g_2(t-1)$，$F(j\\omega)=2\\,\\mathrm{Sa}(\\omega)e^{-j\\omega}$，故 $E(\\omega)=|F(j\\omega)|^2=4\\,\\mathrm{Sa}^{2}(\\omega)$。"},{"id":"r21-06","seq":6,"part":"信号","qt":"填空","pts":3,"ch":"ss-zdomain","q":"6. 周期性抽样序列 $p(k)$ 如图1-6(a)所示 [图1-6(a)：周期抽样序列]，用 $p(k)$ 对任一离散序列 $f(k)$ 进行二倍抽样，得到已抽样序列 $\\tilde{f}(k)$，如图1-6(b)所示。即有 $\\tilde{f}(k)=\\begin{cases}f(k),&k\\text{为偶数}\\\\0,&k\\text{为奇数}\\end{cases}$。若 $f(k)$ 的 z 变换为 $F(z)$，则序列 $\\tilde{f}(k)$ 的 z 变换 $\\tilde{F}(z)=Z[\\tilde{f}(k)]=$ ____（请用 $F(z)$ 表示）。","img":"pro-img/2021_p02.jpg","a":"$\\tilde{F}(z)=\\dfrac{1}{2}[F(z)+F(-z)]$","s":"解析：$\\tilde{f}(k)=\\dfrac{1+(-1)^k}{2}f(k)$，故 $\\tilde{F}(z)=\\dfrac12[F(z)+F(-z)]$。"},{"id":"r21-07","seq":7,"part":"信号","qt":"填空","pts":3,"ch":"ss-sdomain","q":"7. 如图1-7所示 $f(t)$ 为有始周期信号 [图1-7：有始周期信号]（$t<0$ 时 $f(t)=0$），则其拉普拉斯变换为 $F(s)=$ ____；收敛域为：____。","img":"pro-img/2021_p02.jpg","a":"$F(s)=\\dfrac{1-e^{-s}}{s(1+e^{-s})}$；收敛域 $\\mathrm{Re}[s]>0$","s":"解析：单周期 $f_1(t)=\\varepsilon(t)-2\\varepsilon(t-1)+\\varepsilon(t-2)$，$F_1(s)=\\dfrac{(1-e^{-s})^2}{s}$；周期 $T=2$，$F(s)=\\dfrac{F_1(s)}{1-e^{-2s}}=\\dfrac{1-e^{-s}}{s(1+e^{-s})}$。"},{"id":"r21-08","seq":8,"part":"信号","qt":"填空","pts":3,"ch":"ss-zdomain","q":"8. 已知序列 $f(k)$ 的双边 z 变换 $F(z)=\\dfrac{z^2}{(z+2)(z-0.5)}$，收敛域为 $0.5<|z|<2$，则序列 $f(k)=$ ____。","img":"pro-img/2021_p02.jpg","a":"$f(k)=0.2(0.5)^k\\varepsilon(k)-0.8(-2)^k\\varepsilon(-k-1)$","s":"解析：$\\dfrac{z}{(z+2)(z-0.5)}=\\dfrac{0.2}{z-0.5}+\\dfrac{0.8}{z+2}$；由收敛域 $0.5<|z|<2$，对应 $0.2(0.5)^k\\varepsilon(k)$ 与 $-0.8(-2)^k\\varepsilon(-k-1)$。"},{"id":"r21-09","seq":9,"part":"信号","qt":"解答","pts":12,"ch":"ss-freq","q":"1.（12分）周期信号 $f(t)=2\\cos(3\\pi t-\\tfrac{2\\pi}{3})+\\sin(6\\pi t)+3\\cos(8\\pi t)$，试确定：（1）$f(t)$ 的基本周期 $T(s)$、基波频率 $f_0(Hz)$ 和平均功率 $P(W)$；（2）写出 $f(t)$ 的指数型傅里叶级数，并画出其双边幅度谱和相位谱（线状谱）；（3）若以采样频率 $f_s=32\\,Hz$ 对 $f(t)$ 进行采样，并用样点值组成序列 $f(k)=f(t)|_{t=k/f_s}$，则序列 $f(k)$ 的基本周期是多少？若以采样频率 $f_s=8\\,Hz$ 对 $f(t)$ 进行冲激采样，是否可以通过理想低通滤波的方式从采样信号恢复出 $f(t)$？为什么？","img":"pro-img/2021_p03.jpg","a":"（1）$T=2\\,s$，$f_0=0.5\\,Hz$，$P=7\\,W$；（2）$f(t)=e^{-j\\frac{2\\pi}{3}}e^{j3\\pi t}+e^{j\\frac{2\\pi}{3}}e^{-j3\\pi t}+\\tfrac12 e^{-j\\frac{\\pi}{2}}e^{j6\\pi t}+\\tfrac12 e^{j\\frac{\\pi}{2}}e^{-j6\\pi t}+1.5e^{j8\\pi t}+1.5e^{-j8\\pi t}$（$\\Omega=\\pi$ rad/s）；（3）$N=64$；不能恢复，因 $f_m=4\\,Hz$，$f_s=8\\,Hz$ 不满足 $f_s>2f_m$，在 $4\\,Hz$ 处发生频率混叠。","s":"解析：三项分别对应 3、6、8 次谐波；$T_1=\\tfrac23,T_2=\\tfrac13,T_3=\\tfrac14$，$T=\\mathrm{lcm}=2\\,s$，$f_0=\\tfrac12\\,Hz$；$P=\\tfrac12(2^2+1^2+3^2)=7\\,W$；采样后数字频率 $\\omega_1=\\tfrac{3\\pi}{32},\\omega_2=\\tfrac{3\\pi}{16},\\omega_3=\\tfrac{\\pi}{4}$，对应周期 $\\tfrac{64}{3},32,8$，最小公倍数 $N=64$。"},{"id":"r21-10","seq":10,"part":"信号","qt":"解答","pts":12,"ch":"ss-sdomain","q":"2.（12分）描述某线性时不变（LTI）因果连续系统的微分方程为：$y''(t)+7y'(t)+12y(t)=f'(t)+2f(t)$，当输入信号 $f(t)=e^{-2t}\\cos t\\,\\varepsilon(t)$ 时，有 $y(0_+)=0$，$y'(0_+)=3$，求系统的零输入响应 $y_{zi}(t)$、零状态响应 $y_{zs}(t)$ 和全响应 $y(t)$。","img":"pro-img/2021_p03.jpg","a":"$y_{zi}(t)=2(e^{-3t}-e^{-4t})\\varepsilon(t)$；$y_{zs}(t)=\\left[\\tfrac12 e^{-3t}-\\tfrac45 e^{-4t}+\\tfrac{3}{10}e^{-2t}\\cos t-\\tfrac{1}{10}e^{-2t}\\sin t\\right]\\varepsilon(t)$；$y(t)=\\left[\\tfrac52 e^{-3t}-\\tfrac{14}{5}e^{-4t}+\\tfrac{3}{10}e^{-2t}\\cos t-\\tfrac{1}{10}e^{-2t}\\sin t\\right]\\varepsilon(t)$","s":"解析：$H(s)=\\dfrac{s+2}{s^2+7s+12}=\\dfrac{s+2}{(s+3)(s+4)}$，$F(s)=\\dfrac{s+2}{(s+2)^2+1}$；$Y_{zs}(s)=H(s)F(s)=\\dfrac{(s+2)^2}{(s+3)(s+4)[(s+2)^2+1]}=\\dfrac{1/2}{s+3}-\\dfrac{4/5}{s+4}+\\dfrac{0.3(s+2)-0.1}{(s+2)^2+1}$；$y_{zs}(0_+)=0,\\ y_{zs}'(0_+)=1$，故 $y_{zi}(0_+)=0,\\ y_{zi}'(0_+)=2$，由 $C_1+C_2=0,\\ -3C_1-4C_2=2$ 得 $C_1=2,C_2=-2$。"},{"id":"r21-11","seq":11,"part":"信号","qt":"解答","pts":11,"ch":"ss-zdomain","q":"3.（11分）某线性时不变（LTI）因果离散系统的框图如图2-3所示 [图2-3：离散系统框图，含 $0.5$ 反馈支路]。（1）写出描述该系统的差分方程，并确定系统函数 $H(z)$，画出零、极点分布图；（2）系统的频率响应为 $H(e^{j\\theta})=H(z)|_{z=e^{j\\theta}}$（$\\theta$ 为数字角频率），定性画出系统的幅频响应和相频响应曲线（需标注 $\\theta=0$ 和 $\\pm\\pi$ 处的响应数值）；（3）$f(k)=\\cos\\tfrac{\\pi}{2}k$，$-\\infty<k<\\infty$，求系统的稳态响应 $y_{ss}(k)$。","img":"pro-img/2021_p04.jpg","a":"（1）$y(k)+0.5y(k-1)=f(k)-f(k-1)$；$H(z)=\\dfrac{1-z^{-1}}{1+0.5z^{-1}}=\\dfrac{z-1}{z+0.5}$，零点 $z=1$，极点 $z=-0.5$；（2）$|H(e^{j0})|=0$，$|H(e^{j\\pi})|=4$；（3）$y_{ss}(k)=\\dfrac{2\\sqrt{10}}{5}\\cos\\left(\\tfrac{\\pi}{2}k+\\arctan 3\\right)$","s":"解析：由框图 $Y(z)=(1-z^{-1})X(z)$，$F(z)=(1+0.5z^{-1})X(z)$；$H(e^{j\\theta})=\\dfrac{e^{j\\theta}-1}{e^{j\\theta}+0.5}$，$|H|=\\dfrac{2|\\sin\\tfrac{\\theta}{2}|}{\\sqrt{1.25+\\cos\\theta}}$；$H(e^{j\\pi/2})=\\dfrac{j-1}{j+0.5}=\\dfrac{2\\sqrt{10}}{5}e^{j\\arctan3}$，故 $y_{ss}(k)=\\dfrac{2\\sqrt{10}}{5}\\cos\\left(\\tfrac{\\pi}{2}k+\\arctan3\\right)$。"},{"id":"r21-12","seq":12,"part":"信号","qt":"解答","pts":6,"ch":"ss-freq","q":"4.（6分）图2-4所示是模拟调幅(AM)信号的一种部分相干接收系统 [图2-4：含平方器、开方器、理想低通滤波器的相干接收系统]。已知 AM 已调信号 $f(t)=[f_0(t)+A]\\cos(\\omega_c t+\\theta_c)$，其中 $f_0(t)$ 是发送端的基带信号，它是实带限信号，即 $F_0(j\\omega)=0,\\ |\\omega|>\\omega_m$；$\\theta_c$ 为相位常数但大小未知，$A$ 为正实常数，并且对于所有的 $t$ 均有 $f_0(t)+A>0$ 成立。系统 $H(j\\omega)$ 是理想低通滤波器，其频率响应为 $H(j\\omega)=\\begin{cases}2,&|\\omega|<\\omega_m\\\\0,&|\\omega|>\\omega_m\\end{cases}$（且 $\\omega_c>\\omega_m$）。平方器和开方器分别完成对输入信号的平方和开平方运算。试证明：图示接收系统的输出 $y(t)=f_0(t)+A$。","img":"pro-img/2021_p04.jpg","a":"$y(t)=f_0(t)+A$（证明见解析）","s":"解析：$x_1(t)=f(t)\\cos\\omega_c t=\\tfrac12[f_0+A][\\cos(2\\omega_c t+\\theta_c)+\\cos\\theta_c]$，$x_2(t)=f(t)\\sin\\omega_c t=\\tfrac12[f_0+A][\\sin(2\\omega_c t+\\theta_c)-\\sin\\theta_c]$；经增益为 2 的理想低通后 $x_3(t)=[f_0+A]\\cos\\theta_c$，$x_4(t)=-[f_0+A]\\sin\\theta_c$；平方相加 $x_3^2+x_4^2=[f_0+A]^2$，开方得 $y(t)=f_0(t)+A$。"},{"id":"r21-13","seq":13,"part":"信号","qt":"解答","pts":10,"ch":"ss-state","q":"5.（10分）某离散因果系统的信号流图如图2-5所示 [图2-5：离散系统信号流图，含参数 $a$ 与 $0.2$ 反馈]。参数 $a$ 为实数。试确定：（1）该系统的系统函数 $H(z)$，以及使系统保持稳定的参数 $a$ 取值范围；（2）$a=-1$ 时，写出以 $x_1(k)$ 和 $x_2(k)$ 作为状态变量的状态方程和输出方程。","img":"pro-img/2021_p05.jpg","a":"（1）$H(z)=\\dfrac{z^2-2z+1}{z^2-(a+0.2)z+0.2}=\\dfrac{1-2z^{-1}+z^{-2}}{1-(a+0.2)z^{-1}+0.2z^{-2}}$，稳定条件 $-1.4<a<1$；（2）$\\begin{bmatrix}x_1(k+1)\\\\x_2(k+1)\\end{bmatrix}=\\begin{bmatrix}0&0.2\\\\-1&-0.8\\end{bmatrix}\\begin{bmatrix}x_1(k)\\\\x_2(k)\\end{bmatrix}+\\begin{bmatrix}1\\\\1\\end{bmatrix}f(k)$；$y(k)=\\begin{bmatrix}-1&-1.8\\end{bmatrix}\\begin{bmatrix}x_1(k)\\\\x_2(k)\\end{bmatrix}+f(k)$","s":"解析：由流图得 $H(z)=\\dfrac{1-2z^{-1}+z^{-2}}{1-(a+0.2)z^{-1}+0.2z^{-2}}$；$A(z)=z^2-(a+0.2)z+0.2$，稳定需 $A(1)>0$ 且 $A(-1)>0$，即 $-1.4<a<1$；$a=-1$ 时 $x_1(k+1)=0.2x_2(k)+f(k)$，$x_2(k+1)=-x_1(k)-0.8x_2(k)+f(k)$，$y(k)=-x_1(k)-1.8x_2(k)+f(k)$。"},{"id":"r22-01","seq":1,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"积分 $\\int_{-\\infty}^{t}(1-2x)[\\delta(1-2x)+\\delta'(x-3)]\\,dx=$ ___。","img":"pro-img/2022_p01.jpg","a":"$2\\varepsilon(t-3)-5\\delta(t-3)$","s":"$\\int_{-\\infty}^{t}(1-2x)\\delta(1-2x)dx=0$（$\\delta(1-2x)=\\frac12\\delta(x-\\frac12)$，在 $x=\\frac12$ 处 $1-2x=0$）；$\\int_{-\\infty}^{t}(1-2x)\\delta'(x-3)dx=-f'(3)\\varepsilon(t-3)+f(3)\\delta(t-3)=2\\varepsilon(t-3)-5\\delta(t-3)$，其中 $f(x)=1-2x$。"},{"id":"r22-02","seq":2,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"理想冲激采样系统如图1-2所示，其中 $f(t)$ 为输入信号，$y(t)$ 为输出信号，$p(t)$ 为周期性冲激信号：$p(t)=\\sum_{n=-\\infty}^{\\infty}\\delta(t-nT_s)$，$T_s$ 为取样周期。则，该系统是 ___（因果/非因果）、___（时变/时不变）系统。[图1-2：理想冲激采样系统，$f(t)$ 与 $p(t)$ 相乘得到 $y(t)$]","img":"pro-img/2022_p01.jpg","a":"因果，时变","s":"$y(t)=f(t)p(t)=\\sum_{n}f(nT_s)\\delta(t-nT_s)$，输出只取决于当前及过去输入 $f(t)$，故因果；因存在随时间变化的乘子 $p(t)$，故时变。"},{"id":"r22-03","seq":3,"part":"信号","qt":"填空","pts":4,"ch":"ss-zdomain","q":"序列 $f_1(k)=\\varepsilon(-k-1)-\\varepsilon(-k-4)$，序列 $f_2(k)=\\varepsilon(k+1)$，则 $f(k)=f_1(k)*f_2(k)$ 的波形为（请画出 $f(k)$ 的波形）。","img":"pro-img/2022_p01.jpg","a":"$f(k)$ 为阶梯波形：$f(-5)=0$，$f(-4)=1$，$f(-3)=2$，$f(k)=3\\ (k\\ge-2)$，其余为 $0$（由 0、1、2 上升后恒为 3 的序列）。","s":"$f_1(m)=1$（$m=-3,-2,-1$），其余为 0；$f_2(k-m)=\\varepsilon(k-m+1)$。$f(k)=\\#\\{m\\in\\{-3,-2,-1\\}:m\\le k+1\\}$，故依次得 $0,1,2,3,3,\\dots$。"},{"id":"r22-04","seq":4,"part":"信号","qt":"填空","pts":4,"ch":"ss-cont-time","q":"若 $f(t)=\\cos(2\\pi t)[\\varepsilon(t)-\\varepsilon(t-1)]$，则 $f(t)*\\varepsilon(2t-4)=$ ___。","img":"pro-img/2022_p01.jpg","a":"$\\dfrac{1}{2\\pi}\\sin(2\\pi t)\\,[\\varepsilon(t-2)-\\varepsilon(t-3)]$","s":"$\\varepsilon(2t-4)=\\varepsilon(t-2)$，$f(t)*\\varepsilon(t-2)=\\int_{-\\infty}^{t-2}f(\\tau)d\\tau=\\int_{0}^{t-2}\\cos(2\\pi\\tau)d\\tau=\\frac{\\sin 2\\pi(t-2)}{2\\pi}=\\frac{\\sin 2\\pi t}{2\\pi}$，仅在 $2\\le t\\le3$ 非零，即乘 $[\\varepsilon(t-2)-\\varepsilon(t-3)]$。"},{"id":"r22-05","seq":5,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"已知 $\\mathrm{sgn}(t)$ 的傅里叶变换 $S(j\\omega)=\\dfrac{2}{j\\omega}$（$\\omega\\ne0$）。这里 $\\mathrm{sgn}(t)$ 是符号函数，其定义为 $\\mathrm{sgn}(t)=1\\ (t>0)$，$0\\ (t=0)$，$-1\\ (t<0)$。则 $f(t)=\\dfrac{1}{t}$ 的傅里叶变换 $F(j\\omega)=$ ___。","img":"pro-img/2022_p02.jpg","a":"$-j\\pi\\,\\mathrm{sgn}(\\omega)$","s":"由傅里叶变换的对偶性：$\\mathrm{sgn}(t)\\leftrightarrow\\frac{2}{j\\omega}$，故 $\\frac{2}{jt}\\leftrightarrow 2\\pi\\,\\mathrm{sgn}(-\\omega)$，即 $\\frac{1}{t}\\leftrightarrow -j\\pi\\,\\mathrm{sgn}(\\omega)$。"},{"id":"r22-06","seq":6,"part":"信号","qt":"填空","pts":4,"ch":"ss-zdomain","q":"对有限长序列 $f(k)$，构造其二倍内插序列 $f_i(k)$ 如下：$f_i(k)=f(k/2)$（$k$ 为偶数），$f_i(k)=0$（$k$ 为奇数）。若 $f(k)$ 的 $z$ 变换为 $F(z)$，则根据 $z$ 变换的定义，序列 $f_i(k)$ 的 $z$ 变换 $F_i(z)=$ ___。（请用 $F(z)$ 表示 $F_i(z)$）","img":"pro-img/2022_p02.jpg","a":"$F_i(z)=F(z^2)$","s":"$F_i(z)=\\sum_{k}f_i(k)z^{-k}=\\sum_{m}f(m)z^{-2m}=F(z^2)$。"},{"id":"r22-07","seq":7,"part":"信号","qt":"填空","pts":4,"ch":"ss-sdomain","q":"如图1-7所示，周期信号 $f(t)$（周期为3，一周期内 $f(t)=1\\ (0<t<1)$、$0\\ (1<t<3)$）的平均功率 $P=$ ___；$f(t)$ 的单周期信号 $\\varepsilon(t)-\\varepsilon(t-1)$ 的拉普拉斯变换为 ___。[图1-7：周期方波信号 $f(t)$，时间轴标注 $-4,-3,-2,\\dots$]","img":"pro-img/2022_p02.jpg","a":"$P=\\dfrac{1}{3}$；$\\mathcal{L}\\{\\varepsilon(t)-\\varepsilon(t-1)\\}=\\dfrac{1-e^{-s}}{s}$","s":"$P=\\frac{1}{3}\\int_{0}^{1}1^2\\,dt=\\frac{1}{3}$；单周期门脉冲 $\\varepsilon(t)-\\varepsilon(t-1)$ 的拉氏变换为 $\\frac{1}{s}-\\frac{e^{-s}}{s}=\\frac{1-e^{-s}}{s}$（拉氏变换部分以答案页为准）。"},{"id":"r22-08","seq":8,"part":"信号","qt":"填空","pts":4,"ch":"ss-zdomain","q":"序列 $f(k)$ 的单边 $z$ 变换 $F(z)=\\dfrac{(z+4)(z-2)}{(z-1)(z+0.25)(z-0.5)}$，收敛域为 $|z|>1$，则 $f(0_+)=$ ___。","img":"pro-img/2022_p02.jpg","a":"$-16$","s":""},{"id":"r22-09","seq":9,"part":"信号","qt":"解答","pts":12,"ch":"ss-freq","q":"（12分）全波整流正弦信号 $f_1(t)=|\\sin(\\pi t)|$ 的波形如图2-1(a)所示，半波整流正弦信号 $f_2(t)$ 如图2-1(b)所示。连续周期信号 $f(t)$ 的三角型傅里叶级数如下式：$f(t)=\\frac{a_0}{2}+\\sum_{n=1}^{\\infty}a_n\\cos(n\\Omega t)+\\sum_{n=1}^{\\infty}b_n\\sin(n\\Omega t)$，$\\Omega=\\frac{2\\pi}{T}$，$T$ 为 $f(t)$ 的周期。已知 $f_1(t)$ 的傅里叶级数系数（按基本周期 $T=1$ s 进行展开）为 $a_n=\\frac{4}{\\pi(4n^2-1)}$，$n=0,1,2,3,\\dots$。低通滤波器 $H(j\\omega)$ 的幅、相频响特性如图2-1(c)(d)所示。试确定：(1) 信号 $f_2(t)$ 的基本周期 $T_2$ (s)、基波频率 $f_2$ (Hz)；(2) $f_2(t)$ 的指数型傅里叶级数和系数 $F_{2,n}$，画出其双边幅度谱和相位谱（线状谱），要求画到4次谐波为止，并标出相应数值；(3) 以 $f_2(t)$ 作为输入信号，滤波器 $H(j\\omega)$ 的输出信号 $y_2(t)$。[图2-1：(a) 全波整流正弦 $f_1(t)=|\\sin(\\pi t)|$；(b) 半波整流正弦 $f_2(t)$；(c) 低通幅频 $|H(j\\omega)|$；(d) 相频 $\\varphi(\\omega)$]","img":"pro-img/2022_p03.jpg","a":"(1) $T_2=2$ s，$f_2=0.5$ Hz。(2) $f_2(t)=\\sum_{n=-\\infty}^{\\infty}F_{2,n}e^{jn\\Omega_2 t}$，$\\Omega_2=\\pi$ rad/s；$F_{2,0}=\\frac{1}{\\pi}$，$F_{2,\\pm1}=\\mp\\frac{j}{4}$，$F_{2,\\pm n}=-\\frac{1}{\\pi(4n^2-1)}$（$n=1,2,3,\\dots$）；具体 $F_{2,\\pm2}=-\\frac{1}{3\\pi}$，$F_{2,\\pm3}=0$，$F_{2,\\pm4}=-\\frac{1}{15\\pi}$。幅度谱 $|F_{2,n}|$：$\\frac{1}{\\pi}$($0$)、$\\frac14$($\\pm1$)、$\\frac{1}{3\\pi}$($\\pm2$)、$0$($\\pm3$)、$\\frac{1}{15\\pi}$($\\pm4$)；相位谱：$0$、$\\mp\\frac{\\pi}{2}$、$\\pm\\pi$、$0$、$\\pm\\pi$。(3) $f_2(t)=\\frac{1}{\\pi}+\\frac12\\sin(\\pi t)-\\frac{2}{3\\pi}\\cos(2\\pi t)-\\frac{2}{15\\pi}\\cos(4\\pi t)-\\cdots$；由 $H(j0)=1$、$H(\\pm j\\pi)=e^{\\mp j\\pi/2}$、$H(\\pm j2\\pi)=e^{\\mp j\\pi}$、$H(\\pm j4\\pi)=0$，得 $y_2(t)=\\frac{1}{\\pi}-\\frac12\\cos(\\pi t)+\\frac{2}{3\\pi}\\cos(2\\pi t)$。","s":"(1) $f_2(t)=\\frac12[f_1(t)+\\sin(\\pi t)]$，$\\sin(\\pi t)$ 周期为2，故 $T_2=2$ s，$f_2=0.5$ Hz。(2) $f_1(t)=\\frac{2}{\\pi}-\\frac{4}{\\pi}\\sum_{n=1}^{\\infty}\\frac{\\cos(2\\pi nt)}{4n^2-1}$，代入得 $f_2(t)=\\frac{1}{\\pi}+\\frac12\\sin(\\pi t)-\\frac{2}{3\\pi}\\cos(2\\pi t)-\\frac{2}{15\\pi}\\cos(4\\pi t)-\\cdots$，与指数型对比得各 $F_{2,n}$。(3) 滤波后保留 $\\omega=0,\\pm\\pi,\\pm2\\pi$ 分量并按相频特性移相，$\\pm4\\pi$ 分量被滤除。"},{"id":"r22-10","seq":10,"part":"信号","qt":"解答","pts":12,"ch":"ss-sdomain","q":"（12分）某二阶线性时不变(LTI)因果连续系统，初始状态一定，(1) 当激励 $f(t)=\\varepsilon(t)$ 时的全响应为 $(1+2e^{-t}-e^{-2t})\\varepsilon(t)$；(2) 当激励 $f(t)=\\delta(t)$ 时的全响应为 $5e^{-2t}\\varepsilon(t)$。试确定：$f(t)=\\varepsilon(t)$ 时系统的零输入响应 $y_{zi}(t)$、零状态响应 $y_{zs}(t)$；系统描述方程、系统函数 $H(s)$、冲激响应 $h(t)$ 和系统的直接型流图。","img":"pro-img/2022_p03.jpg","a":"$y_{zi}(t)=(e^{-t}+e^{-2t})\\varepsilon(t)$；$y_{zs}(t)=g(t)=(1+e^{-t}-2e^{-2t})\\varepsilon(t)$；微分方程 $y''(t)+3y'(t)+2y(t)=3f'(t)+2f(t)$；$H(s)=\\dfrac{3s+2}{s^2+3s+2}=\\dfrac{3s+2}{(s+1)(s+2)}$；$h(t)=(4e^{-2t}-e^{-t})\\varepsilon(t)$。","s":"设阶跃响应 $g(t)$。全响应 $y_{zi}+g=(1+2e^{-t}-e^{-2t})\\varepsilon(t)$（式1），$y_{zi}+h=5e^{-2t}\\varepsilon(t)$（式2）。式1-式2：$g(t)-h(t)=(1+2e^{-t}-6e^{-2t})\\varepsilon(t)$，取单边拉氏变换得 $\\frac{H(s)}{s}-H(s)=\\frac1s+\\frac{2}{s+1}-\\frac{6}{s+2}$，解得 $H(s)=\\frac{3s+2}{(s+1)(s+2)}$。反变换 $h(t)=(4e^{-2t}-e^{-t})\\varepsilon(t)$；由式2得 $y_{zi}(t)=y-h=(e^{-t}+e^{-2t})\\varepsilon(t)$；由式1得 $y_{zs}(t)=g(t)=y-y_{zi}=(1+e^{-t}-2e^{-2t})\\varepsilon(t)$。"},{"id":"r22-11","seq":11,"part":"信号","qt":"解答","pts":13,"ch":"ss-zdomain","q":"（13分）某线性时不变(LTI)因果离散系统的模拟框图如图2-3所示。(1) 写出描述该系统的差分方程，并确定系统函数 $H(z)$；(2) 求系统的单位序列响应 $h(k)$，判定系统的稳定性；(3) $f(k)=(-1)^k$，$-\\infty<k<\\infty$，求系统响应 $y(k)$，$-\\infty<k<\\infty$；(4) 按图2-3中设定的状态变量 $x_1(k)$、$x_2(k)$ 写系统的状态方程和输出方程。[图2-3：直接型离散系统框图，含系数 $\\frac14$、$\\frac{1}{16}$、$\\frac38$，状态变量 $x_1(k)$、$x_2(k)$]","img":"pro-img/2022_p04.jpg","a":"(1) $y(k)+0.25y(k-1)-0.375y(k-2)=f(k)-0.0625f(k-2)$；$H(z)=\\dfrac{1-0.0625z^{-2}}{1+0.25z^{-1}-0.375z^{-2}}=\\dfrac{z^2-0.0625}{z^2+0.25z-0.375}=\\dfrac{(z+0.25)(z-0.25)}{(z+0.75)(z-0.5)}$，$|z|>0.75$。(2) $h(k)=\\frac16\\delta(k)+\\left[\\frac{8}{15}(-0.75)^k+\\frac{3}{10}(0.5)^k\\right]\\varepsilon(k)$；极点 $-0.75$、$0.5$ 均在单位圆内，系统稳定。(3) $y(k)=H(-1)(-1)^k=2.5(-1)^k=\\frac52(-1)^k$。(4) $x_1(k+1)=x_2(k)$；$x_2(k+1)=\\frac38x_1(k)-\\frac14x_2(k)+f(k)$；$y(k)=\\frac{5}{16}x_1(k)-\\frac14x_2(k)+f(k)$；矩阵形式 $\\begin{bmatrix}x_1(k+1)\\\\x_2(k+1)\\end{bmatrix}=\\begin{bmatrix}0&1\\\\\\frac38&-\\frac14\\end{bmatrix}\\begin{bmatrix}x_1(k)\\\\x_2(k)\\end{bmatrix}+\\begin{bmatrix}0\\\\1\\end{bmatrix}f(k)$，$y(k)=\\begin{bmatrix}\\frac{5}{16}&-\\frac14\\end{bmatrix}\\begin{bmatrix}x_1(k)\\\\x_2(k)\\end{bmatrix}+f(k)$。","s":"(1) 由梅森公式 $H(z)=\\frac{1-0.0625z^{-2}}{1+0.25z^{-1}-0.375z^{-2}}$，对应差分方程。(2) $\\frac{H(z)}{z}=\\frac{1/6}{z}+\\frac{8/15}{z+0.75}+\\frac{3/10}{z-0.5}$，反变换得 $h(k)$。(3) $z=-1$ 在收敛域内，$(-1)^k$ 为特征函数，$y(k)=H(-1)(-1)^k$。"},{"id":"r22-12","seq":12,"part":"信号","qt":"解答","pts":6,"ch":"ss-freq","q":"（6分）信号 $f(t)$ 为带限信号，即 $|\\omega|>\\omega_m>0$ 时，$F(j\\omega)=0$。通信技术中……调制，一般有 $\\omega_s\\gg\\omega_m$。图2-4(a)所示的采样滤波系统中，输入信号 $f(t)$ 为带限信号，采样脉冲序列 $p(t)=\\sum_{n=-\\infty}^{\\infty}\\cos(n\\pi)\\delta(t-nT_s)$，$T_s$ 为取样周期，采样角频率 $\\omega_s=\\frac{2\\pi}{T_s}$。滤波器 $H(j\\omega)$ 是理想的带通滤波器，如图2-4(b)所示，其中 $\\omega_c$ 为通带中心角频率，通带宽度为 $2\\omega_m$，一般有 $\\omega_c\\gg\\omega_m>0$。试证明：在满足采样定理的前提下（即 $\\omega_s>2\\omega_m$），图2-4所示的系统可以完成抑制载波的双边带(DSB)调制，即 $y(t)=f(t)\\cos(\\omega_c t)$，并且载波角频率 $\\omega_c$（也是带通滤波器 $H(j\\omega)$ 的通带中心角频率）为 $\\omega_c=(M+\\frac12)\\omega_s$，$M$ 取正整数且 $M\\ge1$；而系统中带通滤波器 $H(j\\omega)$ 的截止频率参数 $\\omega_c$ 的取值范围为 $\\omega_m<\\omega_c<\\omega_s-\\omega_m$。（提示：$n$ 取整数时，$\\cos(n\\pi)=e^{jn\\pi}=(-1)^n$）[图2-4：(a) 采样滤波系统 $f(t)$→乘法器→$s(t)$→$H(j\\omega)$→$y(t)$，乘法器另一输入 $p(t)$；(b) 理想带通滤波器 $|H(j\\omega)|$，通带中心 $\\pm\\omega_c$，带宽 $2\\omega_m$]","img":"pro-img/2022_p05.jpg","a":"证明：$p(t)=\\sum_{n}(-1)^n\\delta(t-nT_s)$，其傅里叶变换 $P(j\\omega)=\\omega_s\\sum_{n}\\delta\\left(\\omega-(n+\\tfrac12)\\omega_s\\right)$；$s(t)=f(t)p(t)$，故 $S(j\\omega)=\\frac{1}{T_s}\\sum_{n}F\\left(j(\\omega-(n+\\tfrac12)\\omega_s)\\right)$。带通滤波器选取中心位于 $\\pm\\omega_c=\\pm(M+\\frac12)\\omega_s$ 的一对对称频谱，即可得 $y(t)=f(t)\\cos(\\omega_c t)$，其中 $\\omega_c=(M+\\frac12)\\omega_s$（$M\\ge1$），且 $\\omega_m<\\omega_c<\\omega_s-\\omega_m$。","s":"周期冲激串 $\\sum_n\\delta(t-nT_s)\\leftrightarrow\\omega_s\\sum_n\\delta(\\omega-n\\omega_s)$；乘 $(-1)^n=e^{jn\\pi}$ 后频谱平移 $\\omega_s/2$，得 $P(j\\omega)=\\omega_s\\sum_n\\delta(\\omega-(n+\\frac12)\\omega_s)$。采样后 $S(j\\omega)$ 为 $F(j\\omega)$ 的周期延拓，中心在 $(n+\\frac12)\\omega_s$。因 $\\cos(\\omega_c t)f(t)\\leftrightarrow\\frac12[F(j(\\omega+\\omega_c))+F(j(\\omega-\\omega_c))]$，用带通滤波器选出 $\\pm(M+\\frac12)\\omega_s$ 处的一对频谱即实现 DSB 调制。"},{"id":"r23-01","seq":1,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"就函数的奇偶性而言，信号 $f(t)$（原文 OCR 缺失，见整页图）是 ____ 函数；$\\delta(at-b)=$ ____（这里 $a,b$ 均为实常数，且 $a\\neq0$）。","img":"pro-img/2023_p01.jpg","a":"奇函数；$\\delta(at-b)=\\frac{1}{|a|}\\,\\delta\\!\\left(t-\\frac{b}{a}\\right)$","s":""},{"id":"r23-02","seq":2,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"数字通信系统中，可将解调器中的硬判决单元视作如下输入输出关系描述的连续时间系统：$y(t)=\\begin{cases}1,&f(t)>0\\\\0,&f(t)\\le0\\end{cases}$，那么，这个系统是 ____（线性/非线性）、____（时变/时不变）系统。","img":"pro-img/2023_p01.jpg","a":"非线性；时不变","s":"当输入为 $f(t)$ 时输出按符号判决；若输入变为 $kf(t)$（如 $k<0$）输出不满足齐次性，故非线性；输出仅由当前时刻 $f(t)$ 决定、系统系数不随时间变化，故时不变。"},{"id":"r23-03","seq":3,"part":"信号","qt":"填空","pts":4,"ch":"ss-cont-time","q":"因果连续 LTI 系统的输入、输出方程如下：$y''(t)+7y'(t)+10y(t)=2f'(t)-f(t)$，若输入 $f(t)=e^{-t}\\varepsilon(t)$，则 $y(0_+)=$ ____，$y'(0_+)=$ ____。","img":"pro-img/2023_p01.jpg","a":"$y(0_+)=0$，$y'(0_+)=2$","s":"$f'(t)=-e^{-t}\\varepsilon(t)+\\delta(t)$，故 $2f'(t)-f(t)=2\\delta(t)-3e^{-t}\\varepsilon(t)$。最高阶导数项含 $2\\delta(t)$，冲激匹配得 $y'(0_+)-y'(0_-)=2$，$y(0_+)-y(0_-)=0$；系统零起始，故 $y(0_+)=0$，$y'(0_+)=2$。"},{"id":"r23-04","seq":4,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"已知 $\\mathrm{sgn}(t)$ 的傅里叶变换为 $\\frac{2}{j\\omega}$，则 $f(t)=\\varepsilon(t)$（信号原文不清，据答案/图恢复）的傅里叶变换 $F(j\\omega)=$ ____。这里 $\\mathrm{sgn}(t)$ 是符号函数，其定义为 $\\mathrm{sgn}(t)=\\begin{cases}1,&t>0\\\\0,&t=0\\\\-1,&t<0\\end{cases}$。$F(j\\omega)=|F(j\\omega)|e^{j\\varphi(\\omega)}$，请画出 $F(j\\omega)$ 的相频特性曲线：____。","img":"pro-img/2023_p01.jpg","a":"$F(j\\omega)=\\pi\\delta(\\omega)+\\frac{1}{j\\omega}$；相频特性 $\\varphi(\\omega)=-\\frac{\\pi}{2}\\ (\\omega>0)$，$+\\frac{\\pi}{2}\\ (\\omega<0)$","s":"$\\varepsilon(t)=\\frac12+\\frac12\\mathrm{sgn}(t)$，故 $F(j\\omega)=\\pi\\delta(\\omega)+\\frac{1}{j\\omega}$；$\\omega\\neq0$ 时 $\\frac{1}{j\\omega}=\\frac{1}{|\\omega|}e^{-j\\frac{\\pi}{2}\\mathrm{sgn}(\\omega)}$。"},{"id":"r23-05","seq":5,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"假定连续周期信号 $f(t)$ 是电压信号，单位为伏特（V），并且 $f(t)=0.5+\\cos(200\\pi t)-0.4\\sin(200\\pi t)$（频率项原文 OCR 为 1000，按答案 100 Hz 恢复为 $200\\pi$），时间 $t$ 单位为秒（s），则 $f(t)$ 的基波频率为 ____ Hz，平均功率为 ____ W。","img":"pro-img/2023_p02.jpg","a":"100 Hz；0.83 W","s":"$\\omega_0=200\\pi\\ \\mathrm{rad/s}$，$f_0=\\frac{\\omega_0}{2\\pi}=100\\ \\mathrm{Hz}$；$P=0.5^2+\\frac{1^2}{2}+\\frac{0.4^2}{2}=0.25+0.5+0.08=0.83\\ \\mathrm{W}$。"},{"id":"r23-06","seq":6,"part":"信号","qt":"填空","pts":4,"ch":"ss-zdomain","q":"序列 $f_1(k)=\\varepsilon(k-1)-\\varepsilon(k-3)$，序列 $f_2(k)=\\varepsilon(k+1)$，则序列 $f(k)=f_1(k)*f_2(k)$ 的波形为 ____；$f(k)$ 的 z 变换为 ____。","img":"pro-img/2023_p02.jpg","a":"$f(k)=\\varepsilon(k)+\\varepsilon(k-1)$（$k=0$ 处取 1，$k\\ge1$ 处取 2）；$F(z)=\\frac{z+1}{z-1}=1+\\frac{2}{z-1}$（$|z|>1$）","s":"$f_1(k)=\\delta(k-1)+\\delta(k-2)$，故 $f(k)=f_1(k)*f_2(k)=\\varepsilon(k)+\\varepsilon(k-1)$；$F(z)=\\frac{z}{z-1}+\\frac{1}{z-1}=\\frac{z+1}{z-1}$。"},{"id":"r23-07","seq":7,"part":"信号","qt":"填空","pts":4,"ch":"ss-sdomain","q":"时间有限信号 $f(t)$ 如图1-7所示（据答案恢复 $f(t)=\\varepsilon(t)-2\\varepsilon(t-1)+\\varepsilon(t-2)$），有始周期信号 $f_T(t)=\\sum_{n=0}^{\\infty}f(t-2n)$，则其拉普拉斯变换 $F(s)=$ ____，其收敛域为 ____。[图1-7：单周期为 $+1$（$0<t<1$）、$-1$（$1<t<2$）的脉冲]","img":"pro-img/2023_p02.jpg","a":"$F(s)=\\frac{(1-e^{-s})^2}{s(1-e^{-2s})}=\\frac{1-e^{-s}}{s(1+e^{-s})}$；收敛域 $\\mathrm{Re}[s]>0$","s":"单周期 $f(t)=\\varepsilon(t)-2\\varepsilon(t-1)+\\varepsilon(t-2)$，$F_1(s)=\\frac{1-2e^{-s}+e^{-2s}}{s}$；周期延拓后 $F(s)=\\frac{F_1(s)}{1-e^{-2s}}=\\frac{1-e^{-s}}{s(1+e^{-s})}$，$\\mathrm{Re}[s]>0$。"},{"id":"r23-08","seq":8,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"由图1-7所示 $f(t)$ 进行周期延拓得到周期信号 $f_T(t)$，即 $f_T(t)=\\sum_{n}f(t-nT)$，$T=2$。若 $f_T(t)$ 的三角函数形式傅里叶级数如式：$f_T(t)=\\frac{a_0}{2}+\\sum_{n=1}^{\\infty}[a_n\\cos(n\\omega_0 t)+b_n\\sin(n\\omega_0 t)]$，则 $f_T(t)$ 是否存在偶次谐波（是/否）____，$f_T(t)$ 的基波表达式为 ____。","img":"pro-img/2023_p02.jpg","a":"否；基波 $\\frac{4}{\\pi}\\sin(\\pi t)$","s":"$\\omega_0=\\frac{2\\pi}{T}=\\pi$；$f_T(t)$ 为奇函数，$a_n=0$；$b_n=\\frac{4}{n\\pi}$（$n$ 为奇数），$b_n=0$（$n$ 为偶数），故无偶次谐波，基波为 $b_1\\sin(\\pi t)=\\frac{4}{\\pi}\\sin(\\pi t)$。"},{"id":"r23-09","seq":9,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"矩形脉冲取样系统如图1-9(a)所示，其中取样脉冲序列为 $p(t)=\\sum_{n}g_\\tau(t-nT_s)$，$0<\\tau<T_s$；矩形脉冲信号 $g_\\tau(t)$ 如图1-9(b)所示。若信号 $f(t)$ 是实带限信号，最高频率为 $f_m$，则要使取样信号 $f_s(t)$ 的频谱不发生混叠，取样周期 $T_s$ 应满足的条件 ____。[图1-9：矩形脉冲取样系统框图与矩形脉冲波形]","img":"pro-img/2023_p02.jpg","a":"$T_s\\le\\frac{1}{2f_m}$（即满足奈奎斯特采样定理 $f_s\\ge2f_m$）","s":"周期矩形脉冲取样为实际采样，仍须满足采样定理，故 $T_s\\le\\frac{1}{2f_m}$。"},{"id":"r23-10","seq":10,"part":"信号","qt":"解答","pts":11,"ch":"ss-zdomain","q":"如图2-1(a)所描述的离散时间系统中，若单位序列响应为 $h(k)$ 的子系统是 LTI 系统，该子系统系统函数为 $H(z)$（$h(k)\\leftrightarrow H(z)$）。（1）根据线性和时不变性的定义在时域验证图2-1(a)所示系统是线性时不变（LTI）系统，确定其单位序列响应 $h_1(k)$ 和系统函数 $H_1(z)=\\frac{Y(z)}{F(z)}$（即：分别以 $h(k)$ 和 $H(z)$ 来表示它们）。提示：$\\cos(\\pi k)=e^{j\\pi k}=(-1)^k$。（2）若子系统频率响应函数 $H(e^{j\\theta})$ 如图2-1(b)所示，请画出频率响应函数 $H_1(e^{j\\theta})$ 的曲线，并说明其滤波器类型。[图2-1：输入经 $(-1)^k$ 调制→$h(k)$→$(-1)^k$ 解调；(b) 为低通幅频特性]","img":"pro-img/2023_p03.jpg","a":"（1）$h_1(k)=(-1)^k h(k)$，$H_1(z)=H(-z)$；（2）$H_1(e^{j\\theta})=H(-e^{j\\theta})=H(e^{j(\\theta-\\pi)})$，为高通滤波器（由低通频谱搬移 $\\pi$ 得到）","s":"由图 $y(k)=(-1)^k[h(k)*((-1)^k f(k))]$。调制因子 $(-1)^k$ 与卷积子系统均为线性时不变运算，故系统为 LTI。对单位序列响应 $h_1(k)=(-1)^k h(k)$；由 z 变换性质 $H_1(z)=H(-z)$。频率响应 $H_1(e^{j\\theta})=H(-e^{j\\theta})=H(e^{j(\\theta-\\pi)})$，低通搬移 $\\pi$ 后为高通。"},{"id":"r23-11","seq":11,"part":"信号","qt":"解答","pts":8,"ch":"ss-cont-time","q":"描述某线性时不变（LTI）因果连续系统的微分方程为 $y''(t)+3y'(t)+2y(t)=2f'(t)+f(t)$（原文不清，据答案恢复），若 $f(t)=e^{-3t}\\varepsilon(t)$，初始条件 $y(0_-)=1$，$y'(0_-)=0$，求系统的零输入响应 $y_{zi}(t)$、零状态响应 $y_{zs}(t)$ 和全响应 $y(t)$；并指出该系统的滤波器类型（低通/高通/带通/带阻）。","img":"pro-img/2023_p03.jpg","a":"$y_{zi}(t)=(2e^{-t}-e^{-2t})\\varepsilon(t)$；$y_{zs}(t)=(-\\frac{1}{2}e^{-t}+3e^{-2t}-\\frac{5}{2}e^{-3t})\\varepsilon(t)$；$y(t)=(\\frac{3}{2}e^{-t}+2e^{-2t}-\\frac{5}{2}e^{-3t})\\varepsilon(t)$；低通滤波器","s":"特征方程 $s^2+3s+2=0$，根 $-1,-2$，设 $y_{zi}=C_1e^{-t}+C_2e^{-2t}$，由 $y(0_-)=1,y'(0_-)=0$ 得 $C_1=2,C_2=-1$，故 $y_{zi}=(2e^{-t}-e^{-2t})\\varepsilon(t)$。$H(s)=\\frac{2s+1}{s^2+3s+2}$，$F(s)=\\frac{1}{s+3}$，$Y_{zs}(s)=\\frac{2s+1}{(s+1)(s+2)(s+3)}$，部分分式得 $y_{zs}=(-\\frac{1}{2}e^{-t}+3e^{-2t}-\\frac{5}{2}e^{-3t})\\varepsilon(t)$。$H(0)=\\frac12\\neq0$，$H(\\infty)\\to0$，故为低通。"},{"id":"r23-12","seq":12,"part":"信号","qt":"解答","pts":8,"ch":"ss-zdomain","q":"某线性时不变（LTI）因果离散框图如图2-3所示：（1）写出描述系统输入输出关系的差分方程，求单位序列响应 $h(k)$；（2）确定系统函数 $H(z)$，画零极点分布图；（3）画出幅频特性 $|H(e^{j\\theta})|\\sim\\theta$ 曲线，需标明特征频点处的幅频响应值。[图2-3：反馈系数 0.5 与 0.06 的二阶离散系统框图]","img":"pro-img/2023_p04.jpg","a":"（1）$y(k)+0.5y(k-1)+0.06y(k-2)=f(k)$；$h(k)=[-2(-0.2)^k+3(-0.3)^k]\\varepsilon(k)$；（2）$H(z)=\\frac{1}{1+0.5z^{-1}+0.06z^{-2}}=\\frac{z^2}{(z+0.2)(z+0.3)}$，极点 $z=-0.2,\\ -0.3$（均在单位圆内）；（3）$|H(e^{j0})|=\\frac{1}{1.56}\\approx0.641$，$|H(e^{j\\pi})|=\\frac{1}{0.56}\\approx1.786$","s":"由框图 $Y(z)+0.5z^{-1}Y(z)+0.06z^{-2}Y(z)=F(z)$，故差分方程 $y(k)+0.5y(k-1)+0.06y(k-2)=f(k)$。$H(z)=\\frac{z^2}{z^2+0.5z+0.06}=\\frac{z^2}{(z+0.2)(z+0.3)}$，部分分式展开得 $h(k)=[-2(-0.2)^k+3(-0.3)^k]\\varepsilon(k)$。"},{"id":"r23-13","seq":13,"part":"信号","qt":"解答","pts":7,"ch":"ss-state","q":"如图2-4所示为某 LTI 因果连续系统的信号流图：（1）写出以 $x_1(t)$ 和 $x_2(t)$ 作为状态变量的状态方程和输出方程。（2）求使系统保持稳定的参数 $\\alpha$ 取值范围。（3）画出 $\\alpha=-2$ 时系统的直接型流图。[图2-4：含参数 $\\alpha$、增益 5、分支 $s+\\alpha$、$s+3$、$s+1$ 的信号流图（状态方程原文不清，以图为准）]","img":"pro-img/2023_p04.jpg","a":"（2）系统函数 $H(s)=\\frac{-\\alpha}{s^2+(\\alpha+3)s+\\alpha+6}$；稳定条件 $\\alpha+3>0$ 且 $\\alpha+6>0$，即 $\\alpha>-3$；（3）$\\alpha=-2$ 时 $H(s)=\\frac{2}{s^2+s+4}$，直接型流图分母为 $s^2+s+4$、分子为 2。状态方程/输出方程原文不清（以图2-4为准）。","s":"特征多项式 $A(s)=s^2+(\\alpha+3)s+\\alpha+6$，稳定需 $\\alpha+3>0,\\alpha+6>0$，故 $\\alpha>-3$。$\\alpha=-2$ 时 $H(s)=\\frac{2}{s^2+s+4}$。"},{"id":"r23-14","seq":14,"part":"信号","qt":"解答","pts":5,"ch":"ss-freq","q":"如图2-5所示是模拟无线通信中正交复用调制解调系统：（1）$f_1(t),f_2(t)$ 是不同实带限信号，最高频率为 $f_m$；（2）$s_1(t),s_2(t)$ 是调制载波，分别有 $s_1(t)=\\cos(2\\pi f_0 t)$，$s_2(t)=\\sin(2\\pi f_0 t)$，载波频率 $f_0\\gg f_m$；（3）$h_c(t)$ 是无线信道，这里是理想的，即 $h_c(t)=\\delta(t)$；（4）$h_r(t)$ 是接收端的解调滤波器，是理想低通滤波器，其频率响应函数 $H_r(j\\omega)=\\begin{cases}2,&|\\omega|<2\\pi f_c\\\\0,&|\\omega|>2\\pi f_c\\end{cases}$，此处截止频率 $f_c$ 满足 $f_m<f_c<2f_0-f_m$。试证明：$\\hat{f}_1(t)=f_1(t)$，$\\hat{f}_2(t)=f_2(t)$。[图2-5：正交复用发送/调制器、信道、接收/解调器框图]","img":"pro-img/2023_p04.jpg","a":"发送信号 $s(t)=f_1(t)\\cos(2\\pi f_0 t)+f_2(t)\\sin(2\\pi f_0 t)$；接收同相支路乘 $\\cos(2\\pi f_0 t)$ 得 $s(t)\\cos(2\\pi f_0 t)=\\frac12 f_1(t)+\\frac12 f_1(t)\\cos(4\\pi f_0 t)+\\frac12 f_2(t)\\sin(4\\pi f_0 t)$，经增益 2 的理想低通滤除 $2f_0$ 附近分量得 $\\hat{f}_1(t)=f_1(t)$；正交支路同理 $\\hat{f}_2(t)=f_2(t)$。","s":"利用三角恒等式 $\\cos^2 x=\\frac{1+\\cos2x}{2}$、$\\sin x\\cos x=\\frac12\\sin2x$；由 $f_m<f_c<2f_0-f_m$，低通滤波器只保留基带分量（$|\\omega|<2\\pi f_c$），滤除 $2f_0$ 附近的高频项。"},{"id":"r25-01","seq":1,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"$\\int_{-\\infty}^{\\infty}(1-x)\\delta'(x)\\,\\mathrm{d}x=$ ____","img":"pro-img/2025_q01.jpg","a":"","s":""},{"id":"r25-02","seq":2,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"已知 $f(5-2t)=2\\delta(t-3)$，求 $\\int_{-\\infty}^{\\infty}f(t)\\,\\mathrm{d}t=$ ____","img":"pro-img/2025_q01.jpg","a":"","s":""},{"id":"r25-03","seq":3,"part":"信号","qt":"填空","pts":4,"ch":"ss-cont-time","q":"$h(t)$ 是系统的冲激响应，$f(t)$ 是系统的输入，$y$ 是零状态响应，求 $y$ 在 $0$ 和 $4$ 处的值。[图：$h(t)$ 与 $f(t)$ 波形，见图]","img":"pro-img/2025_q20.jpg","a":"","s":""},{"id":"r25-04","seq":4,"part":"信号","qt":"填空","pts":4,"ch":"ss-sdomain","q":"已知 $F(s)$（表达式见图），求 $f(t)$。[图：$F(s)$ 表达式，见图]","img":"pro-img/2025_q21.jpg","a":"","s":""},{"id":"r25-05","seq":5,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"$\\int_{-\\infty}^{\\infty}F(j\\omega)\\,\\mathrm{Sa}(2\\omega)e^{j\\omega t}\\,\\mathrm{d}\\omega=$ ____ [图：$f(t)$ 波形，见图]","img":"pro-img/2025_q22.jpg","a":"","s":""},{"id":"r25-06","seq":6,"part":"信号","qt":"填空","pts":4,"ch":"ss-zdomain","q":"求 $\\sum_{m=0}^{\\infty}2^{m}u(k-m)$ 的 Z 变换。（原文不清，以图为准）","img":"pro-img/2025_q23.jpg","a":"","s":""},{"id":"r25-07","seq":7,"part":"信号","qt":"填空","pts":4,"ch":"ss-zdomain","q":"离散因果系统，求 $H(z)$。[图：系统信号流图，见图]","img":"pro-img/2025_q24.jpg","a":"","s":""},{"id":"r25-08","seq":8,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"由 $H(j\\omega)$ 的幅频特性 $|H(j\\omega)|$ 图求冲激响应 $h(t)$。[图：$|H(j\\omega)|$ 幅频特性，见图]","img":"pro-img/2025_q25.jpg","a":"","s":""},{"id":"r25-09","seq":9,"part":"信号","qt":"解答","pts":9,"ch":"ss-freq","q":"$f(t)$ 的周期为 8，$F_n$ 为 $f(t)$ 的傅里叶系数，$F_1=F_{-1}=2$，$F_3=F_{-3}=4j$（其余为 0，原文不清以图为准）。(1) 写出 $f(t)=\\sum_{n=0}^{\\infty}A_n\\cos(n\\Omega t+\\varphi_n)$ 的形式；(2) $f(t)$ 经过图示系统后的 $y(t)$ 是什么；(3) 经过系统后 $y(t)$ 有无失真。[图：系统 $H(j\\omega)$ 频率特性，见图]","img":"pro-img/2025_q26.jpg","a":"","s":""},{"id":"r25-10","seq":10,"part":"信号","qt":"解答","pts":12,"ch":"ss-freq","q":"(1) 求奈奎斯特频率；(2) 用 $T_s=\\dfrac{\\pi}{12}$ s 和 $T_s=\\dfrac{\\pi}{8}$ s 分别抽样，分别画出频谱 $F(j\\omega)$；(3) 有如下系统 $P(t)=\\sum_{n=-\\infty}^{\\infty}\\delta(t-nT)$，求 $y(t)$ 表达式。[图：系统 $f(t)\\to H(j\\omega)\\to\\times P(t)\\to y(t)$，$H(j\\omega)$ 为理想低通，见图]","img":"pro-img/2025_q02.jpg","a":"","s":""},{"id":"r25-11","seq":11,"part":"信号","qt":"解答","pts":12,"ch":"ss-zdomain","q":"已知 $H(1)=2$（原文不清，疑为 $H(\\infty)=2$）。(1) 求 $H(z)$；(2) 求 $h(k)$；(3) …（原文不清）。[图：零极点分布图，极点在 $z=0.5$ 与 $z=-0.5$，见图]","img":"pro-img/2025_q04.jpg","a":"","s":""},{"id":"r25-12","seq":12,"part":"信号","qt":"解答","pts":10,"ch":"ss-state","q":"(1) 求状态方程、输出方程；(2) $a,b$ 满足什么条件系统稳定。[图：系统框图含 $\\frac{1}{s+a}$、$\\frac{1}{s+b}$、$\\frac{1}{s+1}$ 环节，状态变量 $x_1(t)$、$x_2(t)$，输入 $f(t)$，输出 $y(t)$，见图]","img":"pro-img/2025_q05.jpg","a":"","s":""},{"id":"fs18-01","seq":1,"part":"信号","qt":"选择","pts":3,"ch":"ss-intro","q":"积分 $\\int_{-\\infty}^{\\infty}\\sin t\\,\\delta(t-5)\\,dt$ 等于（ ）","o":["A. $\\sin 5\\,\\delta(t-5)$","B. $\\sin 5$","C. $\\sin 5\\,\\varepsilon(t)$","D. $\\sin t\\,\\varepsilon(t-5)$"],"img":"pro-img/final-sig_p32.jpg","a":"B","s":"由冲激函数取样性质：$\\int_{-\\infty}^{\\infty}\\sin t\\,\\delta(t-5)dt=\\sin 5$。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-02","seq":2,"part":"信号","qt":"选择","pts":3,"ch":"ss-intro","q":"某离散系统的输入 $f(k)$ 与输出 $y(k)$ 满足 $y(k)+y(k-1)y(k-2)=f(k)$，则该系统是（ ）","o":["A. 时变非线性","B. 时不变非线性","C. 时变线性","D. 时不变线性"],"img":"pro-img/final-sig_p32.jpg","a":"B","s":"含乘积项 $y(k-1)y(k-2)$，为非线性；系数均为常数，为时不变。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-03","seq":3,"part":"信号","qt":"选择","pts":3,"ch":"ss-cont-time","q":"信号 $f_1(t)$ 和信号 $f_2(t)$ 的波形如题3图所示，设 $f(t)=f_1(t)*f_2(t)$，则 $f(3)$ 等于（ ）[题3图：两矩形/波形信号 $f_1(t)$ 与 $f_2(t)$，作卷积]","o":["A. 2","B. 6","C. 5","D. 4"],"img":"pro-img/final-sig_p32.jpg","a":"","s":"需按卷积图计算重叠面积，OCR 无法还原 $f_1(t),f_2(t)$ 具体波形，原文不清。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-04","seq":4,"part":"信号","qt":"选择","pts":3,"ch":"ss-freq","q":"周期信号 $f(k)$ 的波形如题4图所示，其傅里叶级数的系数 $F_0$ 等于（ ）[题4图：离散周期序列波形]","o":["A. 0","B. 0.5","C. 1","D. 2"],"img":"pro-img/final-sig_p32.jpg","a":"","s":"$F_0$ 为周期内直流分量（平均值），需按原图取值，OCR 无法还原，原文不清。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-05","seq":5,"part":"信号","qt":"选择","pts":3,"ch":"ss-freq","q":"信号 $f(t)=\\cos(2t)+3\\cos(15t)$，则对下列信号进行均匀采样时，其奈奎斯特角频率等于 10 rad/s 的是（ ）","o":["A. $2f(t)$","B. $f^2(t)$","C. $f(3t)$","D. $f(t/3)$"],"img":"pro-img/final-sig_p32.jpg","a":"D","s":"$f(t/3)=\\cos(\\tfrac{2}{3}t)+3\\cos(5t)$，最高角频率 $5$ rad/s，奈奎斯特角频率 $2\\times5=10$ rad/s。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-06","seq":6,"part":"信号","qt":"选择","pts":3,"ch":"ss-sdomain","q":"信号 $f(t)=e^{-3t}\\varepsilon(t)$ 的拉普拉斯变换以及收敛域为（ ）","o":["A. $\\frac{1}{s+3},\\ \\mathrm{Re}[s]>3$","B. $\\frac{1}{s-3},\\ \\mathrm{Re}[s]>3$","C. $\\frac{1}{s+3},\\ \\mathrm{Re}[s]>-3$","D. $\\frac{1}{s-3},\\ \\mathrm{Re}[s]>-3$"],"img":"pro-img/final-sig_p32.jpg","a":"C","s":"$\\mathcal{L}[e^{-3t}\\varepsilon(t)]=\\dfrac{1}{s+3}$，收敛域 $\\mathrm{Re}[s]>-3$。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-07","seq":7,"part":"信号","qt":"选择","pts":3,"ch":"ss-sdomain","q":"以下为四个因果信号的拉普拉斯变换，其中不存在傅里叶变换的是（ ）","o":["A. $\\frac{1}{s+2}$","B. $\\frac{1}{s-2}$","C. $\\frac{1}{s+4}$","D. $\\frac{1}{s+1}$"],"img":"pro-img/final-sig_p33.jpg","a":"B","s":"$\\frac{1}{s-2}$ 极点在右半平面（$s=2$），收敛域 $\\mathrm{Re}[s]>2$ 不含虚轴，故无傅里叶变换。（选项据 OCR 残片复原）","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-08","seq":8,"part":"信号","qt":"选择","pts":3,"ch":"ss-zdomain","q":"已知某因果序列 $f(k)$ 的 z 变换 $F(z)=\\dfrac{z^4-1}{z^3(z-1)}$，则 $f(k)$ 等于（ ）","o":["A. $\\delta(k)-\\delta(k-4)$","B. $\\varepsilon(k)-\\varepsilon(k-4)$","C. $\\delta(k)-\\delta(k-3)$","D. $\\delta(k-3)-\\delta(k-7)$"],"img":"pro-img/final-sig_p33.jpg","a":"B","s":"$F(z)=\\frac{z^4-1}{z^3(z-1)}=1+z^{-1}+z^{-2}+z^{-3}$，故 $f(k)=\\delta(k)+\\delta(k-1)+\\delta(k-2)+\\delta(k-3)=\\varepsilon(k)-\\varepsilon(k-4)$。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-09","seq":9,"part":"信号","qt":"选择","pts":3,"ch":"ss-zdomain","q":"已知 $f(k)$ 象函数 $F(z)=\\dfrac{2z}{(z+0.6)(z+3)}$，则 $F(z)$ 的收敛域为何值时，$f(k)$ 为因果序列（ ）","o":["A. $|z|>0.6$","B. $|z|<3$","C. $|z|>3$","D. $0.6<|z|<3$"],"img":"pro-img/final-sig_p33.jpg","a":"C","s":"极点为 $z=-0.6,\\ z=-3$（模 0.6 与 3），因果序列收敛域为最外极点之外：$|z|>3$。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-10","seq":10,"part":"信号","qt":"选择","pts":3,"ch":"ss-sdomain","q":"已知 $f(t)$ 的单边拉普拉斯变换 $F(s)=\\dfrac{e^{-(s+3)}}{s+3}$，则原函数 $f(t)$ 为（ ）","o":["A. $e^{-3(t-1)}\\varepsilon(t-1)$","B. $e^{-3(t-3)}\\varepsilon(t-3)$","C. $e^{-3t}\\varepsilon(t-1)$","D. $e^{-3t}\\varepsilon(t-3)$"],"img":"pro-img/final-sig_p33.jpg","a":"C","s":"$\\frac{1}{s+3}\\leftrightarrow e^{-3t}\\varepsilon(t)$；乘 $e^{-s}$ 延时 1，再乘常数 $e^{-3}$：$e^{-3}e^{-3(t-1)}=e^{-3t}$，故 $f(t)=e^{-3t}\\varepsilon(t-1)$。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-11","seq":11,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"已知 $f(t)$ 波形如题11图所示，设 $g(t)=\\dfrac{df(t)}{dt}$，试画出 $g(2t-1)$ 的波形。[题11图：$f(t)$ 波形]","o":[],"img":"pro-img/final-sig_p33.jpg","a":"","s":"先由 $f(t)$ 求导得 $g(t)$，再经时间变换（平移、尺度）得 $g(2t-1)$ 波形；原图波形 OCR 无法还原，需按图作图。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-12","seq":12,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"已知信号 $f(t)$ 的最高频率 $f_m=100$ Hz，若对 $f(t)+f^2(t)$ 进行取样，则最小取样频率 $f_s$ 为 ____。","o":[],"img":"pro-img/final-sig_p33.jpg","a":"400 Hz","s":"$f^2(t)$ 最高频率 $2\\times100=200$ Hz，故最小取样频率 $f_s\\ge 2\\times200=400$ Hz。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-13","seq":13,"part":"信号","qt":"填空","pts":4,"ch":"ss-zdomain","q":"序列 $f(k)=\\sum_{i=0}^{k}(-1)^{i}$ 的单边 z 变换 $F(z)$ 等于 ____。","o":[],"img":"pro-img/final-sig_p33.jpg","a":"$\\dfrac{z^2}{z^2-1}$","s":"$f(k)=1,0,1,0,\\cdots$（$k$ 为偶数取 1），$F(z)=\\sum_{n=0}^{\\infty}z^{-2n}=\\dfrac{1}{1-z^{-2}}=\\dfrac{z^2}{z^2-1}$。（题干含求和号，OCR 残缺，按答案页反推）","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-14","seq":14,"part":"信号","qt":"填空","pts":4,"ch":"ss-sdomain","q":"单边拉普拉斯变换 $F(s)=\\dfrac{2}{s^2+3s+2}$ 的原函数 $f(t)$ 为 ____。","o":[],"img":"pro-img/final-sig_p33.jpg","a":"$2(e^{-t}-e^{-2t})\\varepsilon(t)$","s":"$\\frac{2}{s^2+3s+2}=\\frac{2}{(s+1)(s+2)}=\\frac{2}{s+1}-\\frac{2}{s+2}$，故 $f(t)=2(e^{-t}-e^{-2t})\\varepsilon(t)$。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-15","seq":15,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"若信号 $f(t)$ 的傅里叶变换为 $F(j\\omega)$，则信号 $f(3-2t)$ 的傅里叶变换为 ____。","o":[],"img":"pro-img/final-sig_p33.jpg","a":"$\\tfrac{1}{2}e^{-j\\frac{3}{2}\\omega}F\\!\\left(-j\\tfrac{\\omega}{2}\\right)$","s":"$f(-2t+3)$：$f(at+b)\\leftrightarrow \\frac{1}{|a|}e^{j\\frac{b}{a}\\omega}F(j\\frac{\\omega}{a})$，取 $a=-2,b=3$ 得 $\\frac12 e^{-j\\frac32\\omega}F(-j\\frac{\\omega}{2})$。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-16","seq":16,"part":"信号","qt":"解答","pts":10,"ch":"ss-sdomain","q":"已知某 LTI 系统的阶跃响应 $g(t)=(1-e^{-2t})\\varepsilon(t)$，欲使系统的零状态响应为 $y_{zs}(t)=(1-e^{-2t}+te^{-2t})\\varepsilon(t)$，求系统的输入信号 $f(t)$。","o":[],"img":"pro-img/final-sig_p34.jpg","a":"$f(t)=\\left(1+\\tfrac12 e^{-2t}\\right)\\varepsilon(t)$","s":"$H(s)=sG(s)=\\frac{2}{s+2}$；$Y_{zs}(s)=\\frac1s-\\frac{1}{s+2}+\\frac{1}{(s+2)^2}$；$F(s)=\\frac{Y_{zs}(s)}{H(s)}=\\frac1s+\\frac{1}{2(s+2)}$，故 $f(t)=(1+\\frac12 e^{-2t})\\varepsilon(t)$。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-17","seq":17,"part":"信号","qt":"解答","pts":10,"ch":"ss-zdomain","q":"已知某 LTI 离散系统的差分方程为 $y(k)-1.5y(k-1)-y(k-2)=f(k-1)$。(1) 若该系统为因果系统，求该系统的单位序列响应；(2) 若系统函数 $H(z)$ 的收敛域包含单位圆，求系统的单位序列响应，并计算当输入为 $f(k)=(-0.5)^k\\varepsilon(k)$ 时系统的零状态响应 $y_{zs}(k)$。","o":[],"img":"pro-img/final-sig_p34.jpg","a":"(1) $h(k)=0.4[2^k-(-0.5)^k]\\varepsilon(k)$；(2) $h(k)=-0.4(-0.5)^k\\varepsilon(k)-0.4\\cdot2^k\\varepsilon(-k-1)$；$y_{zs}(k)=-0.32\\cdot2^k\\varepsilon(-k-1)+\\left[0.2k(-0.5)^{k-1}-0.32(-0.5)^k\\right]\\varepsilon(k)$","s":"零状态 z 变换：$H(z)=\\frac{z^{-1}}{1-1.5z^{-1}-z^{-2}}=\\frac{z}{(z-2)(z+0.5)}$，极点 $2,\\ -0.5$。因果 $|z|>2$；含单位圆 $0.5<|z|<2$。$F(z)=\\frac{z}{z+0.5}$，$Y_{zs}(z)=\\frac{z^2}{(z-2)(z+0.5)^2}$ 部分分式展开后反变换。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-18","seq":18,"part":"信号","qt":"解答","pts":10,"ch":"ss-freq","q":"如题18(a)图所示系统，滤波器的频率响应函数如题18(b)图所示，其相频特性为 0（零相位）。试求系统输出 $y(t)$。[题18(a)图：$f(t)$ 经滤波器 $H(j\\omega)$ 后与 $s(t)$ 相乘得 $y(t)$ 的系统框图][题18(b)图：滤波器幅频特性 $|H(j\\omega)|$，相频 $\\varphi(\\omega)=0$]","o":[],"img":"pro-img/final-sig_p35.jpg","a":"$y(t)=\\dfrac{\\sin t}{2\\pi t}$","s":"$F(j\\omega)=\\tfrac12 g(\\omega+1000)+\\tfrac12 g(\\omega-1000)$；令 $f_1(t)=f(t)s(t)=f(t)\\cos(\\omega_0t)$，$F_1(j\\omega)=\\tfrac12[g(\\omega+200)+g(\\omega-200)]+g(\\omega)$；$Y(j\\omega)=F(j\\omega)H(j\\omega)=\\tfrac12 g(\\omega)$，故 $y(t)=\\dfrac{\\sin t}{2\\pi t}$。（题干 OCR 严重残缺，按答案页残句复原，需核对原图）","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-19","seq":19,"part":"信号","qt":"解答","pts":10,"ch":"ss-sdomain","q":"已知如题19图所示的稳态电路，$t=0$ 时，开关 S 由 1 打向 2，求 $t\\ge0$ 以后的 $u_{zi}(t)$ 和 $u_{zs}(t)$。[题19图：含电压源 2V、电感、电容、电阻的换路电路]","o":[],"img":"pro-img/final-sig_p36.jpg","a":"$u_{zi}(t)=(5e^{-t}-3e^{-2t})\\varepsilon(t)$；$u_{zs}(t)=(c-2e^{-t}-e^{-2t})\\varepsilon(t)$（$c$ 为直流稳态分量，原文系数不清）","s":"$t=0_-$ 稳态：$u_c(0_-)=2V$，$i_L(0_-)=1A$。$U_{zi}(s)=\\frac{2s+7}{(s+1)(s+2)}=\\frac{5}{s+1}-\\frac{3}{s+2}$；$U_{zs}(s)=\\frac{\\cdot}{s(s+1)(s+2)}$（分子系数 OCR 不清）。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs18-20","seq":20,"part":"信号","qt":"解答","pts":10,"ch":"ss-state","q":"某 LTI 离散系统的差分方程为 $y(k)-1.5y(k-1)-y(k-2)=f(k-1)$。试求：(1) 系统函数 $H(z)$；(2) 系统为因果系统时 $h(k)$；(3) 系统为稳定系统时 $h(k)$；(4) 画出该系统的信号流图；(5) 列出其状态方程和输出方程，用矩阵形式表示。","o":[],"img":"pro-img/final-sig_p37.jpg","a":"(1) $H(z)=\\dfrac{z}{z^2-1.5z-1}=\\dfrac{z}{(z-2)(z+0.5)}$；(2) 因果（$|z|>2$）：$h(k)=0.4[2^k-(-0.5)^k]\\varepsilon(k)$；(3) 稳定（$0.5<|z|<2$）：$h(k)=-0.4(-0.5)^k\\varepsilon(k)-0.4\\cdot2^k\\varepsilon(-k-1)$；(4) 直接Ⅱ型信号流图；(5) $\\begin{bmatrix}x_1(k+1)\\\\x_2(k+1)\\end{bmatrix}=\\begin{bmatrix}1.5&1\\\\1&0\\end{bmatrix}\\begin{bmatrix}x_1(k)\\\\x_2(k)\\end{bmatrix}+\\begin{bmatrix}1\\\\0\\end{bmatrix}f(k)$，$y(k)=\\begin{bmatrix}1&0\\end{bmatrix}\\begin{bmatrix}x_1(k)\\\\x_2(k)\\end{bmatrix}$","s":"极点 $z_1=2,\\ z_2=-0.5$；按极点反推状态矩阵（答案页 OCR 严重缺损，分子/差分方程右侧系数以 $f(k-1)$ 为准）。","t":"期末","y":2018,"src":"西电信号2018期末"},{"id":"fs19-01","seq":1,"part":"信号","qt":"选择","pts":3,"ch":"ss-intro","q":"序列和 $\\sum_{n=-\\infty}^{\\infty}\\delta(n-2)$ 等于（ ）","o":["A. 1","B. $\\varepsilon(k-2)$","C. $\\varepsilon(k)$","D. $\\delta(k-2)$"],"img":"pro-img/final-sig_p27.jpg","a":"A","s":"单位样值序列在 $n=2$ 处取值 1，全区间求和为 1。（题干含「sin」OCR 噪声，按选项反推为 $\\delta(n-2)$ 求和）","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-02","seq":2,"part":"信号","qt":"选择","pts":3,"ch":"ss-freq","q":"对信号 $f(t)=\\dfrac{\\sin(\\pi t)}{\\pi t}$ 进行均匀抽样的 Nyquist 抽样间隔 $T_s$ 等于（ ）","o":["A. 1","B. $\\pi$","C. $\\dfrac{\\pi}{2}$","D. $2\\pi$"],"img":"pro-img/final-sig_p27.jpg","a":"A","s":"$f(t)=\\mathrm{Sa}(\\pi t)$ 带宽 $\\omega_m=\\pi$，Nyquist 间隔 $T_s=\\dfrac{\\pi}{\\omega_m}=1$。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-03","seq":3,"part":"信号","qt":"选择","pts":3,"ch":"ss-intro","q":"关于功率信号和能量信号，下列说法不正确的是（ ）","o":["A. 功率信号的功率有限，能量无穷大","B. 能量信号的能量有限，功率为零","C. 功率信号不可能是能量信号","D. 信号要么是功率信号，要么是能量信号"],"img":"pro-img/final-sig_p27.jpg","a":"D","s":"存在既非能量信号也非功率信号的信号（如 $e^t\\varepsilon(t)$ 等功率、能量均无穷的信号），故 D 说法不正确。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-04","seq":4,"part":"信号","qt":"选择","pts":3,"ch":"ss-intro","q":"下列微分或差分方程所描述的系统中，为线性时变系统的是（ ）","o":["A. $y'(t)+3y(t)=f'(t)+2f(t)$","B. $y'(t)+(1-t)y(t)=2f(t)$","C. $y(k)+(1+k)y(k-1)=f(k-1)$","D. $y(k)+2y(k-1)y(k-2)=f(k)$"],"img":"pro-img/final-sig_p27.jpg","a":"B","s":"B 中系数 $(1-t)$ 随时间变化，且 $y$ 项线性，为线性时变系统。（注：选项 C 也含时变系数 $(1+k)$，同为线性时变，OCR 题干若为「线性时不变」则选 A，此处按题干「线性时变」选 B，需核对原卷）","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-05","seq":5,"part":"信号","qt":"选择","pts":3,"ch":"ss-freq","q":"如图所示信号 $f(t)$ 的傅里叶变换记为 $F(j\\omega)$，则 $\\int_{-\\infty}^{\\infty}F(j\\omega)\\,d\\omega$ 等于（ ）[题5图：信号 $f(t)$ 波形]","o":["A. 0","B. $2\\pi$","C. $4\\pi$","D. $\\pi$"],"img":"pro-img/final-sig_p27.jpg","a":"","s":"$\\int_{-\\infty}^{\\infty}F(j\\omega)d\\omega=2\\pi f(0)$，需按图中 $f(0)$ 取值确定，OCR 无法还原波形，原文不清。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-06","seq":6,"part":"信号","qt":"选择","pts":3,"ch":"ss-cont-time","q":"对于连续 LTI 系统，以下说法正确的是（ ）","o":["A. 稳定系统的系统频率响应不一定存在","B. 系统自由响应的象函数极点是输入信号象函数的极点","C. 系统强迫响应的象函数极点是系统特征根（系统函数的极点）","D. 若该系统因果稳定，则该系统的自由响应就是瞬态响应"],"img":"pro-img/final-sig_p27.jpg","a":"D","s":"因果稳定系统的自由（自然）响应随时间衰减，即瞬态响应；A/B/C 均与定义相反。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-07","seq":7,"part":"信号","qt":"选择","pts":3,"ch":"ss-sdomain","q":"已知某连续系统的系统函数零极点分布位置如题7图所示，以下说法正确的是（ ）[题7图：系统函数零极点分布图]","o":["A. 若系统是因果的，则该系统不稳定","B. 若系统是反因果的，则该系统稳定","C. 若该系统稳定，无法判断系统因果性","D. 以上说法都错"],"img":"pro-img/final-sig_p27.jpg","a":"","s":"需按零极点图（极点位于左/右半平面）判断因果/稳定关系，OCR 无法还原图形，原文不清。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-08","seq":8,"part":"信号","qt":"选择","pts":3,"ch":"ss-zdomain","q":"已知系统函数 $H(z)=\\dfrac{z}{z^2-1.5z-1}$，对应的系统稳定，则该系统的收敛域为（ ）","o":["A. $|z|>0$","B. $0.5<|z|<2$","C. $|z|>2$","D. $|z|<0.5$"],"img":"pro-img/final-sig_p28.jpg","a":"B","s":"极点 $z=2,\\ z=-0.5$（模 2 与 0.5），系统稳定要求收敛域包含单位圆：$0.5<|z|<2$。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-09","seq":9,"part":"信号","qt":"选择","pts":3,"ch":"ss-freq","q":"某信号的频谱是非周期的连续谱，则该信号是（ ）","o":["A. 连续的周期信号","B. 离散的周期信号","C. 连续的非周期信号","D. 离散的非周期信号"],"img":"pro-img/final-sig_p28.jpg","a":"C","s":"连续非周期信号 $\\leftrightarrow$ 非周期连续谱（傅里叶变换）；周期信号对应离散谱，离散非周期信号对应周期连续谱。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-10","seq":10,"part":"信号","qt":"选择","pts":3,"ch":"ss-freq","q":"已知某连续系统的频率响应是 $H(j\\omega)=e^{-j\\omega}g_2(\\omega)$，输入信号 $f(t)=2\\sin t+\\cos 2t$ 经过该系统后，下列说法正确的是（ ）","o":["A. $f(t)$ 经过该系统后会出现幅度失真","B. $f(t)$ 经过该系统后会出现相位失真","C. $f(t)$ 经过该系统后幅度和相位都不会出现失真","D. $f(t)$ 经过该系统后幅度和相位都会出现失真"],"img":"pro-img/final-sig_p28.jpg","a":"A","s":"$e^{-j\\omega}$ 为线性相位（无相位失真），但门函数 $g_2(\\omega)$ 使 $\\omega=2$ 分量（$\\cos2t$）被滤除，产生幅度失真。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-11","seq":11,"part":"信号","qt":"填空","pts":4,"ch":"ss-sdomain","q":"已知连续信号 $f(t)$ 的单边拉普拉斯变换是 $F(s)=\\dfrac{se^{-s}}{s^2+4}$，则信号 $f(t)=$ ____。","o":[],"img":"pro-img/final-sig_p28.jpg","a":"$\\cos(2t-2)\\varepsilon(t-1)$","s":"$\\frac{s}{s^2+4}\\leftrightarrow\\cos(2t)$，乘 $e^{-s}$ 延时 1：$f(t)=\\cos[2(t-1)]\\varepsilon(t-1)=\\cos(2t-2)\\varepsilon(t-1)$。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-12","seq":12,"part":"信号","qt":"填空","pts":4,"ch":"ss-zdomain","q":"序列 $f(k)=2^k\\varepsilon(k)$，则 $f(k-4)\\varepsilon(k-4)=$ ____。","o":[],"img":"pro-img/final-sig_p28.jpg","a":"$2^{k-4}\\varepsilon(k-4)$","s":"移位性质：$f(k-4)\\varepsilon(k-4)=2^{k-4}\\varepsilon(k-4)$。（题干 OCR 仅存「序列 f(k)=2k」，按答案页「2^{k-4}」反推）","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-13","seq":13,"part":"信号","qt":"填空","pts":4,"ch":"ss-zdomain","q":"已知两个离散信号 $f_1(k)$ 和 $f_2(k)$ 如题13图所示，则卷积和 $f_1(k)*f_2(k)=$ ____。[题13图：$f_1(k)$ 与 $f_2(k)$ 序列波形，横轴 3,4,5,6]","o":[],"img":"pro-img/final-sig_p28.jpg","a":"$\\{0,2,1,2,0,2,5,2,2,4,4,0\\}$","s":"答案页给出卷积和序列「0,2,1,2,0,2,5,2,2,4,4,0」（OCR 中 20/25/22 疑为 2,0/2,5/2,2 粘连），需核对原图序列。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-14","seq":14,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"已知信号 $f(t)$ 波形如题14图所示，$g(t)=\\dfrac{df(t)}{dt}$，试写出 $g(t)$ 的表达式为：____。[题14图：$f(t)$ 波形]","o":[],"img":"pro-img/final-sig_p28.jpg","a":"$g(t)=(t+2)\\varepsilon(t)-2\\delta(t-2)$","s":"对 $f(t)$ 求导得 $g(t)$；答案页 OCR 为「(t+2)ε(t)-2δ(t-2)」（原文有缺），需核对原图。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-15","seq":15,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"已知信号 $f(t)$ 的傅里叶变换为 $F(j\\omega)$，则信号 $t^2f(-2t)$ 对应的傅里叶变换为 ____。","o":[],"img":"pro-img/final-sig_p29.jpg","a":"$\\tfrac{1}{8}\\dfrac{d^2}{d\\omega^2}F\\!\\left(-j\\tfrac{\\omega}{2}\\right)$","s":"$f(-2t)\\leftrightarrow\\frac12F(-j\\frac{\\omega}{2})$；$t^2f(-2t)\\leftrightarrow-\\frac{d^2}{d\\omega^2}\\left[\\frac12F(-j\\frac{\\omega}{2})\\right]=\\frac18\\frac{d^2}{d\\omega^2}F(-j\\frac{\\omega}{2})$。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-16","seq":16,"part":"信号","qt":"解答","pts":6,"ch":"ss-freq","q":"设 $f(t)$ 是定义在时间 $(-\\infty,\\infty)$ 区间上的实能量信号，$F(j\\omega)$ 是 $f(t)$ 的傅里叶变换。试证明帕斯瓦尔方程 $\\int_{-\\infty}^{\\infty}f^2(t)dt=\\dfrac{1}{2\\pi}\\int_{-\\infty}^{\\infty}|F(j\\omega)|^2d\\omega$ 成立，并说明帕斯瓦尔方程的物理意义。","o":[],"img":"pro-img/final-sig_p29.jpg","a":"证明成立；物理意义：信号在时域与频域的总能量守恒（相等）。","s":"令 $f_1(t)=f(t)f(t)=f^2(t)$，则 $F_1(j\\omega)=\\frac{1}{2\\pi}F(j\\omega)*F(j\\omega)$，且 $F_1(j\\omega)=\\int f^2(t)e^{-j\\omega t}dt$，$F_1(0)=\\int f^2(t)dt$。$f(t)$ 为实信号时 $F(-j\\omega)=F^*(j\\omega)$，故 $F_1(0)=\\frac{1}{2\\pi}\\int F(j\\theta)F(-j\\theta)d\\theta=\\frac{1}{2\\pi}\\int|F(j\\omega)|^2d\\omega$，即得证。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-17","seq":17,"part":"信号","qt":"解答","pts":10,"ch":"ss-sdomain","q":"某连续 LTI 系统在输入 $f(t)=2\\delta(t)+6\\varepsilon(t)$ 时的零状态响应是 $y(t)=(3-4e^{-t}+e^{-2t})\\varepsilon(t)$。(1) 试利用拉普拉斯变换求解系统冲激响应 $h(t)$；(2) 如果系统初始状态为 $y(0_-)=2$，$y'(0_-)=1$，试求系统零输入响应 $y_{zi}(t)$。","o":[],"img":"pro-img/final-sig_p29.jpg","a":"(1) $h(t)=(e^{-t}-e^{-2t})\\varepsilon(t)$；(2) $y_{zi}(t)=(5e^{-t}-3e^{-2t})\\varepsilon(t)$","s":"(1) $F(s)=2+\\frac6s=\\frac{2(s+3)}{s}$，$Y_{zs}(s)=\\frac3s-\\frac4{s+1}+\\frac1{s+2}=\\frac{2(s+3)}{s(s+1)(s+2)}$，$H(s)=\\frac{Y_{zs}}{F}=\\frac{1}{(s+1)(s+2)}$，故 $h(t)=(e^{-t}-e^{-2t})\\varepsilon(t)$。(2) 特征方程 $\\lambda^2+3\\lambda+2=0$，$y_{zi}=C_1e^{-t}+C_2e^{-2t}$；由 $y_{zi}(0_+)=2$、$y'_{zi}(0_+)=1$ 得 $C_1=5,C_2=-3$。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-18","seq":18,"part":"信号","qt":"解答","pts":12,"ch":"ss-sdomain","q":"描述某 LTI 因果系统的微分方程为 $y''(t)+5y'(t)+6y(t)=5f(t)$。(1) 试求系统函数 $H(s)$，判断系统稳定性，并判断是否存在系统频率响应；(2) 在频率响应存在条件下，求系统频率响应 $H(j\\omega)$，并求解在输入为 $f(t)=2\\cos(t)\\varepsilon(t)$ 时系统的稳态响应 $y_{ss}(t)$。","o":[],"img":"pro-img/final-sig_p30.jpg","a":"(1) $H(s)=\\dfrac{5}{s^2+5s+6}=\\dfrac{5}{(s+2)(s+3)}$，极点 $-2,-3$ 在左半平面，因果系统稳定，存在频率响应；(2) $H(j\\omega)=\\dfrac{5}{6-\\omega^2+j5\\omega}$，$y_{ss}(t)=\\sqrt{2}\\cos(t-45^\\circ)$","s":"(1) 零状态拉氏变换：$H(s)=\\frac{5}{s^2+5s+6}$，极点 $s_1=-2,s_2=-3$，因果收敛域 $\\mathrm{Re}[s]>-2$ 含虚轴，系统稳定且存在频率响应。(2) $H(j\\omega)=\\frac{5}{6-\\omega^2+j5\\omega}$；$H(j1)=\\frac{1}{1+j}$，$|H(j1)|=\\frac{1}{\\sqrt2}$，$\\angle H(j1)=-45^\\circ$，故 $y_{ss}(t)=2\\cdot\\frac{1}{\\sqrt2}\\cos(t-45^\\circ)=\\sqrt2\\cos(t-45^\\circ)$。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-19","seq":19,"part":"信号","qt":"解答","pts":12,"ch":"ss-state","q":"某离散因果系统的信号流图如题19图所示。(1) 试求系统函数；(2) 分析系统的稳定性；(3) 求出系统差分方程；(4) 列写系统状态方程和输出方程的矩阵形式。[题19图：三延时器信号流图，增益含 0.5、-0.25，输入 $F(z)$、输出 $Y_{zs}(z)$]","o":[],"img":"pro-img/final-sig_p30.jpg","a":"(1) $H(z)=\\dfrac{B(z)}{1-0.5z^{-2}+0.25z^{-3}}$（分子 $B(z)$ 按信号流图确定）；(2) 由 Jury 判据 $A(1)>0$、$A(-1)>0$、$|0.25|<1$，因果系统稳定；(3) $y(k)-0.5y(k-2)+0.25y(k-3)=B(z)f(k)$ 对应差分方程；(4) 状态方程见解析。","s":"$A(z)=1-0.5z^{-2}+0.25z^{-3}$；延时器从左到右依次为 $x_1,x_2,x_3$，$x_1(k+1)=0.5x_2(k)-0.25x_3(k)+f(k)$，$x_2(k+1)=x_1(k)$，$x_3(k+1)=x_2(k)$（状态方程系数按答案页复原，需核对信号流图）；输出方程 $y(k)=[b_1\\ b_2\\ b_3][x_1\\ x_2\\ x_3]^T$。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs19-20","seq":20,"part":"信号","qt":"解答","pts":10,"ch":"ss-freq","q":"题20图(a)给出了一个正弦幅度调制和解调的通信系统。已知输入信号 $f(t)$ 的频谱 $F(j\\omega)$ 如图(b)所示，子系统 $H_1(j\\omega)$ 的频率响应由图(c)给出。(1) 画出系统中 A、B、C、D 各点信号的频谱图 $F_A(j\\omega)$、$F_B(j\\omega)$、$F_C(j\\omega)$ 和 $F_D(j\\omega)$；(2) 如图(a)所示，如果希望解调输出信号 $y(t)$ 与调制输入信号 $f(t)$ 相同，试画出子系统 $H_2(j\\omega)$ 频率响应图。[题20图(a)：$f(t)\\to\\times\\cos100t\\to H_1(j\\omega)\\to\\times\\cos100t\\to H_2(j\\omega)\\to y(t)$][题20图(b)：$F(j\\omega)$ 频谱，$|\\omega|\\le10$][题20图(c)：$H_1(j\\omega)$ 带通，$100\\le|\\omega|\\le120$]","o":[],"img":"pro-img/final-sig_p31.jpg","a":"(1) $F_A(j\\omega)=\\tfrac12F(j(\\omega+100))+\\tfrac12F(j(\\omega-100))$；$F_B(j\\omega)=F_A(j\\omega)H_1(j\\omega)$；$F_C(j\\omega)=\\tfrac12F_B(j(\\omega+100))+\\tfrac12F_B(j(\\omega-100))$；$F_D(j\\omega)=F_C(j\\omega)H_2(j\\omega)$。(2) $H_2(j\\omega)=\\begin{cases}4,&|\\omega|<\\omega_c\\\\0,&\\text{其它}\\end{cases}$，其中 $10<\\omega_c<20$。","s":"两次乘 $\\cos100t$ 各引入 $\\tfrac12$ 因子，总增益 $\\tfrac14$，故低通滤波器 $H_2(j\\omega)$ 取增益 4 以恢复原信号，截止频率 $\\omega_c$ 满足 $10<\\omega_c<20$（保留基带、滤除 $\\pm200$ 附近分量）。","t":"期末","y":2019,"src":"西电信号2019期末"},{"id":"fs20-01","seq":1,"part":"信号","qt":"选择","pts":3,"ch":"ss-intro","q":"1.（原题公式 OCR 严重不清，为冲激函数 $\\delta$ 与其导数 $\\delta'$ 的尺度变换/化简题）下列表达式化简结果等于（ ）。","o":["A. $\\tfrac14\\delta'(2t-2)+\\delta(t-1)$","B. $2\\delta'(t-1)$","C. $2\\delta(t-1)+2\\delta(t-1)$","D. $4\\delta'(t-1)+\\delta(t-1)$"],"img":"pro-img/final-sig_p19.jpg","a":"B","s":"冲激函数尺度变换：$\\delta(2t-2)=\\tfrac12\\delta(t-1)$、$\\delta'(2t-2)=\\tfrac14\\delta'(t-1)$；据此化简得 $2\\delta'(t-1)$，选 B。（答案页：1~4 题均为 B）","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-02","seq":2,"part":"信号","qt":"选择","pts":3,"ch":"ss-intro","q":"2. 以下序列关系式中不正确的是（ ）。","o":["A. $\\delta(k-1)=\\varepsilon(k-1)-\\varepsilon(k-2)$","B. $\\varepsilon(k)=\\sum_{i=-\\infty}^{k}\\delta(i-1)$","C. $\\delta(k)+\\delta(k-1)+\\delta(k-2)=\\varepsilon(k)-\\varepsilon(k-3)$","D. $\\delta(k-3)=\\delta(3-k)$"],"img":"pro-img/final-sig_p19.jpg","a":"B","s":"A：$\\delta(k-1)=\\varepsilon(k-1)-\\varepsilon(k-2)$ 正确；B：$\\sum_{i=-\\infty}^{k}\\delta(i-1)=\\varepsilon(k-1)\\neq\\varepsilon(k)$，故 B 不正确；C、D 均为基本恒等式，正确。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-03","seq":3,"part":"信号","qt":"选择","pts":3,"ch":"ss-sdomain","q":"3. 连续 LTI 系统框图如题 3 图所示 [题3图：含两级积分器与反馈系数 $a_0,a_1$、前向系数 $b_0,b_1$]，则其系统函数 $H(s)$ 为（ ）。","o":["A. $H(s)=\\dfrac{b_1s^2+b_0}{s^2-a_1s-a_0}$","B. $H(s)=\\dfrac{b_1s^2+b_0}{s^2+a_1s+a_0}$","C. $H(s)=\\dfrac{b_1+b_0s^2}{s^2-a_1s-a_0}$","D. $H(s)=\\dfrac{b_1+b_0s^2}{s^2+a_1s+a_0}$"],"img":"pro-img/final-sig_p19.jpg","a":"B","s":"由相变量型（直接型）框图，特征多项式为 $s^2+a_1s+a_0$，前向通路给出 $b_1s^2+b_0$，故 $H(s)=\\dfrac{b_1s^2+b_0}{s^2+a_1s+a_0}$，选 B。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-04","seq":4,"part":"信号","qt":"选择","pts":3,"ch":"ss-cont-time","q":"4. 序列 $f_1(k)$ 和 $f_2(k)$ 是时间有限序列，波形如题 4 图所示 [题4图：两有限长序列波形]，若 $f(k)=f_1(k)*f_2(k)$，则 $f(2)=$（ ）。","o":["A. 0","B. 2.5","C. 4","D. 4.5"],"img":"pro-img/final-sig_p19.jpg","a":"B","s":"由卷积和 $f(2)=\\sum_i f_1(i)f_2(2-i)$，结合波形逐点累加得 $f(2)=2.5$，选 B。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-05","seq":5,"part":"信号","qt":"选择","pts":3,"ch":"ss-freq","q":"5. 若 $f(t)\\leftrightarrow F(j\\omega)$，则 $\\dfrac{d}{dt}\\left[f(2t-3)e^{j2t}\\right]$ 的傅里叶变换为（ ）。","o":["A. $\\dfrac{j(\\omega-2)}{2}F\\left(j\\dfrac{\\omega-2}{2}\\right)e^{-j\\tfrac32(\\omega-2)}$","B. $\\dfrac{j(\\omega+2)}{2}F\\left(j\\dfrac{\\omega+2}{2}\\right)e^{-j\\tfrac32(\\omega+2)}$","C. $\\dfrac{j\\omega}{2}F\\left(j\\dfrac{\\omega-2}{2}\\right)e^{-j\\tfrac32(\\omega-2)}$","D. $\\dfrac{j\\omega}{2}F\\left(j\\dfrac{\\omega+2}{2}\\right)e^{j\\tfrac32(\\omega+2)}$"],"img":"pro-img/final-sig_p20.jpg","a":"C","s":"答案页 5~8 缺失，按标准结论推导：$f(2t-3)\\leftrightarrow\\tfrac12F(j\\omega/2)e^{-j3\\omega/2}$；乘 $e^{j2t}$ 频谱右移 2；再对 $t$ 求导乘 $j\\omega$，得 $\\tfrac{j\\omega}{2}F\\left(j\\tfrac{\\omega-2}{2}\\right)e^{-j\\tfrac32(\\omega-2)}$，选 C。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-06","seq":6,"part":"信号","qt":"选择","pts":3,"ch":"ss-sdomain","q":"6. 若 $f(t)\\leftrightarrow F(s)$，则 $t e^{-2t}f(t)\\varepsilon(t)$ 的（单边）拉普拉斯变换为（ ）。（原题公式 OCR 不清，据选项反推）","o":["A. $\\dfrac{d}{ds}\\left[(s+2)F(s+2)e^{-(s+2)}\\right]$","B. $\\dfrac{d}{ds}\\left[(s+2)F(s+2)e^{s+2}\\right]$","C. $\\dfrac{d}{ds}\\left[(s-2)F(s-2)e^{s-2}\\right]$","D. $-\\dfrac{d}{ds}F(s+2)$"],"img":"pro-img/final-sig_p20.jpg","a":"D","s":"答案页 5~8 缺失。由 $e^{-2t}f(t)\\leftrightarrow F(s+2)$，乘 $t$ 对应 $-\\dfrac{d}{ds}$，故 $t e^{-2t}f(t)\\leftrightarrow -\\dfrac{d}{ds}F(s+2)$，选 D。（选项原文 OCR 不清，答案以性质推导为准）","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-07","seq":7,"part":"信号","qt":"选择","pts":3,"ch":"ss-zdomain","q":"7. 序列 $f(k)$ 的双边 $z$ 变换为 $F(z)=\\dfrac{z^2+2z+5}{(z-1)(z-2)}$（原分母公式 OCR 不清），设序列 $f(k)$ 既非因果又非反因果，则以下收敛域形式中，（ ）是正确且可能的。","o":["A. $|z|>2$","B. $|z|<1$","C. $1<|z|<2$","D. $|z|>1$"],"img":"pro-img/final-sig_p20.jpg","a":"C","s":"答案页 5~8 缺失。$F(z)$ 极点 $z=1,2$；双边（既非因果又非反因果）序列的收敛域为极点之间的环形区域，即 $1<|z|<2$，选 C。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-08","seq":8,"part":"信号","qt":"选择","pts":3,"ch":"ss-freq","q":"8. 关于连续时间理想低通滤波器，以下陈述中不正确的是（ ）。","o":["A. 理想低通滤波器是幅频特性为“门函数”特性（门宽为 $2\\omega_c$，增益为常数，$\\omega_c$ 为截止频率）、相频特性为线性相位的实滤波器","B. 理想滤波器的冲激响应具有可能存在时移的 $\\mathrm{Sa}$ 函数形式","C. 对于信号带宽小于截止（角）频率的实信号，理想低通滤波器可以实现信号的无失真传输","D. 理想低通滤波器是物理可实现的"],"img":"pro-img/final-sig_p20.jpg","a":"D","s":"答案页 5~8 缺失。理想低通滤波器的冲激响应 $h(t)\\propto\\mathrm{Sa}(\\omega_c t)$ 在 $t<0$ 时非零（非因果），故物理不可实现，D 不正确。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-09","seq":9,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"9. 信号 $f(t)=e^{-2t}\\varepsilon(t)$ 是 ____（填“功率”或“能量”）信号，则其平均功率（或总能量）为 ____（结果请标明单位）。","img":"pro-img/final-sig_p20.jpg","a":"能量；总能量 $E=\\tfrac14$ J","s":"非周期、平方可积信号为能量信号，$E=\\int_0^{\\infty}e^{-4t}dt=\\tfrac14$（焦耳）。答案页：能量。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-10","seq":10,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"10. 序列 $f(k)=\\cos\\frac{7\\pi}{3}k+3\\sin\\left(\\frac{\\pi}{3}k\\right)$ 是 ____（填“周期”或“非周期”）信号，若为周期信号，其周期是 ____。（第二个正弦项角频率 OCR 不清）","img":"pro-img/final-sig_p20.jpg","a":"周期；$N=6$","s":"两分量角频率 $\\frac{7\\pi}{3}$、$\\frac{\\pi}{3}$，周期分别为 $N_1=\\frac{2\\pi}{7\\pi/3}\\cdot7=6$、$N_2=\\frac{2\\pi}{\\pi/3}=6$，故为周期信号，公共周期 $N=6$。答案页：周期。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-11","seq":11,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"11. 零初始状态条件下，方程 $y(k)+3k\\,y(k-1)=2f(k-1)$ 描述的离散系统是 ____（填“线性”或“非线性”）、____（填“时变”或“时不变”）的。","img":"pro-img/final-sig_p20.jpg","a":"线性；时变","s":"方程为线性差分方程（满足齐次性与可加性），故线性；系数 $3k$ 随 $k$ 变化，故时变。答案页：线性。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-12","seq":12,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"12. 假定信号 $f(t)$ 是限带实信号，最高角频率为 $\\omega_m$。现对信号 $f_1(t)$（最高角频率为 $1.5\\omega_m$，原式 OCR 不清）进行冲激取样，那么奈奎斯特取样速率 $f_{s,\\min}=$ ____。","img":"pro-img/final-sig_p21.jpg","a":"$\\omega_{s,\\min}=3\\omega_m$（即 $f_{s,\\min}=\\dfrac{3\\omega_m}{2\\pi}$）","s":"取样信号最高角频率 $1.5\\omega_m$，奈奎斯特角取样频率 $\\omega_{s,\\min}=2\\times1.5\\omega_m=3\\omega_m$。答案页：$3\\omega_m$。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-13","seq":13,"part":"信号","qt":"填空","pts":4,"ch":"ss-cont-time","q":"13. $f_1(t)=3e^{-t}\\varepsilon(t)$，$f_2(t)=(1+e^{-4t})\\varepsilon(t)$，则 $f_1(t+1)*f_2(t-1)=$ ____。","img":"pro-img/final-sig_p21.jpg","a":"$3-2e^{-t}-e^{-4t}$（$t>0$）","s":"卷积平移抵消：$f_1(t+1)*f_2(t-1)=f_1(t)*f_2(t)$。$F(s)=\\frac{3}{s+1}\\left(\\frac1s+\\frac1{s+4}\\right)=\\frac3s-\\frac2{s+1}-\\frac1{s+4}$，逆变换得 $3-2e^{-t}-e^{-4t}$。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-14","seq":14,"part":"信号","qt":"填空","pts":4,"ch":"ss-sdomain","q":"14. 如题 14 图所示电路 [题14图：R 与 C 串联，输入 $u_s(t)$，输出 $u_c(t)$]，设初始状态为零，则以 $u_s(t)$ 为输入、$u_c(t)$ 为输出，系统函数 $H(s)=$ ____；该系统是一个 ____（填“低通”或“高通”或“带通”）滤波器。","img":"pro-img/final-sig_p21.jpg","a":"$H(s)=\\dfrac{1}{1+sRC}$；低通","s":"$H(s)=\\dfrac{U_c(s)}{U_s(s)}=\\dfrac{1/(sC)}{R+1/(sC)}=\\dfrac{1}{1+sRC}$，幅频随频率增大而衰减，为低通滤波器。答案页：低通、$1/(1+sRC)$。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-15","seq":15,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"15. 连续时间周期函数 $f(t)$ 如题 15 图所示 [题15图：周期梯形波，周期 $T$]，其周期为 $T$，$0<t<T$，则直流分量 = ____。设 $f(t)=f(-t)$，傅里叶级数形式如下：$f(t)=\\dfrac{a_0}{2}+\\sum_n a_n\\cos(n\\Omega t)+\\sum_n b_n\\sin(n\\Omega t)$，$\\Omega=\\dfrac{2\\pi}{T}$，则 $f(t)$ 的谐波特性为：____（概括直流、正弦分量、余弦分量、奇次谐波、偶次谐波的存在情况）。","img":"pro-img/final-sig_p21.jpg","a":"直流分量 $\\dfrac{2}{T}$；存在正弦分量、奇次谐波、偶次谐波","s":"由波形积分得直流分量 $\\dfrac{a_0}{2}=\\dfrac1T\\int_0^T f(t)dt=\\dfrac2T$；波形无半波对称性，故奇、偶次谐波与正弦分量均存在。（谐波特性概括以答案页为准）","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-16","seq":16,"part":"信号","qt":"填空","pts":4,"ch":"ss-zdomain","q":"16. 因果序列 $f(k)$ 的象函数为 $F(z)=\\dfrac{z}{2(z-3)}$（原公式 OCR 不清，按答案反推），则初值 $f(0)=$ ____；$F(z)$ 的收敛域为 ____。","img":"pro-img/final-sig_p21.jpg","a":"$f(0)=\\dfrac12$；$|z|>3$","s":"初值定理 $f(0)=\\lim_{z\\to\\infty}F(z)=\\lim_{z\\to\\infty}\\frac{z}{2(z-3)}=\\frac12$；极点 $z=3$，因果序列收敛域 $|z|>3$。答案页：$1/2$，$|z|>3$。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-17","seq":17,"part":"信号","qt":"解答","pts":10,"ch":"ss-sdomain","q":"17. 描述某 LTI 因果连续系统的微分方程为：$y''(t)+4y'(t)+3y(t)=f'(t)+5f(t)$。\n(1) 已知 $y(0_-)=0,\\ y'(0_-)=2$，$f(t)=e^{-2t}\\varepsilon(t)$，试求系统的零输入响应 $y_{zi}(t)$、零状态响应 $y_{zs}(t)$ 及全响应 $y(t)$。\n(2) 若 $f(t)=\\cos(t)$，$-\\infty<t<\\infty$，求稳态响应 $y_s(t)$。","img":"pro-img/final-sig_p22.jpg","a":"(1) $y_{zi}(t)=(e^{-t}-e^{-3t})\\varepsilon(t)$，$y_{zs}(t)=(2e^{-t}-3e^{-2t}+e^{-3t})\\varepsilon(t)$，$y(t)=(3e^{-t}-3e^{-2t})\\varepsilon(t)$；(2) $y_s(t)=\\sqrt{\\tfrac{13}{10}}\\cos\\left(t-\\arctan\\tfrac97\\right)$","s":"(1) 特征方程 $s^2+4s+3=0\\Rightarrow s=-1,-3$，$y_{zi}(t)=C_1e^{-t}+C_2e^{-3t}$；由 $y(0_-)=0,y'(0_-)=2$ 得 $C_1=1,C_2=-1$，故 $y_{zi}(t)=e^{-t}-e^{-3t}$。$H(s)=\\frac{s+5}{s^2+4s+3}$，$F(s)=\\frac1{s+2}$，$Y_{zs}(s)=\\frac{s+5}{(s+1)(s+2)(s+3)}=\\frac2{s+1}-\\frac3{s+2}+\\frac1{s+3}$，故 $y_{zs}(t)=(2e^{-t}-3e^{-2t}+e^{-3t})\\varepsilon(t)$；$y(t)=y_{zi}+y_{zs}=(3e^{-t}-3e^{-2t})\\varepsilon(t)$。(2) $H(j\\omega)=\\frac{j\\omega+5}{3-\\omega^2+j4\\omega}$，$\\omega=1$ 时 $|H(j1)|=\\sqrt{\\frac{26}{20}}=\\sqrt{\\frac{13}{10}}$，$\\angle H(j1)=\\arctan\\tfrac15-\\arctan2=-\\arctan\\tfrac97$，故 $y_s(t)=\\sqrt{\\tfrac{13}{10}}\\cos(t-\\arctan\\tfrac97)$。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-18","seq":18,"part":"信号","qt":"解答","pts":8,"ch":"ss-zdomain","q":"18. LTI 离散时间复合系统框图如题 18 图 (a) 所示 [题18图：复合系统框图与 $h_1(k)$ 波形]，其中离散子系统 $S_1$ 的单位序列响应 $h_1(k)$（$k\\le-1$ 与 $k\\ge2$ 时 $h_1(k)=0$）如题 18 图 (b) 所示。\n(1) 画出单位延迟器的单位序列响应 $h_D(k)$ 和复合系统的单位序列响应 $h(k)$ 的波形。\n(2) 写出复合系统的系统函数 $H(z)$ 并画出零、极点分布图。","img":"pro-img/final-sig_p23.jpg","a":"(1) $h_D(k)=\\delta(k-1)$，$h(k)=\\delta(k)+\\delta(k-3)$；(2) $H(z)=1+z^{-3}=\\dfrac{z^3+1}{z^3}$，零点 $z=-1,e^{\\pm j\\pi/3}$，极点 $z=0$（三阶）","s":"单位延迟器 $h_D(k)=\\delta(k-1)$，$H_D(z)=z^{-1}$；$S_1$ 子系统 $h_1(k)$ 仅在 $k=0,1$ 非零（取值见题图）。复合系统 $H(z)=1+z^{-3}$，故 $h(k)=\\delta(k)+\\delta(k-3)$（在 $k=0,3$ 处各有一冲激）。零点由 $z^3=-1$ 得 $z=-1,e^{\\pm j\\pi/3}$（单位圆上），极点 $z=0$ 三阶。（框图连接关系详见原题图）","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-19","seq":19,"part":"信号","qt":"解答","pts":10,"ch":"ss-freq","q":"19. $f(t)$ 如题 19 图所示（偶对称梯形脉冲：$|t|\\le1$ 时 $f(t)=1$，$1<|t|\\le2$ 时 $f(t)=2-|t|$，其余为 0）[题19图]，若 $f(t)\\leftrightarrow F(j\\omega)$，且 $F(j\\omega)=R(\\omega)+jX(\\omega)$。试完成以下计算：\n(1) $F(0)$；\n(2) $\\int_{-\\infty}^{\\infty}F(j\\omega)e^{-j\\omega}d\\omega$；\n(3) 若 $f_1(t)=-\\dfrac{1}{\\pi}\\int_{0}^{\\infty}X(\\omega)\\sin(\\omega t)d\\omega$，画出 $f_1(t)$ 的波形；\n(4) $\\dfrac{1}{\\pi}\\int_{-\\infty}^{\\infty}[R^2(\\omega)+X^2(\\omega)]d\\omega$；\n(5) 求 $f(t)$ 的单边拉普拉斯变换，并指出其收敛域。","img":"pro-img/final-sig_p24.jpg","a":"(1) $F(0)=3$；(2) $2\\pi$；(3) $f_1(t)=0$（$f$ 为偶函数，$X(\\omega)=0$）；(4) $\\dfrac{16}{3}$；(5) $F(s)=\\dfrac1s+\\dfrac{e^{-2s}-e^{-s}}{s^2}$，收敛域为整个 $s$ 平面","s":"(1) $F(0)=\\int f(t)dt=\\tfrac12\\times1\\times(2+4)=3$。(2) 由反变换 $f(t)=\\tfrac1{2\\pi}\\int F(j\\omega)e^{j\\omega t}d\\omega$，得 $\\int F(j\\omega)e^{-j\\omega}d\\omega=2\\pi f(-1)=2\\pi$。(3) 实信号分解 $f_{odd}(t)=\\tfrac{f(t)-f(-t)}2\\leftrightarrow jX(\\omega)$，$f$ 为偶函数故 $X(\\omega)=0$、$f_1(t)=f_{odd}(t)=0$。(4) 帕塞瓦尔：$\\tfrac1\\pi\\int|F|^2d\\omega=2\\int f^2(t)dt=2\\times\\tfrac83=\\tfrac{16}{3}$。(5) $t\\ge0$ 部分 $f(t)=1(0\\le t\\le1)$、$2-t(1\\le t\\le2)$，$F(s)=\\frac{1-e^{-s}}s+\\left(\\frac{e^{-s}}s+\\frac{e^{-2s}-e^{-s}}{s^2}\\right)=\\frac1s+\\frac{e^{-2s}-e^{-s}}{s^2}$，时限信号收敛域为整个 $s$ 平面。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-20","seq":20,"part":"信号","qt":"解答","pts":8,"ch":"ss-freq","q":"20. 如题 20 图所示模拟调幅（AM）通信系统原理框图 [题20图：乘法器、理想信道、理想低通滤波器、加法器构成解调器]。$f(t)$ 是发送端基带信号，$f_1(t)=0.5\\cos\\omega_m t$，$f_2(t)$ 和 $f_4(t)$ 是发送端载波和接收端本地载波，且 $f_2(t)=f_4(t)=\\cos\\omega_0 t$，$\\omega_0\\gg\\omega_m>0$；$f_A(t)$ 为发送端已调信号，$f_A(t)=[1+f_1(t)]f_2(t)$。传输信道为理想信道，$f_B(t)=f_A(t)$。接收端有 $f_C(t)=f_B(t)f_4(t)$ 和 $f_D(t)=f_C(t)-1$。现欲使 $f_D(t)=f_1(t)$。\n(1) 试画出 $f_A(t)$ 和 $f_C(t)$ 的频谱 $F_A(j\\omega)$ 和 $F_C(j\\omega)$；\n(2) 试画出理想低通滤波器 $H(j\\omega)$ 的幅频响应曲线（应标明通带增益），并确定其截止频率 $\\omega_c$ 的可能取值范围。","img":"pro-img/final-sig_p25.jpg","a":"(1) $F_A(j\\omega)=\\pi[\\delta(\\omega+\\omega_0)+\\delta(\\omega-\\omega_0)]+\\tfrac{\\pi}{4}[\\delta(\\omega\\pm(\\omega_0+\\omega_m))+\\delta(\\omega\\pm(\\omega_0-\\omega_m))]$；$F_C(j\\omega)=\\pi\\delta(\\omega)+\\tfrac{\\pi}{4}[\\delta(\\omega+\\omega_m)+\\delta(\\omega-\\omega_m)]+$高频项（$2\\omega_0,\\ 2\\omega_0\\pm\\omega_m$）；(2) 通带增益 $2$，$\\omega_m<\\omega_c<2\\omega_0-\\omega_m$","s":"$f_A(t)=(1+0.5\\cos\\omega_m t)\\cos\\omega_0 t=\\cos\\omega_0 t+0.25\\cos(\\omega_0+\\omega_m)t+0.25\\cos(\\omega_0-\\omega_m)t$。$f_C(t)=f_A(t)\\cos\\omega_0 t$ 后，基带分量 $0.25\\cos\\omega_m t$ 叠加得 $0.25\\cos\\omega_m t$（频谱幅度 $\\tfrac{\\pi}{4}$ 于 $\\pm\\omega_m$），另含 $2\\omega_0$ 及 $2\\omega_0\\pm\\omega_m$ 高频项与直流 $\\pi\\delta(\\omega)$。$f_D=f_C-1$ 去直流后，低通（增益 2）取出基带得 $2\\times0.25\\cos\\omega_m t=0.5\\cos\\omega_m t=f_1(t)$；截止频率需 $\\omega_m<\\omega_c<2\\omega_0-\\omega_m$。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs20-21","seq":21,"part":"信号","qt":"解答","pts":8,"ch":"ss-zdomain","q":"21. 描述离散因果 LTI 系统的差分方程如下：$y(k)+0.7y(k-1)+0.06y(k-2)=f(k)-0.7f(k-1)+0.1f(k-2)$。试完成：\n(1) 写出该系统的系统函数 $H(z)$，并计算单位序列响应 $h(k)$；\n(2) 判定系统的稳定性；\n(3) 画出该系统的直接型信号流图；\n(4) 基于 (3) 中信号流图以各单位延迟器的输出端作为状态变量（从左到右分别为 $x_1(k)$ 和 $x_2(k)$），写出该系统的状态方程和输出方程（要求写成矩阵形式）。","img":"pro-img/final-sig_p26.jpg","a":"(1) $H(z)=\\dfrac{1-0.7z^{-1}+0.1z^{-2}}{1+0.7z^{-1}+0.06z^{-2}}=\\dfrac{(z-0.5)(z-0.2)}{(z+0.6)(z+0.1)}$，$h(k)=\\tfrac53\\delta(k)+\\tfrac{44}{15}(-0.6)^k\\varepsilon(k)-\\tfrac{18}{5}(-0.1)^k\\varepsilon(k)$；(2) 稳定；(3) 直接Ⅱ型流图；(4) $\\begin{bmatrix}x_1(k+1)\\\\x_2(k+1)\\end{bmatrix}=\\begin{bmatrix}-0.7&-0.06\\\\1&0\\end{bmatrix}\\begin{bmatrix}x_1(k)\\\\x_2(k)\\end{bmatrix}+\\begin{bmatrix}1\\\\0\\end{bmatrix}f(k)$，$y(k)=\\begin{bmatrix}-1.4&0.04\\end{bmatrix}\\begin{bmatrix}x_1(k)\\\\x_2(k)\\end{bmatrix}+f(k)$","s":"(1) $H(z)=\\frac{z^2-0.7z+0.1}{z^2+0.7z+0.06}$；$H(z)/z$ 部分分式得 $H(z)=\\tfrac53+\\tfrac{44}{15}\\tfrac{z}{z+0.6}-\\tfrac{18}{5}\\tfrac{z}{z+0.1}$，逆变换得 $h(k)$。(2) 极点 $z=-0.6,-0.1$，均在单位圆内，$|z|>0.6$ 含单位圆，系统稳定。(3)(4) 直接Ⅱ型：$x_1(k+1)=-0.7x_1(k)-0.06x_2(k)+f(k)$，$x_2(k+1)=x_1(k)$，$y(k)=-1.4x_1(k)+0.04x_2(k)+f(k)$。","t":"期末","y":2020,"src":"西电信号2020期末"},{"id":"fs21-01","seq":1,"part":"信号","qt":"选择","pts":3,"ch":"ss-intro","q":"1.（ ）下列信号是非周期信号的是：","o":["A. $f(t)=\\cos(2t)+\\sin(7t)$","B. $f(t)=\\cos(3\\pi t)+\\sin(7\\pi t)$","C. $f(k)=\\cos\\left(\\tfrac{\\pi}{3}k\\right)+\\sin(2\\pi k)$（cos 项角频率 OCR 不清）","D. $f(k)=\\cos(2k)+\\sin(3k)$"],"img":"pro-img/final-sig_p11.jpg","a":"D","s":"D 中 $\\cos(2k)$、$\\sin(3k)$ 的角频率 $2,3$ 不是 $\\pi$ 的有理数倍，$2\\pi/2=\\pi$ 无理，故为非周期序列；A、B、C 均为周期信号。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-02","seq":2,"part":"信号","qt":"选择","pts":3,"ch":"ss-intro","q":"2.（ ）某离散系统输入输出满足 $y(k)+y(k-2)=3f(k)+1$，则该系统是：","o":["A. 线性；时不变","B. 线性；时变","C. 非线性；时变","D. 非线性；时不变"],"img":"pro-img/final-sig_p12.jpg","a":"D","s":"方程含常数项 $+1$，不满足零输入零输出与可加性，为非线性；系数均为常数，为时不变。故选 D。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-03","seq":3,"part":"信号","qt":"选择","pts":3,"ch":"ss-freq","q":"3.（ ）若周期信号 $f(t)$ 是实偶函数，则其傅里叶系数 $F_n$ 是 $n$ 的：","o":["A. 实偶函数","B. 实奇函数","C. 虚偶函数","D. 虚奇函数"],"img":"pro-img/final-sig_p12.jpg","a":"A","s":"实偶信号傅里叶级数只含余弦项，系数 $F_n$ 为实且偶对称，故选 A。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-04","seq":4,"part":"信号","qt":"选择","pts":3,"ch":"ss-freq","q":"4.（ ）若 $f(t)\\leftrightarrow F(j\\omega)$，则 $e^{jt}f(5-2t)$（指数项 OCR 不清）的傅里叶变换为：","o":["A. $\\tfrac12F\\left(j\\tfrac{1-\\omega}{2}\\right)e^{-j\\tfrac52(\\omega-1)}$","B. $\\tfrac12F\\left(j\\tfrac{1-\\omega}{2}\\right)e^{j\\tfrac52\\omega}$","C. $\\tfrac12F\\left(j\\tfrac{\\omega-1}{2}\\right)e^{-j\\tfrac52\\omega}$","D. $\\tfrac12F\\left(j\\tfrac{\\omega-1}{2}\\right)e^{j\\tfrac52\\omega}$"],"img":"pro-img/final-sig_p12.jpg","a":"A","s":"$f(5-2t)=f(-2t+5)\\leftrightarrow\\tfrac12F\\left(-j\\tfrac{\\omega}{2}\\right)e^{-j\\tfrac52\\omega}$；乘 $e^{jt}$ 频谱右移 1，得 $\\tfrac12F\\left(j\\tfrac{1-\\omega}{2}\\right)e^{-j\\tfrac52(\\omega-1)}$，选 A。（选项 OCR 不清，以推导为准）","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-05","seq":5,"part":"信号","qt":"选择","pts":3,"ch":"ss-freq","q":"5.（ ）有限频带信号 $f(t)$ 的最高频率为 $f_m$ Hz（假定 $F(j\\omega)|_{\\omega=2\\pi f_m}=0$），若对 $f_1(t)=f(t)*f(2t)$ 进行时域采样，则奈奎斯特频率是：","o":["A. $f_m$","B. $2f_m$","C. $3f_m$","D. $1.5f_m$"],"img":"pro-img/final-sig_p12.jpg","a":"B","s":"时域卷积对应频域相乘，$F_1(j\\omega)=F(j\\omega)\\cdot\\tfrac12F(j\\omega/2)$，带宽取 $\\min(f_m,2f_m)=f_m$，奈奎斯特频率 $2f_m$，选 B。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-06","seq":6,"part":"信号","qt":"选择","pts":3,"ch":"ss-sdomain","q":"6.（ ）已知单边拉氏变换象函数 $F(s)=\\dfrac{e^{-(s-1)}}{s-2}$，则原函数 $f(t)$ 等于：","o":["A. $e^{2(t-1)}\\varepsilon(t-1)$","B. $e^{2t}\\varepsilon(t-1)$","C. $e^{2t-1}\\varepsilon(t-1)$","D. $e^{2t-1}\\varepsilon(t)$"],"img":"pro-img/final-sig_p12.jpg","a":"C","s":"$F(s)=e\\cdot\\dfrac{e^{-s}}{s-2}$；$\\dfrac1{s-2}\\leftrightarrow e^{2t}\\varepsilon(t)$，$e^{-s}$ 延迟 1，再乘 $e$，得 $f(t)=e^{2(t-1)+1}\\varepsilon(t-1)=e^{2t-1}\\varepsilon(t-1)$，选 C。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-07","seq":7,"part":"信号","qt":"选择","pts":3,"ch":"ss-sdomain","q":"7.（ ）某 LTI 系统的阶跃响应 $g(t)=(1-e^{-2t})\\varepsilon(t)$，则该系统的系统函数为：","o":["A. $\\dfrac{1}{s-2}$","B. $\\dfrac{1}{s+2}$","C. $\\dfrac{2}{s+2}$","D. $\\dfrac{2}{s-2}$"],"img":"pro-img/final-sig_p13.jpg","a":"C","s":"$h(t)=g'(t)=2e^{-2t}\\varepsilon(t)$，$H(s)=\\dfrac2{s+2}$；或 $H(s)=sG(s)=s\\left(\\tfrac1s-\\tfrac1{s+2}\\right)=\\tfrac2{s+2}$，选 C。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-08","seq":8,"part":"信号","qt":"选择","pts":3,"ch":"ss-zdomain","q":"8.（ ）因果稳定离散系统的系统函数为 $H(z)$（假定 $H(z)$ 有理），则其所有的极点均位于：","o":["A. $z$ 平面的左半开平面","B. $z$ 平面的右半开平面","C. $z$ 平面的单位圆外","D. $z$ 平面的单位圆内"],"img":"pro-img/final-sig_p13.jpg","a":"D","s":"因果稳定离散系统的收敛域为 $|z|>r$ 且包含单位圆，故全部极点位于单位圆内，选 D。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-09","seq":9,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"9. 积分 $\\int(3-x)\\delta(2-x)\\,dx=$ ____。","img":"pro-img/final-sig_p13.jpg","a":"1","s":"$\\int(3-x)\\delta(2-x)dx=\\int(3-x)\\delta(x-2)dx=3-2=1$。（答案页该题作 $-2\\delta(t-4)$，与积分型题干不符，疑为 OCR/答案错位，按积分定义给出结果）","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-10","seq":10,"part":"信号","qt":"填空","pts":4,"ch":"ss-cont-time","q":"10. 信号 $f_1(t)$ 和 $f_2(t)$ 如题 10 图所示 [题10图：两信号波形，图在下一页]，$f(t)=f_1(-t-1)*f_2(t)$，则 $f(1)=$ ____。","img":"pro-img/final-sig_p13.jpg","a":"$-0.5$","s":"由卷积积分 $f(1)=\\int f_1(-\\tau-1)f_2(1-\\tau)d\\tau$，结合题图波形积分得 $-0.5$。答案页：$-0.5$。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-11","seq":11,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"11. 某 LTI 系统的幅频特性和相频特性如题 11 图所示（假定 $\\varphi(0)=0$）[题11图：$|H(j\\omega)|$ 在 $\\omega=0$ 处为 4、$\\omega=2\\pi$ 处为 3.5、$\\omega=4\\pi$ 处为 0，相频 $\\pm\\tfrac\\pi2$]，若输入信号为 $f(t)=1+2\\sin(2\\pi t)+1.5\\cos(4\\pi t)$，则该系统的输出 $y(t)=$ ____。","img":"pro-img/final-sig_p14.jpg","a":"$y(t)=4+7\\sin\\left(2\\pi t+\\tfrac{\\pi}{2}\\right)=4+7\\cos(2\\pi t)$","s":"直流分量增益 $|H(0)|=4$ → 输出 $4$；$\\omega=2\\pi$ 处 $|H|=3.5$、$\\varphi=+\\tfrac\\pi2$ → $2\\times3.5\\sin(2\\pi t+\\tfrac\\pi2)=7\\cos(2\\pi t)$；$4\\pi$ 分量增益为 0 被滤除。故 $y(t)=4+7\\cos(2\\pi t)$。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-12","seq":12,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"12. 某理想低通滤波器的频率特性为 $H(j\\omega)=e^{-j\\omega t_0}$（$|\\omega|<4$），则其单位冲激响应 $h(t)=$ ____。","img":"pro-img/final-sig_p14.jpg","a":"$h(t)=\\dfrac{\\sin4(t-t_0)}{\\pi(t-t_0)}=\\dfrac4\\pi\\mathrm{Sa}[4(t-t_0)]$","s":"$h(t)=\\dfrac1{2\\pi}\\int_{-4}^{4}e^{-j\\omega t_0}e^{j\\omega t}d\\omega=\\dfrac1{2\\pi}\\cdot\\dfrac{2\\sin4(t-t_0)}{t-t_0}=\\dfrac{\\sin4(t-t_0)}{\\pi(t-t_0)}$。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-13","seq":13,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"13. 信号 $f(t)=2\\cos(2021t)\\dfrac{\\sin(4t)}{t}$ 的能量是 ____ (J)。","img":"pro-img/final-sig_p14.jpg","a":"$8\\pi$ J","s":"$\\dfrac{\\sin4t}{t}\\leftrightarrow\\pi\\,g_8(\\omega)$（门宽 8），乘 $2\\cos(2021t)$ 后频谱为 $\\pi[g_8(\\omega-2021)+g_8(\\omega+2021)]$；帕塞瓦尔 $E=\\dfrac1{2\\pi}\\int|F|^2d\\omega=\\dfrac1{2\\pi}\\cdot\\pi^2\\cdot16=8\\pi$ J。（答案页该题空）","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-14","seq":14,"part":"信号","qt":"填空","pts":4,"ch":"ss-sdomain","q":"14. 如题 14 图所示 [题14图：有始周期方波，周期 $2T$]，$f(t)$ 为有始周期方波信号，其象函数 $F(s)=$ ____，收敛域为 $\\mathrm{Re}[s]>$ ____。","img":"pro-img/final-sig_p14.jpg","a":"$F(s)=\\dfrac{1-e^{-sT}}{s(1+e^{-sT})}=\\dfrac1s\\tanh\\dfrac{sT}{2}$；$\\mathrm{Re}[s]>0$","s":"有始周期信号 $F(s)=\\dfrac{F_1(s)}{1-e^{-sT_0}}$，首周期 $f_1(t)=\\varepsilon(t)-2\\varepsilon(t-T)+\\varepsilon(t-2T)$，$F_1(s)=\\dfrac{(1-e^{-sT})^2}s$，$T_0=2T$，故 $F(s)=\\dfrac{(1-e^{-sT})^2}{s(1-e^{-2sT})}=\\dfrac{1-e^{-sT}}{s(1+e^{-sT})}$，收敛域 $\\mathrm{Re}[s]>0$。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-15","seq":15,"part":"信号","qt":"填空","pts":4,"ch":"ss-sdomain","q":"15. 象函数 $F(s)=\\dfrac{2s+1}{(s+1)^2}$，$\\mathrm{Re}[s]>-1$，则初值 $f(0_+)=$ ____，终值 $f(\\infty)=$ ____。","img":"pro-img/final-sig_p15.jpg","a":"$f(0_+)=2$；$f(\\infty)=0$","s":"初值定理 $f(0_+)=\\lim_{s\\to\\infty}sF(s)=\\lim\\dfrac{2s^2+s}{(s+1)^2}=2$；终值定理 $f(\\infty)=\\lim_{s\\to0}sF(s)=0$。答案页：2；0。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-16","seq":16,"part":"信号","qt":"填空","pts":4,"ch":"ss-zdomain","q":"16. 序列 $f(k)=k(-2)^k\\varepsilon(k)$（原式 $(-2)^{-k}$ 疑为 $(-2)^k$，以答案为准）的 $z$ 变换 $F(z)=$ ____；收敛域为 $|z|>$ ____。","img":"pro-img/final-sig_p15.jpg","a":"$F(z)=\\dfrac{-2z}{(z+2)^2}$；$|z|>2$","s":"$Z\\{ka^k\\varepsilon(k)\\}=\\dfrac{az}{(z-a)^2}$，取 $a=-2$ 得 $F(z)=\\dfrac{-2z}{(z+2)^2}$，极点 $z=-2$，收敛域 $|z|>2$。答案页：分母 $(z+2)^2$、$|z|>2$。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-17","seq":17,"part":"信号","qt":"解答","pts":12,"ch":"ss-freq","q":"17.（本题 12 分）如题 17 图 (a) 所示系统 [题17图：乘法器与低通滤波器，$f(t)s(t)$ 后经低通输出]。若输入信号 $f(t)=\\dfrac{\\sin(10\\pi t)}{\\pi t}\\cos(1000t)$，$s(t)=\\cos(1000t)$，低通滤波器的频率响应如题 17 图 (b) 所示（$|\\omega|<100$，增益 1），其中相频特性 $\\varphi(\\omega)=0$。\n(1) 求输出信号 $y(t)$。\n(2) 进一步地，用周期为 $T_s=0.05\\ \\mathrm{s}$ 的冲激序列 $\\delta_{T_s}(t)$ 对信号 $y(t)$ 进行取样，画出取样信号 $y_s(t)=y(t)\\delta_{T_s}(t)$ 的频谱图。\n(3) 若由取样信号恢复信号 $y(t)$，理想低通滤波器的截止频率应如何选择？","img":"pro-img/final-sig_p15.jpg","a":"(1) $y(t)=5\\mathrm{Sa}(10\\pi t)=\\dfrac{\\sin10\\pi t}{2\\pi t}$；(2) $Y_s(j\\omega)=10\\sum_n g_{20\\pi}(\\omega-40\\pi n)$（周期 $40\\pi$ 复现）；(3) $5\\ \\mathrm{Hz}<f_c<15\\ \\mathrm{Hz}$","s":"$\\dfrac{\\sin10\\pi t}{\\pi t}\\leftrightarrow g_{20\\pi}(\\omega)$。$f(t)s(t)=\\dfrac{\\sin10\\pi t}{\\pi t}\\cos^2(1000t)$，频谱 $\\tfrac14[g_{20\\pi}(\\omega+2000)+2g_{20\\pi}(\\omega)+g_{20\\pi}(\\omega-2000)]$；低通（$|\\omega|<100$）取出 $\\tfrac12g_{20\\pi}(\\omega)$，故 $y(t)=\\tfrac12\\cdot10\\mathrm{Sa}(10\\pi t)=5\\mathrm{Sa}(10\\pi t)$。(2) $T_s=0.05\\Rightarrow f_s=20\\ \\mathrm{Hz},\\ \\omega_s=40\\pi$，$Y_s(j\\omega)=\\tfrac1{T_s}\\sum Y(j(\\omega-n\\omega_s))=10\\sum g_{20\\pi}(\\omega-40\\pi n)$。(3) $y(t)$ 最高频率 $f_m=\\tfrac{10\\pi}{2\\pi}=5\\ \\mathrm{Hz}$，恢复低通截止频率需 $f_m<f_c<f_s-f_m$，即 $5\\ \\mathrm{Hz}<f_c<15\\ \\mathrm{Hz}$。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-18","seq":18,"part":"信号","qt":"解答","pts":12,"ch":"ss-sdomain","q":"18.（本题 12 分）如题 18 图所示电路 [题18图：含 $U_s$、$L$、$C$、$R_1,R_2,R_3$ 的二阶电路]，已知 $U_s=8\\ \\mathrm{V}$，$L=1\\ \\mathrm{H}$，$C=0.5\\ \\mathrm{F}$，$R_1=R_2=R_3=4\\ \\Omega$，原电路已处于稳定状态，开关 $S$ 在 $t=0$ 时闭合，求经过电阻 $R_3$ 的电流 $i(t)$ 的零输入响应和零状态响应。","img":"pro-img/final-sig_p16.jpg","a":"节点电压：$y_{zi}(t)=(10e^{-2t}-6e^{-3t})\\varepsilon(t)$ V，$y_{zs}(t)=\\left(\\tfrac83-8e^{-2t}+\\tfrac{16}{3}e^{-3t}\\right)\\varepsilon(t)$ V；故 $i_{3,zi}(t)=\\left(\\tfrac52e^{-2t}-\\tfrac32e^{-3t}\\right)\\varepsilon(t)$ A，$i_{3,zs}(t)=\\left(\\tfrac23-2e^{-2t}+\\tfrac43e^{-3t}\\right)\\varepsilon(t)$ A","s":"初始值：$u_c(0_-)=\\tfrac{R_2}{R_1+R_2}\\times8=4\\ \\mathrm{V}$，$i_L(0_-)=\\tfrac8{R_1+R_2}=1\\ \\mathrm{A}$。$t>0$ 时列节点（$s$ 域）电压方程，解得 $Y_{zi}(s)=\\dfrac{2i_L(0_-)+(s+4)u_c(0_-)}{s^2+5s+6}=\\dfrac{4s+18}{(s+2)(s+3)}=\\dfrac{10}{s+2}-\\dfrac6{s+3}$；$Y_{zs}(s)=\\dfrac{2U_s(s)}{s^2+5s+6}=\\dfrac{16}{s(s+2)(s+3)}=\\dfrac{8/3}{s}-\\dfrac8{s+2}+\\dfrac{16/3}{s+3}$。取逆变换后 $i_3(t)=y(t)/R_3$。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-19","seq":19,"part":"信号","qt":"解答","pts":10,"ch":"ss-zdomain","q":"19.（本题 10 分）描述某 LTI 离散因果系统的差分方程为：$y(k+2)-0.9y(k+1)+0.2y(k)=-6f(k+1)+2.5f(k)$，已知 $y(-1)=10,\\ y(-2)=5$，$f(k)=(0.5)^k\\varepsilon(k)$，试求该系统的零输入响应 $y_{zi}(k)$、零状态响应 $y_{zs}(k)$ 及全响应 $y(k)$。","img":"pro-img/final-sig_p17.jpg","a":"$y_{zi}(k)=\\left[20(0.5)^k-12(0.4)^k\\right]\\varepsilon(k)$；$y_{zs}(k)=\\left[10(0.4)^k-10(0.5)^k-10k(0.5)^k\\right]\\varepsilon(k)$；$y(k)=\\left[10(0.5)^k-2(0.4)^k-10k(0.5)^k\\right]\\varepsilon(k)$","s":"前向差分转后向：$y(k)-0.9y(k-1)+0.2y(k-2)=-6f(k-1)+2.5f(k-2)$。单边 $z$ 变换代入 $y(-1)=10,y(-2)=5,f(-1)=f(-2)=0,F(z)=\\tfrac z{z-0.5}$：$Y_{zi}(z)=\\dfrac{8-2z^{-1}}{1-0.9z^{-1}+0.2z^{-2}}=\\dfrac{20z}{z-0.5}-\\dfrac{12z}{z-0.4}$；$Y_{zs}(z)=\\dfrac{(-6z^{-1}+2.5z^{-2})z}{(z-0.4)(z-0.5)^2}\\cdot z=\\dfrac{10z}{z-0.4}-\\dfrac{10z}{z-0.5}-\\dfrac{5z}{(z-0.5)^2}$。取逆变换即得。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs21-20","seq":20,"part":"信号","qt":"解答","pts":10,"ch":"ss-state","q":"20.（本题 10 分）某连续系统的信号流图如题 20 图所示（原题图数据丢失，据答案页反推）[题20图：含状态变量 $x_1(t),x_2(t)$ 的信号流图]。\n(1) 利用梅森公式写出系统函数 $H(s)$。\n(2) 按照图中给出的状态变量 $x_1(t)$ 和 $x_2(t)$ 写出状态方程和输出方程。\n(3) 判断该系统是否稳定。","img":"pro-img/final-sig_p18.jpg","a":"(1) $H(s)=\\dfrac{2s^2+9s+9}{s^2+5s+6}$；(2) $\\begin{bmatrix}\\dot x_1\\\\\\dot x_2\\end{bmatrix}=\\begin{bmatrix}-5&-6\\\\1&0\\end{bmatrix}\\begin{bmatrix}x_1\\\\x_2\\end{bmatrix}+\\begin{bmatrix}1\\\\0\\end{bmatrix}f(t)$，$y(t)=x_1+3x_2-2f(t)$；(3) 稳定","s":"(1) 流图为两部分并联，梅森公式得 $H(s)=\\dfrac{2+9s^{-1}+9s^{-2}}{1+5s^{-1}+6s^{-2}}=\\dfrac{2s^2+9s+9}{s^2+5s+6}$。(2) $\\dot x_1=-5x_1-6x_2+f$，$\\dot x_2=x_1$，$y=x_1+3x_2-2f$（状态方程以答案页为准，符号一致性以原流图为准）。(3) 极点 $s=-2,-3$ 均在左半平面，系统稳定。","t":"期末","y":2021,"src":"西电信号2021期末"},{"id":"fs22-01","seq":1,"part":"信号","qt":"填空","pts":4,"ch":"ss-cont-time","q":"某连续 LTI 系统的单位冲激响应 $h(t)=2e^{-2t}\\varepsilon(t)$，输入 $f(t)=\\varepsilon(t-2)$，则系统的零状态响应 $y_f(t)=$____。（原题 OCR 残缺，本题干按参考答案反推）","img":"pro-img/final-sig_p01.jpg","a":"$[1-e^{-2(t-2)}]\\varepsilon(t-2)$","s":"$y_f(t)=h(t)*f(t)=2e^{-2t}\\varepsilon(t)*\\varepsilon(t-2)=2\\int_0^{t-2}e^{-2\\tau}d\\tau\\,\\varepsilon(t-2)=[1-e^{-2(t-2)}]\\varepsilon(t-2)$。答 $(1-e^{-2t})\\varepsilon(t)$（漏时移）或 $e^{-2(t-2)}\\delta(t-2)$ 给 2 分。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-02","seq":2,"part":"信号","qt":"填空","pts":4,"ch":"ss-intro","q":"某离散时间系统的输入 $f(k)$、输出 $y(k)$ 关系如下：$y(k)=f(k)\\cos(k\\pi)$。那么，该系统是____（线性/非线性）、____（时变/时不变）、____（因果/非因果）系统。","img":"pro-img/final-sig_p01.jpg","a":"线性；时变；因果","s":"$\\cos(k\\pi)=(-1)^k$ 是已知序列，$y(k)$ 是 $f(k)$ 的线性运算，故线性；加权系数 $(-1)^k$ 随 $k$ 变化，故时变；$y(k)$ 仅与当前 $f(k)$ 有关，故因果。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-03","seq":3,"part":"信号","qt":"填空","pts":4,"ch":"ss-cont-time","q":"三阶连续因果系统 I 的微分方程为 $y'''(t)+a_2y''(t)+a_1y'(t)+a_0y(t)=b_1f'(t)+b_0f(t)$，激励 $f(t)$ 于 $t=0$ 时接入系统，那么系统的初始状态可以表示为____；另有三阶因果系统 II 如下：$y'''(t)+a_2y''(t)+a_1y'(t)+a_0y(t)=2f(t)$，已知给定激励下三阶系统 II 的零状态响应为 $y_1(t)$，那么在相同激励下上述三阶系统 I 的零状态响应 $y(t)=$____（请用 $y_1(t)$ 表示）。","img":"pro-img/final-sig_p01.jpg","a":"$y(0_-)$、$y'(0_-)$、$y''(0_-)$；$y(t)=\\tfrac12\\big[b_1y_1'(t)+b_0y_1(t)\\big]$","s":"三阶系统初始状态由三个初值 $y(0_-),y'(0_-),y''(0_-)$ 确定。设零状态响应算子为 $H(p)$，系统 II 的 $y_1(t)=H(p)\\cdot2f=2H(p)f$，故 $H(p)f=\\tfrac12y_1$；系统 I 的零状态响应 $=H(p)(b_1f'+b_0f)=b_1(H(p)f)'+b_0(H(p)f)=\\tfrac12[b_1y_1'+b_0y_1]$。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-04","seq":4,"part":"信号","qt":"填空","pts":4,"ch":"ss-freq","q":"已知周期信号 $f(t)$ 的波形如题图1所示（周期 $T$，$\\Omega=\\frac{2\\pi}{T}$）。[题1图：周期方波，幅值 0~2，OCR 未显示数值，按参考答案反推]。请分别写出 $f(t)$ 的直流分量、一次谐波和二次谐波的表达式：(1) $f(t)$ 的直流分量：____；(2) $f(t)$ 的一次谐波：____；(3) $f(t)$ 的二次谐波：____。","img":"pro-img/final-sig_p02.jpg","a":"直流分量 $1$；一次谐波 $\\frac{4}{\\pi}\\sin(\\Omega t)$；二次谐波 $0$","s":"方波（0~2，周期 $T$）的傅里叶级数 $f(t)=1+\\frac{4}{\\pi}\\sin(\\Omega t)+\\frac{4}{3\\pi}\\sin(3\\Omega t)+\\cdots$，故直流分量 1、一次谐波 $\\frac4\\pi\\sin(\\Omega t)$、二次谐波（偶次谐波）为 0。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-05","seq":5,"part":"信号","qt":"填空","pts":4,"ch":"ss-sdomain","q":"电路如图2所示。开关 S 原接通在端子\"1\"处，且电路已达稳态；$t=0$ 时开关 S 由端子\"1\"切换到端子\"2\"。请在以下横线上方画出该电路的 s 域零输入电路模型。[题2图：含电感（3H）、电容（2F）与开关 S 的电路，OCR 元件参数不清]。","img":"pro-img/final-sig_p02.jpg","a":"s 域零输入模型：电感等效为初值电流源 $I_L(s)$ 与阻抗 $sL$ 并联（或等效电压源），电容等效为初值电压源 $U_c(s)$ 与阻抗 $\\frac{1}{sC}$ 串联（如题解图1）","s":"将电感、电容的初始储能分别用初值电源等效：电感用电流源 $I_L(s)$（阻抗 $sL$），电容用电压源 $U_c(s)$（阻抗 $\\frac{1}{sC}$）；电压源、电流源等效出错扣 2 分，等效为电流源形式同样给分。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-06","seq":6,"part":"信号","qt":"选择","pts":3,"ch":"ss-intro","q":"以下连续时间信号中，既非能量信号又非功率信号的是：","o":["A. $e^{-t}\\varepsilon(t-1)$","B. $e^{t}$","C. $\\cos(\\pi t)$","D. $\\varepsilon(t+0.3)$"],"img":"pro-img/final-sig_p03.jpg","a":"B","s":"$e^{-t}\\varepsilon(t-1)$ 能量有限（能量信号）；$\\cos(\\pi t)$ 为周期功率信号；$\\varepsilon(t+0.3)$ 为功率信号；$e^{t}$ 能量、功率均无限，既非能量又非功率信号。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-07","seq":7,"part":"信号","qt":"选择","pts":3,"ch":"ss-intro","q":"以下关于信号周期性的陈述错误的是：","o":["A. $\\cos(\\omega_0t)$，$\\omega_0$ 是不等于零的实常数，一定具有周期性。","B. $\\cos(\\beta k)$，$\\beta$ 是不等于零的实常数，不一定具有周期性。","C. 两个连续时间周期信号的线性组合一定具有周期性。","D. 两个周期序列的线性组合一定具有周期性。"],"img":"pro-img/final-sig_p03.jpg","a":"C","s":"两连续周期信号周期之比为无理数时（如 $\\cos t+\\cos\\sqrt2 t$）其和信号非周期，故 C 错误；连续余弦必周期；离散余弦仅在 $\\beta/(2\\pi)$ 为有理数时周期；两周期序列之和必周期（周期为两整周期的公倍数）。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-08","seq":8,"part":"信号","qt":"选择","pts":3,"ch":"ss-zdomain","q":"序列 $f_1(k)$ 和 $f_2(k)$ 都是有限长序列，序列波形如图3所示。[题3图：两有限长序列，均含幅值 1.5 的样本，具体取值见原题图]。若 $f(k)=f_1(k)*f_2(k)$，则 $f(k)$ 在题设点处的值为：","o":["A. $0$","B. $2.5$","C. $4$","D. $4.5$"],"img":"pro-img/final-sig_p03.jpg","a":"D","s":"由卷积定义，$f_1(k)*f_2(k)$ 在题设点处为三个幅值 1.5 样本之和 $1.5+1.5+1.5=4.5$，选 D。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-09","seq":9,"part":"信号","qt":"选择","pts":3,"ch":"ss-freq","q":"以下关于连续实信号 $f(t)$ 之傅里叶变换 $F(j\\omega)$ 奇偶性的陈述错误的是（设 $F(j\\omega)=|F(j\\omega)|e^{j\\varphi(\\omega)}$）：","o":["A. 若 $f(t)$ 为奇信号，则 $F(j\\omega)$ 是 $\\omega$ 的实且奇函数；","B. 若 $f(t)$ 为偶信号，则 $F(j\\omega)$ 是 $\\omega$ 的实且偶函数。","C. $F(j\\omega)$ 的幅频特性 $|F(j\\omega)|$ 关于 $\\omega$ 偶对称；","D. $F(j\\omega)$ 的相频特性 $\\varphi(\\omega)$ 关于 $\\omega$ 奇对称。"],"img":"pro-img/final-sig_p03.jpg","a":"A","s":"实奇信号的傅里叶变换应为纯虚且奇的函数（非实函数），故 A 错；B、C、D 均正确。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-10","seq":10,"part":"信号","qt":"选择","pts":3,"ch":"ss-sdomain","q":"$\\dfrac{\\mathrm{d}\\cos(\\pi t)}{\\mathrm{d}t}$ 的单边拉普拉斯变换为：（选项 OCR 不清，按结果反推）","o":["A. $\\frac{\\pi s}{s^2+\\pi^2}$","B. $\\frac{s^2}{s^2+\\pi^2}$","C. $\\frac{\\pi^2}{s^2+\\pi^2}$","D. $-\\frac{\\pi^2}{s^2+\\pi^2}$"],"img":"pro-img/final-sig_p04.jpg","a":"D","s":"$\\mathcal L\\{\\frac{d}{dt}\\cos(\\pi t)\\}=s\\cdot\\frac{s}{s^2+\\pi^2}-\\cos(0)=\\frac{s^2-s^2-\\pi^2}{s^2+\\pi^2}=-\\frac{\\pi^2}{s^2+\\pi^2}$，选 D。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-11","seq":11,"part":"信号","qt":"选择","pts":3,"ch":"ss-zdomain","q":"对于序列 $f(k)$，构造其二倍内插序列 $\\tilde f(k)$ 如下：$\\tilde f(k)=\\begin{cases}f(k/2),&k\\text{ 为偶数}\\\\0,&k\\text{ 为奇数}\\end{cases}$。若 $f(k)$ 的单边 z 变换为 $F(z)$，则根据 z 变换的定义，序列 $\\tilde f(k)$ 的单边 z 变换 $\\tilde F(z)=$","o":["A. $F(\\sqrt z)$","B. $F(z^2)$","C. $\\frac12[F(z)+F(-z)]$","D. $\\frac12[F(z)-F(-z)]$"],"img":"pro-img/final-sig_p04.jpg","a":"B","s":"$\\tilde F(z)=\\sum_k \\tilde f(k)z^{-k}=\\sum_n f(n)z^{-2n}=F(z^2)$，选 B。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-12","seq":12,"part":"信号","qt":"选择","pts":3,"ch":"ss-freq","q":"信号 $f(t)$ 如图4所示。若 $f(t)\\leftrightarrow F(j\\omega)$，则 $\\int_{-\\infty}^{\\infty}F(j\\omega)d\\omega=$","o":["A. $4\\pi$","B. $2\\pi$","C. $12\\pi$","D. $3\\pi$"],"img":"pro-img/final-sig_p04.jpg","a":"A","s":"由反变换 $f(0)=\\frac{1}{2\\pi}\\int_{-\\infty}^{\\infty}F(j\\omega)d\\omega$，故 $\\int F(j\\omega)d\\omega=2\\pi f(0)$；由图4 $f(0)=2$，结果为 $4\\pi$，选 A。（选项 A/B 数值 OCR 不清，$f(0)$ 由图4与第14题答案反推）","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-13","seq":13,"part":"信号","qt":"选择","pts":3,"ch":"ss-sdomain","q":"某模拟滤波器系统函数 $H(s)$ 的零、极点分布图如图5所示。[题5图：零点位于虚轴 $s=\\pm j100$，极点分布见图]。该滤波器是：","o":["A. 低通滤波器；","B. 高通滤波器；","C. 带通滤波器；","D. 带阻滤波器。"],"img":"pro-img/final-sig_p04.jpg","a":"C","s":"由零极点分布：零点位于虚轴 $s=\\pm j100$、极点位于左半平面，$|H(j\\omega)|$ 在 $\\omega=0$ 及 $\\omega\\to\\infty$ 处趋于零，在 $\\omega\\approx100$ 附近最大，故为带通滤波器，选 C。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-14","seq":14,"part":"信号","qt":"解答","pts":19,"ch":"ss-freq","q":"画图和计算题（共 19 分）：\n(1)（8 分）信号 $f(t)$ 如图4所示。[题4图：门形/梯形信号，$f(t)=2\\ (0<t<1)$，$f(-0.3)=1.4$]。\na) 请画出 $f'(t)=\\dfrac{\\mathrm{d}f(t)}{\\mathrm{d}t}$ 的波形；\nb) 请定性画出信号 $f_1(t)=f(t)\\varepsilon(t)$ 的幅频特性 $|F_1(j\\omega)|$ 曲线；\nc) 若 $f(t)\\leftrightarrow F(j\\omega)$，不计算傅里叶变换，试确定积分 $\\int_{-\\infty}^{\\infty}F(j\\omega)e^{-j0.3\\omega}d\\omega$。\n(2)（6 分）离散 LTI 复合系统如图6所示。[题6图：$h_1(k)$、$h_2(k)$、$h_3(k)$ 的复合系统框图]。已知 $h_1(k)=\\varepsilon(k)$，$h_2(k)=\\delta(k-3)$，$h_3(k)=\\delta(k-1)$，试画出该复合系统单位序列响应 $h(k)$ 和单位阶跃响应 $g(k)$ 的波形。\n(3)（5 分）已知某连续 LTI 系统的幅频响应和相频响应曲线如图7所示。[题7图：$|H(j\\omega)|$ 平坦、$\\varphi(\\omega)$ 线性的理想信道特性]，$H(j\\omega)=|H(j\\omega)|e^{j\\varphi(\\omega)}$。试确定以 $f(t)=\\cos^2(2\\pi t)$ 作为系统输入时，该系统是否会对输入 $f(t)$ 造成波形失真？并分别画出输入 $f(t)$ 和输出 $y(t)$ 的波形。","img":"pro-img/final-sig_p05.jpg","a":"(1)a $f'(t)=2[\\varepsilon(t+1)-\\varepsilon(t)]-2\\delta(t-1)$；b $F_1(j\\omega)=2\\mathrm{Sa}(\\frac{\\omega}{2})$；c $\\int F(j\\omega)e^{-j0.3\\omega}d\\omega=2.8\\pi$。(2) $h(k)=\\delta(k-1)+\\delta(k-2)+\\delta(k-3)$，$g(k)=\\varepsilon(k-1)+\\varepsilon(k-2)+\\varepsilon(k-3)$。(3) 不会失真。","s":"(1)a $f'(t)=2[\\varepsilon(t+1)-\\varepsilon(t)]-2\\delta(t-1)$（$t=1$ 处冲激不画只给 1 分）。\nb) $f_1(t)=f(t)\\varepsilon(t)=2g_1(t)$，$F_1(j\\omega)=2\\mathrm{Sa}(\\frac{\\omega}{2})$，幅频特性为峰值 2、零点在 $\\omega=\\pm2\\pi,\\pm4\\pi,\\pm6\\pi,\\dots$ 的 $|\\mathrm{Sa}|$ 型曲线。\nc) 由反变换 $f(t)=\\frac1{2\\pi}\\int F(j\\omega)e^{j\\omega t}d\\omega$，故 $\\int_{-\\infty}^{\\infty}F(j\\omega)e^{-j0.3\\omega}d\\omega=2\\pi f(-0.3)=2\\pi\\times1.4=2.8\\pi$。\n(2) 由框图 $h(k)=[h_1(k)-h_2(k)]*h_3(k)=[\\varepsilon(k)-\\delta(k-3)]*\\delta(k-1)=\\delta(k-1)+\\delta(k-2)+\\delta(k-3)$；$g(k)=\\sum_{i=-\\infty}^{k}h(i)=\\varepsilon(k-1)+\\varepsilon(k-2)+\\varepsilon(k-3)$。\n(3) $f(t)=\\cos^2(2\\pi t)=\\frac12[1+\\cos(4\\pi t)]$，只含直流（$\\omega=0$）与 $\\omega=4\\pi$ 成分；题设滤波器幅频平坦、相频线性，故不造成波形失真。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-15","seq":15,"part":"信号","qt":"解答","pts":5,"ch":"ss-freq","q":"证明题（5 分）：连续时间理想冲激采样系统如图8所示。[题8图：$f(t)$ 经乘法器与采样脉冲序列 $p(t)$ 相乘得 $y(t)$]。即：系统输入（被采样信号）为 $f(t)$，采样输出 $y(t)=f(t)p(t)$，采样脉冲序列 $p(t)=\\sum_{n=-\\infty}^{\\infty}\\delta(t-nT_s)$，$T_s$ 为采样周期。试证明：采样输出 $y(t)$ 的傅里叶变换 $Y(j\\omega)$ 为 $Y(j\\omega)=\\frac{1}{T_s}\\sum_{n=-\\infty}^{\\infty}F[j(\\omega-n\\omega_s)]$，其中 $\\omega_s=\\frac{2\\pi}{T_s}$ 是采样角频率；$F(j\\omega)$ 是 $f(t)$ 的傅里叶变换。若 $f(t)$ 是带限信号，最高频率为 $f_m$（Hz），欲使采样输出 $y(t)$ 的频谱不发生混叠，请给出采样频率 $f_s=\\frac{1}{T_s}$ 需满足的条件。","img":"pro-img/final-sig_p07.jpg","a":"$Y(j\\omega)=\\frac1{T_s}\\sum_{n}F[j(\\omega-n\\omega_s)]$；无混叠条件 $f_s>2f_m$（写 $f_s\\ge2f_m$ 不扣分）","s":"冲激串的傅里叶变换 $P(j\\omega)=\\omega_s\\sum_{n}\\delta(\\omega-n\\omega_s)$，$\\omega_s=\\frac{2\\pi}{T_s}$。由频域卷积定理 $y(t)=f(t)p(t)\\leftrightarrow Y(j\\omega)=\\frac1{2\\pi}F(j\\omega)*P(j\\omega)=\\frac1{2\\pi}F(j\\omega)*\\omega_s\\sum_n\\delta(\\omega-n\\omega_s)=\\frac1{T_s}\\sum_nF[j(\\omega-n\\omega_s)]$。由采样定理，无混叠要求 $f_s>2f_m$。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-16","seq":16,"part":"信号","qt":"解答","pts":16,"ch":"ss-state","q":"计算题（16 分）：描述某 LTI 因果连续系统的微分方程为 $y''(t)+2y'(t)+y(t)=f'(t)+2f(t)$，已知 $y(0_-)=1$ 和 $y'(0_-)=0$，$f(t)=\\sin(t)\\varepsilon(t)$。试计算和确定：\n(1) $y_x(t)$、$y_f(t)$ 和全响应 $y(t)$；\n(2) 指出 $y(t)$ 中的暂态响应和稳态响应；\n(3) 写出该系统的系统函数 $H(s)$，并画出系统的直接 I 型信号流图；\n(4) 结合所得信号流图，以积分器输出端作为状态变量，自左至右依次设定为 $x_1(t)$ 和 $x_2(t)$。写出该系统的状态方程和输出方程（矩阵形式）。","img":"pro-img/final-sig_p07.jpg","a":"$y_x(t)=(t+1)e^{-t}\\varepsilon(t)$；$y_f(t)=[(1+\\frac t2)e^{-t}+\\frac12\\sin t-\\cos t]\\varepsilon(t)$；$y(t)=[(\\frac{3t}{2}+2)e^{-t}+\\frac12\\sin t-\\cos t]\\varepsilon(t)$；暂态 $(\\frac{3t}{2}+2)e^{-t}\\varepsilon(t)$，稳态 $(\\frac12\\sin t-\\cos t)\\varepsilon(t)$；$H(s)=\\frac{s+2}{(s+1)^2}$；状态方程与输出方程见解析。","s":"(1) 对方程取单边拉氏变换：$s^2Y-sy(0_-)-y'(0_-)+2[sY-y(0_-)]+Y=sF+2F$，代入 $y(0_-)=1,y'(0_-)=0$，$F(s)=\\frac1{s^2+1}$。零输入 $Y_x(s)=\\frac{s+2}{(s+1)^2}=\\frac1{s+1}+\\frac1{(s+1)^2}$，故 $y_x(t)=(t+1)e^{-t}\\varepsilon(t)$；零状态 $Y_f(s)=\\frac{s+2}{(s+1)^2(s^2+1)}=\\frac1{s+1}+\\frac{1/2}{(s+1)^2}-\\frac{s}{s^2+1}+\\frac{1/2}{s^2+1}$，故 $y_f(t)=[(1+\\frac t2)e^{-t}-\\cos t+\\frac12\\sin t]\\varepsilon(t)$；$y(t)=y_x+y_f=[(\\frac{3t}{2}+2)e^{-t}+\\frac12\\sin t-\\cos t]\\varepsilon(t)$。\n(2) 暂态响应 $(\\frac{3t}{2}+2)e^{-t}\\varepsilon(t)$；稳态响应 $(\\frac12\\sin t-\\cos t)\\varepsilon(t)=\\frac{\\sqrt5}{2}\\sin(t-\\arctan2)\\varepsilon(t)$（$\\arctan2\\approx63.43^\\circ$）。\n(3) $H(s)=\\frac{s+2}{s^2+2s+1}=\\frac{s^{-1}+2s^{-2}}{1+2s^{-1}+s^{-2}}$，由梅森公式得直接 I 型信号流图（如题解图6）。\n(4) 以两积分器输出（左→右）为 $x_1,x_2$：状态方程 $\\begin{bmatrix}\\dot x_1\\\\ \\dot x_2\\end{bmatrix}=\\begin{bmatrix}-2&-1\\\\1&0\\end{bmatrix}\\begin{bmatrix}x_1\\\\x_2\\end{bmatrix}+\\begin{bmatrix}1\\\\0\\end{bmatrix}f(t)$；输出方程 $y(t)=\\begin{bmatrix}1&2\\end{bmatrix}\\begin{bmatrix}x_1\\\\x_2\\end{bmatrix}$。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-17","seq":17,"part":"信号","qt":"解答","pts":9,"ch":"ss-zdomain","q":"计算题（9 分）：某 LTI 离散因果系统的模拟框图如图9所示。[题9图：含系数 $\\frac1{16}$、$\\frac38$ 反馈与前馈的离散系统模拟框图]。\n(1) 写出描述该系统的差分方程，并确定系统函数 $H(z)$；\n(2) 求系统的单位序列响应 $h(k)$；\n(3) 判定系统的稳定性。","img":"pro-img/final-sig_p09.jpg","a":"$H(z)=\\frac{1-0.0625z^{-2}}{1+0.25z^{-1}-0.375z^{-2}}=\\frac{(z+0.25)(z-0.25)}{(z+0.75)(z-0.5)}$；差分方程 $y(k)+0.25y(k-1)-0.375y(k-2)=f(k)-0.0625f(k-2)$；$h(k)=\\frac16\\delta(k)+\\frac8{15}(-0.75)^k\\varepsilon(k)+\\frac3{10}(0.5)^k\\varepsilon(k)$；系统稳定。","s":"(1) 由模拟框图与梅森公式（考虑因果性）$H(z)=\\frac{1-0.0625z^{-2}}{1+0.25z^{-1}-0.375z^{-2}}=\\frac{(z+0.25)(z-0.25)}{(z+0.75)(z-0.5)}$，收敛域 $|z|>0.75$；差分方程 $y(k)+0.25y(k-1)-0.375y(k-2)=f(k)-0.0625f(k-2)$。\n(2) $\\frac{H(z)}z=\\frac{(z+0.25)(z-0.25)}{z(z+0.75)(z-0.5)}=\\frac{1/6}{z}+\\frac{8/15}{z+0.75}+\\frac{3/10}{z-0.5}$，故 $h(k)=\\frac16\\delta(k)+\\frac8{15}(-0.75)^k\\varepsilon(k)+\\frac3{10}(0.5)^k\\varepsilon(k)$。\n(3) 因果有理系统，极点 $z=-0.75$、$z=0.5$ 均在单位圆内，故系统稳定。","t":"期末","y":2022,"src":"西电信号2022期末"},{"id":"fs22-18","seq":18,"part":"信号","qt":"解答","pts":7,"ch":"ss-freq","q":"计算、画图题（7 分）：模拟通信中的双边带（DSB）调制解调系统原理框图如图10所示。[题10图：发送端调制 $y_1(t)=f(t)s_1(t)$ → 信道 $h_c(t)$ → 接收端相干解调 $y_2(t)=y_1(t)s_2(t)$ → 低通 $h(t)$ → $y_3(t)$]。其中 $y_1(t)=f(t)s_1(t)$ 是发送端的调制环节；冲激响应为 $h_c(t)$ 的系统是通信信道；$y_2(t)=y_1(t)s_2(t)$ 以及后面级联的冲激响应为 $h(t)$ 的系统构成了接收端的相干解调环节。现具体信号和系统参数如下：(1) 调制信号 $f(t)=2\\mathrm{Sa}(2\\pi t)$；(2) 发、收端的载波 $s_1(t)=s_2(t)=\\cos(2000\\pi t)$；(3) $h_c(t)=\\delta(t)$——信道是理想的，$h(t)=6\\mathrm{Sa}(3\\pi t)$。请写出 $F(j\\omega)$ 和 $H(j\\omega)$ 的表达式，并画出 $Y_1(j\\omega)$、$Y_2(j\\omega)$、$Y_3(j\\omega)$。","img":"pro-img/final-sig_p10.jpg","a":"$F(j\\omega)=g_{4\\pi}(\\omega)$（$|\\omega|<2\\pi$）；$H(j\\omega)=2g_{6\\pi}(\\omega)$（$|\\omega|<3\\pi$）；$Y_1(j\\omega)=\\frac12[F(j(\\omega+2000\\pi))+F(j(\\omega-2000\\pi))]$；$Y_2(j\\omega)=\\frac12F(j\\omega)+\\frac14[F(j(\\omega+4000\\pi))+F(j(\\omega-4000\\pi))]$；$Y_3(j\\omega)=F(j\\omega)=g_{4\\pi}(\\omega)$，$y_3(t)=f(t)$。","s":"$f(t)=2\\mathrm{Sa}(2\\pi t)\\Rightarrow F(j\\omega)=g_{4\\pi}(\\omega)$（门宽 $4\\pi$，即 $|\\omega|<2\\pi$）；$h(t)=6\\mathrm{Sa}(3\\pi t)\\Rightarrow H(j\\omega)=2g_{6\\pi}(\\omega)$（$|\\omega|<3\\pi$）。$y_1(t)=f(t)\\cos(2000\\pi t)\\Rightarrow Y_1(j\\omega)=\\frac12[F(j(\\omega+2000\\pi))+F(j(\\omega-2000\\pi))]$（$\\pm2000\\pi$ 处各半幅门）。信道理想故 $Y_1$ 不变；$y_2(t)=y_1(t)\\cos(2000\\pi t)\\Rightarrow Y_2(j\\omega)=\\frac12F(j\\omega)+\\frac14[F(j(\\omega+4000\\pi))+F(j(\\omega-4000\\pi))]$。经低通 $H(j\\omega)=2g_{6\\pi}(\\omega)$ 滤除 $\\pm4000\\pi$ 成分：$Y_3(j\\omega)=\\frac12F(j\\omega)\\cdot2=F(j\\omega)=g_{4\\pi}(\\omega)$，故 $y_3(t)=f(t)$，实现无失真解调。","t":"期末","y":2022,"src":"西电信号2022期末"}]};
